(window.GIM_TS=window.GIM_TS||{})["Shabbat.12"]={"from":288,"a":[["\u0003שבא\u0004 ה\u0003נחש על חוה\u0004 כשפתה אותה לאכול מעץ הדעת \u0003הטיל בה זוהמא,\u0004 וזוהמה זו נשארה קיימת בכל בני האדם, אלא \u0003ישראל שעמדו על הר סיני\u0004 — \u0003פסקה זוהמתן,\u0004 ואילו \u0003גוים\u0004 כיון \u0003שלא עמדו על הר סיני\u0004 — \u0003לא פסקה זוהמתן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: גרים מאי\u0004 \u0005[מה]?\u0006 כיצד תסביר את ביטול זוהמתן? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אף על גב דאינהו\u0004 \u0005[אף על פי שהם\u0006 עצמם\u0005]\u0006 \u0003לא הוו\u0004 \u0005[היו]\u0006 בהר סיני מכל מקום \u0003מזלייהו הוו\u0004 \u0005[מזלם היה].\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ולא אתכם לבדכם אנכי כורת את הברית הזאת ואת האלה הזאת כי \u0003את אשר ישנו פה עמנו עמד היום לפני ה' אלהינו ואת אשר איננו פה\u0004 עמנו היום\" (דברים כט, יג–יד) — להביא את הגרים.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003ר' אבא בר כהנא\u0004 ש\u0003אמר: עד שלשה דורות לא פסקה\u0004 אותה \u0003זוהמא מאבותינו: אברהם הוליד את ישמעאל,\u0004 שלא היה הגון. \u0003יצחק הוליד את עשו,\u0004 ורק \u0003יעקב הוליד שנים עשר שבטים שלא היה בהן שום דופי,\u0004 הרי שהוא סבור שפסקה זוהמה מאבות האומה עוד לפני מעמד הר סיני.","\u0003שובר אדם\u0004 בשבת \u0003את החבית\u0004 כדי \u0003לאכול הימנה גרוגרות\u0004 (תאנים יבשות) \u0003ובלבד שלא יתכוין לעשות כלי. ואין נוקבין מגופה של חבית\u0004 כדי להוציא ממנה את היין, אלא מורידים את המגופה כולה, שעל ידי כך אינו יוצר פתח חדש, אלו \u0003דברי ר' יהודה. וחכמים מתירין,\u0004 ואולם אף הם הגבילו את הדבר אמרו ש\u0003לא יקבנה\u0004 למגופת החבית \u0003מצדה. ואם היתה נקובה\u0004 כבר, מכל מקום \u0003לא יתן עליה שעוה\u0004 לסתום את הנקב, \u0003מפני ש\u0004בשעת נתינת השעוה \u0003הוא ממרח\u0004 ועושה מלאכה אסורה של הממחק. \u0003אמר ר' יהודה: מעשה\u0004 כעין זה \u0003בא לפני רבן יוחנן בן זכאי ב\u0004עיר \u0003ערב, ואמר: חוששני לו\u0004 שמא נתחייב על ידי כך בקרבן \u0003חטאת .\u0004","\u0003אמר ר' אושעיא: לא שנו\u0004 שמותר לשבור את החבית \u0003אלא\u0004 כשהיו התאנים \u0003דרוסות\u0004 ודבוקות זו לזו בחזקה, שכיון שמותר לו לקחת כלי לחתוך ולהפריד את התאנים הדבוקות, אף מותר לו להשתמש בכלי זה בשבירת החבית, \u0003אבל\u0004 אם היו התאנים \u0003מפורדות\u0004 — \u0003לא,\u0004 שאסור לו לטלטל כלי לצורך פתיחת החבית בלבד. ושואלים: \u0003ו\u0004כי \u0003מפורדות\u0004 אסור לפתוח?","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה \u0003ששנינו, רבן שמעון בן גמליאל אומר: מביא אדם את החבית של יין ומתיז ראשה בסייף, ומניחה לפני האורחים בשבת ואינו חושש\u0004 משום טלטול ומשום יצירת כלי, והרי שמותר לטלטל בשבת כלי רק לצורך פתיחת החבית! ומתרצים לשיטת ר' אושעיא: הברייתא \u0003ההיא\u0004 של רבן שמעון בן גמליאל כשיטת \u0003רבנן\u0004 \u0005[חכמים ]\u0006 היא, ואילו \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 לשיטת \u0003ר' נחמיה היא,\u0004 שאמר שאסור לטלטל כל כלי בשבת אלא לצורכי מלאכתו המיוחדת לו בלבד.","ושואלים: \u0003ומאי דוחקיה\u0004 \u0005[ומה דוחקו]\u0006 של \u0003ר' אושעיא לאוקמי מתניתין\u0004 \u0005[להעמיד\u0006 את \u0005משנתנו]\u0006 \u0003כ\u0004דעת היחיד של \u0003ר' נחמיה וב\u0004תאנים \u0003דרוסות\u0004 דווקא? \u0003לוקמה\u0004 \u0005[שיעמידנה]\u0006 אף \u0003במפורדות ורבנן\u0004 \u0005[ו\u0006כשיטת \u0005חכמים]!\u0006 \u0003אמר רבא, מתניתין קשיתיה\u0004 \u0005[משנתנו\u0006 היתה \u0005קשה לו]:\u0006 \u0003מאי איריא דתני\u0004 \u0005[מה שייך\u0006 דווקא \u0005ששנה]\u0006 \u0003\"גרוגרות\"? ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"פירות\"\u0004 סתם! \u0003אלא שמע מינה\u0004 \u0005[למד ממנה]\u0006 שדיבר \u0003ב\u0004גרוגרות \u0003דרוסות\u0004 דווקא, משום שלצורכן מותר לו לטלטל כלי ואגב כך גם לפתוח בו את החבית.","\u0003תניא חדא:\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003חותלות\u0004 (סלים קלועים וסגורים) \u0003של גרוגרות ושל תמרים\u0004 — \u0003מתיר\u0004 בשבת את קשר הסל, \u0003ומפקיע\u0004 (פותח את הקליעה), \u0003וחותך. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מתיר אבל לא מפקיע ולא חותך,\u0004 והרי זו סתירה בין הברייתות! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המתירה — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, ואילו \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האוסרת — לשיטת \u0003ר' נחמיה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' נחמיה אומר: אפילו תרווד\u0004 (כף גדולה) \u0003ואפילו טלית, ואפילו סכין\u0004 — \u0003אין ניטלין\u0004 בשבת \u0003אלא לצורך תשמישן\u0004 המיוחד להם, ואסור לטלטל סכין כדי לחתוך את חותלות הפירות.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 התלמידים \u0003מרב ששת: מהו\u0004 הדין לענין ההיתר \u0003למיברז חביתא בבורטיא בשבתא\u0004 \u0005[לנקוב חבית ברומח בשבת],\u0006 האם \u0003לפיתחא קמיכוין, ואסיר\u0004 \u0005[ל\u0006עשות \u0005פתח\u0006 בחבית \u0005הוא מתכוין, ואסור],\u0006 \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003ל\u0004הראות \u0003עין יפה קמיכוין, ושרי\u0004 \u0005[הוא מתכוין, ומותר]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ששת: \u0003לפיתחא קא מכוין, ואסיר\u0004 \u0005[ל\u0006עשות \u0005פתח\u0006 בחבית \u0005הוא מתכוין, ואסור].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו ש\u0003רבן שמעון בן גמליאל אומר: מביא אדם\u0004 בשבת \u0003חבית של יין ומתיז\u0004 את \u0003ראשה בסייף,\u0004 ומדוע אם כן אסר רב ששת לפתוח חבית אחרת ברומח? ענה להם: \u0003התם\u0004 שעל יד כך מקלקל את החבית, \u0003ודאי לעין יפה קמיכוין\u0004 \u0005[הוא מתכוון],\u0006 ומראה שהוא שובר חבית במיוחד עבור אורחים אלה, ואולם \u0003הכא\u0004 בנקיבת חבית אחרת ברומח — \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר ש\u0003לעין יפה קמיכוין\u0004 \u0005[הוא\u0006 \u0003מתכוין]\u0004 אם כן \u0003לפתוחי מיפתח\u0004 \u0005[שיפתח]\u0006 את מגופתה, ומאחר שרק נוקבה אינו מראה בכך רוחב לב, אלא כוונתו לעשות חור קטן דווקא.","שנינו במשנה שלדעת ר' יהודה \u0003אין נוקבין מגופה\u0004 של חבית בשבת וחכמים מתירים. \u0003אמר רב הונא: מחלוקת\u0004 זו היא רק באופן שרוצה לעשות נקב \u0003למעלה,\u0004 בראש המגופה, \u0003אבל\u0004 אם רוצה לעשות נקב \u0003מן הצד\u0004 — ל\u0003דברי הכל אסור,\u0004 שכן דרך לנקוב לפעמים חבית מתחת למגופה באופן זה. \u0003והינו דקתני\u0004 \u0005[וזהו ששנינו]:\u0006 \u0003\"לא יקבנה מצדה\". ו\u0004אילו \u0003רב חסדא אמר: מחלוקת\u0004 זו היא באופן שרוצה לעשות את הנקב \u0003מן הצד, אבל\u0004 כאשר רוצה לעשות אותו \u0003על גבה\u0004 — ל\u0003דברי הכל מותר. והא דקתני\u0004 \u0005[וזו ששנינו]\u0006 \u0003\"לא יקבנה מצדה\"\u0004 — \u0003התם\u0004 \u0005[שם]\u0006 מדובר בנוקב \u0003בגופה\u0004 של ה\u0003חבית\u0004 עצמה ולא במגופה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא\u0005]:\u0006 \u0003אין נוקבין נקב חדש בשבת\u0004 בכל כלי, \u0003ואם בא להוסיף\u0004 ולהרחיב נקב ישן — \u0003מוסיף. ויש אומרים:\u0004 אף \u0003אין מוסיפין. ושוין\u0004 כולם בדעתם, ואף האוסרים מודים \u0003שנוקבין נקב ישן\u0004 שנסתם אפילו \u0003לכתחילה. ו\u0004לשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 נקיבת נקב ישן שנסתם שמותר \u0003מנקב חדש\u0004 ש\u0003לא\u0004 הותר לעשותו — משום \u0003דקא\u0004 \u0005[ש\u0006בכך \u0005הוא]\u0006 \u0003מתקן פיתחא\u0004 \u0005[פתח],\u0006 ואולם אם כן הרי ב\u0003אוסופי נמי קא\u0004 \u0005[\u0006ב\u0005הוספת\u0006 והגדלת נקב הרי \u0005גם כן הוא]\u0006 \u0003מתקן פיתחא\u0004 \u0005[פתח]!\u0006","\u0003אמר רבה:\u0004 לאמיתו של דבר אף עשיית הנקב הראשונה אינה אסורה, כי \u0003דבר תורה\u0004 — \u0003כל פתח שאינו עשוי להכניס ולהוציא\u0004 כדוגמת נקב שבחבית שאינו עשוי אלא להוציא — \u0003אינו פתח, ורבנן הוא דגזור\u0004 \u0005[וחכמים הם שגזרו]\u0006 שלא לעשות נקב בכלי \u0003משום\u0004 שדומה הדבר לנקב ב\u0003לול של תרנגולין,\u0004 ונקב זה שבלול אסור מן התורה שהוא פתח גמור העשוי להכניס ולהוציא, \u0003דעביד לעיולי אוירא ולאפוקי הבלא\u0004 \u0005[שעשוי להכניס אויר ולהוציא חום].\u0006 \u0003ו\u0004לכן אף שנינו ש\u0003אם בא להוסיף\u0004 ולהרחיב נקב קיים — \u0003מוסיף,\u0004 שאין מקום לגזור כאן משום לול, שכן \u0003אוסופי\u0004 \u0005[להוסיף]\u0006 \u0003ודאי בלול של תרנגולים\u0004 — \u0003לא אתי לאוסופי\u0004 \u0005[יבוא להוסיף]\u0006"],["\u0003משום ריחשא\u0004 \u0005[שרצים]\u0006 שלא יכנסו דרכו ללול. \u0003ו\u0004מה ששנינו ש\u0003יש אומרים\u0004 ש\u0003אין מוסיפים,\u0004 אף הם טעמם משום גזירת לול תרנגולים, והם מסבירים: \u0003זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003לא תקניה מעיקרא\u0004 \u0005[תקנו מתחילה]\u0006 לנקב זה, \u0003ואתי לארוחי ביה\u0004 \u0005[ובא ל\u0006עשותו \u0005מרווח\u0006 יותר\u0005],\u0006 שרק על ידי הרחבה זו נעשה הפתח ראוי לשימוש. ונמצא שבאותו זמן נעשה הפתח. \u0003דרש רב נחמן משום רבי יוחנן הלכה כיש אומרים.\u0004","בברייתא שנינו: \u0003ושוין\u0004 בדעתם המחמירים למקילים \u0003ש\u0004לדעת הכל \u0003נוקבין\u0004 בשבת \u0003נקב ישן\u0004 שנסתם \u0003לכתחלה. אמר רב יהודה\u0004 שכך \u0003אמר שמואל: לא שנו\u0004 שנוקבים \u0003אלא במקום העשוי לשמר\u0004 (להוציא את היין מן השמרים, לסננו), \u0003אבל\u0004 אם היה עשוי \u0003לחזק\u0004 את הכלי — \u0003אסור\u0004 (גאונים). ושואלים: \u0003היכי דמי\u0004 \u0005[איך בדיוק]\u0006 נחשב \u0003לשמר, היכי דמי\u0004 \u0005[איך בדיוק]\u0006 נחשב \u0003לחזק? אמר רב חסדא:\u0004 אם נוקב בחבית \u0003למעלה מן היין\u0004 — \u0003זהו לשמר,\u0004 ואם נוקב \u0003למטה מן היין\u0004 — \u0003זהו לחזק. רבא אמר: למטה מן היין נמי\u0004 \u0005[גם כן]\u0006 \u0003זהו\u0004 נחשב \u0003לשמר. והיכי דמי\u0004 \u0005[ואיך בדיוק]\u0006 נחשב \u0003לחזק\u0004 — \u0003כגון שניקבה\u0004 החבית \u0003למטה מן השמרים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת]\u0006 \u0003לך,\u0004 לשיטתך, שפתח דינו תמיד כפתח אלא אם כן מוכח באופן שאין בו ספק, שאינו משמש עוד לצורך זה. ששנינו: כאשר מחלקים חצר בין בעלי הבתים שבתוכה מקבל כל בעל בית, נוסף לחלקו בחצר, גם ארבע אמות ליד כל פתח של ביתו. ואמרו: כי \u0003בית סתום,\u0004 שסתמו אחד מפתחיו — \u0003יש לו ארבע אמות\u0004 לאותו פתח, כיון שהפתח עשוי לחזור ולהפתח, ורק אם \u0003פרץ את פצימיו\u0004 (מזוזותיו) של הפתח וסתמו, בטלה תורת פתח לגמרי — ו\u0003אין לו ארבע אמות,\u0004 שפריצת הפצימים מוכיחה שביטל פתח זה לחלוטין. וכן בדיני טומאה: בית שהיה בו מת מטמא רק כנגד פתחיו, ואף \u0003בית סתום\u0004 שסתם את פתחו — \u0003אינו מטמא\u0004 את \u0003כל סביביו,\u0004 אלא כנגד פתחו בלבד, ואולם אם \u0003פרץ את פצימיו\u0004 שוב אין כאן פתח — ובית זה \u0003מטמא כל סביביו\u0004 במגע כקבר סתום.","בענין \u0003גובתא\u0004 \u0005[קנה]\u0006 שמכניסים בנקב החבית להוציא משם את היין, \u0003רב אסר ושמואל שרי\u0004 \u0005[התיר].\u0006 ומפרטים: \u0003מחתך לכתחלה\u0004 ומתקין קנה זה — \u0003דכולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 ש\u0003אסור,\u0004 לפי שיש בכך עשיית כלי ממש. \u0003אהדורי\u0004 — \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[להחזיר\u0006 למקומו קנה מוכן, \u0005הכל אינם חלוקים שמותר].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר\u0006 נחלקו] היה זה \u0003דחתיכה ולא מתקנא\u0004 \u0005[\u0006כ\u0005ש\u0006הקנה \u0005חתוך ואינו מותקן].\u0006 \u0003מאן דאסר\u0004 \u0005[מי שאוסר,\u0006 רב\u0005]\u0006 סבור כי \u0003גזרינן דלמא אתי למיחתך\u0004 \u0005[גוזרים אנו שמא יבוא לחתוך]\u0006 \u0003לכתחלה\u0004 קנה לצורך זה. \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר,\u0006 שמואל\u0005]\u0006 סבור כי \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006","ומעירים: מחלוקת רב ושמואל בענין זה הריהי \u0003כתנאי\u0004 \u0005[כתנאים],\u0006 שכבר נחלקו בדבר זה. ששנינו: \u0003אין חותכין שפופרת\u0004 של קנה \u0003ביום טוב, ואין צריך לומר\u0004 שאסור לחותכה \u0003בשבת.\u0004 ואם היתה חתוכה כבר אלא ש\u0003נפלה\u0004 ממקומה — \u0003מחזירין אותה בשבת, ואין צריך לומר\u0004 שמותר להחזירה \u0003ביום טוב. ור' יאשיה מיקל.\u0004","ושואלים: \u0003ר' יאשיה אהייא\u0004 \u0005[על מה\u0006 מוסבים דבריו\u0005],\u0006 \u0003אילימא ארישא\u0004 \u0005[אם תאמר\u0006 שהוא מדבר על \u0005ראש\u0006 הברייתא\u0005],\u0006 בענין חיתוך שפופרת — איך הוא מיקל, \u0003הא קמתקן מנא\u0004 \u0005[הרי\u0006 בכך \u0005הוא מתקן כלי]\u0006 וכיצד יתיר מלאכה ממש? \u0003אלא\u0004 תאמר כי הוא מדבר \u0003אסיפא\u0004 \u0005[על הסוף]\u0006 בענין החזרת השפופרת שנפלה למקומה — והלא \u0003התנא קמא נמי מישרא קשרי\u0004 \u0005[הראשון גם כן מתיר],\u0006 ומה יש להקל עוד בדבר? \u0003אלא\u0004 ודאי באופן \u0003דחתיכה ולא מתקנא איכא בינייהו\u0004 \u0005[שחתוכה ואינה מותקנת יש ביניהם\u0006 מחלוקת\u0005],\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 התנא קמא \u0005סבור]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 איסור בכך. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יאשיה \u0005סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים].\u0006 ומסכמים: \u0003דרש רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 בפומבי \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: הלכה כר' יאשיה.\u0004","\u0003ו\u0004עוד שנינו במשנה ש\u0003אם היתה\u0004 החבית \u0003נקובה\u0004 — אסור לסתום אותו נקב בשעוה. ושנינו שנחלקו אמוראים אם מותר לסתום נקב ב\u0003מישחא\u0004 \u0005[שמן],\u0006 ש\u0003רב אסר, ושמואל שרי\u0004 \u0005[התיר].\u0006 ומסבירים: \u0003מאן דאסר\u0004 \u0005[מי שאוסר,\u0006 רב\u0005]\u0006 — לדעתו \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 איסור אף בשמן \u0003משום שעוה. ומאן דשרי\u0004 \u0005[ומי שהתיר,\u0006 שמואל\u0005]\u0006 — לדעתו \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 בשמן משום שעוה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר בר חנה לרב יוסף:\u0004 איך מביאים משם רב לאסור סתימת נקב החבית בשבת בשמן, והלא \u0003בפירוש אמרת לן משמיה\u0004 \u0005[לנו משמו]\u0006 של \u0003רב\u0004 כי \u0003מישחא שרי\u0004 \u0005[שמן מותר]\u0006 לסתום בו!","ומביאים עוד מה ש\u0003אמר טבות רישבא\u0004 \u0005[הצייד]\u0006 שכך \u0003אמר שמואל: האי טרפא דאסא\u0004 \u0005[עלה זה של הדס]\u0006 — \u0003אסור\u0004 לשים אותו כמרזב בנקב חבית. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003רב יימר מדפתי אמר: גזירה\u0004 היא שגזרו \u0003משום\u0004 החשש שמא יבוא לעשות \u0003מרזב\u0004 ממש לצורך זה. \u0003רב אשי אמר: גזירה\u0004 היא \u0003שמא יקטום\u0004 לצורך זה עלה מענף ההדס. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה באופן \u0003דקטים ומנחי\u0004 \u0005[שקטומים\u0006 העלים מכבר \u0005ומונחים],\u0006 ואינו צריך לקטום עלים נוספים לצורך זה, שבמקרה כזה מתיר רב אשי, ולדעת רב יימר אף בכגון זה אסור.","ודבר נוסף שנחלקו בו רב ושמואל: \u0003בי סדיא\u0004 \u0005[לבדים]\u0006 שנוהגים בדרך כלל לשבת עליהם, אבל אפשר גם להתעטף בהם, שנחלקו חכמים אם מותר בשבת להתעטף בהם ולהעבירם ממקום למקום דרך רשות הרבים, \u0003רב אסר ושמואל שרי\u0004 \u0005[מתיר].\u0006 ומפרטים: \u0003ב\u0004לבדים \u0003רכין\u0004 — \u0003דכולי עלמא לא פליגי דשרי\u0004 \u0005[הכל אינם חלוקים שמותר]\u0006 שהם כשאר לבושים. \u0003בקשין\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אסור. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 — היה זה \u0003במיצעי\u0004 \u0005[בממוצעים]:\u0006 \u0003מאן דאסר\u0004 \u0005[מי שאוסר,\u0006 רב\u0005]\u0006 הרי זה משום שלדעתו הלובש בגדים אלו — \u0003מיחזי כמשוי\u0004 \u0005[נראה כ\u0006נושא \u0005משא],\u0006 \u0003ומאן דשרי\u0004 \u0005[ומי שמתיר,\u0006 שמואל\u0005]\u0006 הרי זה משום שלדעתו \u0003לא מיחזי כמשוי\u0004 \u0005[נראה כ\u0006נושא \u0005משא],\u0006 אלא כמלבוש.","ומעירים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 של \u0003רב לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמר]\u0006 על ידו \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 דברים אחרים שנהג \u0005נאמר,\u0006 הובן\u0005]\u0006 שזו דעתו. ש\u0003רב איקלע לההוא אתרא\u0004 \u0005[הזדמן למקום אחד]\u0006 ש\u0003לא הוה ליה רווחא\u0004 \u0005[היה לו רווח]\u0006 מספיק בתוך הבית, ולכן \u0003נפק יתיב\u0004 \u0005[יצא\u0006 ו\u0005ישב]\u0006 \u0003בכרמלית. אייתו ליה בי סדיא\u0004 \u0005[הביאו לו לבדים]\u0006 דרך מלבוש, ו\u0003לא יתיב\u0004 \u0005[ישב]\u0006 על לבדים אלה. \u0003מאן דחזא\u0004 \u0005[מי שראה]\u0006 מעשה \u0003זה סבר\u0004 שאינו יושב עליהם \u0003משום דבי סדיא\u0004 \u0005[שלבדים]\u0006 \u0003אסור\u0004 לטלטלם כך, \u0003ולא היא,\u0004 אין הדבר כן, שהלא \u0003רב אכרוזי\u0004 \u0005[להכריז]\u0006 היה הולך \u0003ומכריז: בי סדיא שרי\u0004 \u0005[לבדים מותרים]\u0006 לטלטלם בדרך זו, \u0003ו\u0004אולם \u0003משום כבוד רבותינו\u0004 שהיו באותו מקום \u0003לא ישב עליו,\u0004 שלא רצה שישב הוא במקום גבוה ומכובד יותר משלהם. ומעירים: \u0003ומאן נינהו\u0004 \u0005[ומי הם]\u0006 רבותינו אלה — \u0003רב כהנא ורב אסי\u0004 שהיו תלמידים וחברים של רב.","\u0003נותנין תבשיל לתוך הבור\u0004 הריק \u0003בשביל שיהא שמור\u0004 מפני החום, \u0003ואת המים היפים\u0004 לשתיה מכניסים בכלי ואותו נותנים \u0003ב\u0004תוך המים ה\u0003רעים, בשביל שיצננו\u0004 המים הטובים. \u0003ו\u0004כן נותנים \u0003את הצונן בחמה בשביל שיחמו\u0004 המים. ועוד אמרו: \u0003מי שנשרו\u0004 (נפלו) \u0003כליו\u0004 (בגדיו) בלכתו \u0003בדרך במים\u0004 — \u0003מהלך בהן ואינו חושש\u0004 משום סחיטה וכיבוס. \u0003הגיע לחצר החיצונה\u0004 של מקום שאפשר לשמור בו חפצים — \u0003שוטחן\u0004 את הבגדים הללו \u0003בחמה\u0004 להתייבש, \u0003אבל לא כנגד העם\u0004 שיחשדוהו שכבסם בשבת.","על ההלכה ששנינו במשנה שנותנים תבשיל בבור תוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמותר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניגזר\u0004 \u0005[נגזור]\u0006 איסור בכך \u0003משום אשוויי\u0004 \u0005[השוואת,\u0006 יישור\u0005]\u0006 \u0003גומות\u0004 בבור שבא לשים בו את התבשיל, שהיא מלאכה אסורה בשבת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אוסרים משום כך.","\u0003ו\u0004עוד שנינו במשנה שמכניסים בשבת \u0003את המים היפים ברעים\u0004 כדי לצננם. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמותר! ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[הסוף,\u0006 ההמשך, היה \u0005נצרך לו]\u0006 שמותר להטמין \u0003את הצונן בחמה,\u0004 ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומסבירים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניגזור דילמא אתי לאטמוני\u0004 \u0005[שמא יבוא להטמין]\u0006 \u0003ברמץ\u0004 (אפר חם), שגם כך מחמם את המים ולא על האש ממש, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים עד כדי כך.","שנינו במשנה ש\u0003מי שנשרו\u0004 בגדיו בלכתו בדרך במים שמהלך בהם, ואינו חושש משום סחיטה וכיבוס, ושוטחם בחמה לייבשם, אבל לא כנגד העם, כדי שלא יחשדוהו שכיבסם בשבת. ובקשר לזה מביאים את מה ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: כל מקום שאסרו חכמים\u0004 לעשות דבר \u0003מפני מראית העין\u0004 — \u0003אפילו בחדרי חדרים אסור\u0004 לעשותו, שלא הבדילו חכמים בדבר. ולכאורה \u0003תנן\u0004 \u0005[משנתנו]\u0006 ששנינו בה ש\u0003שוטחן בחמה אבל לא כנגד העם\u0004 היא בניגוד לשיטה זו! ומסבירים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שוטחן בחמה אבל לא כנגד העם. ר' אלעזר ור' שמעון אוסרין\u0004 וכדברי רב יהודה בשם רב.","\u0003אמר רב הונא\u0004"],["\u0003המנער טליתו בשבת\u0004 מן האבק שדבק בה — \u0003חייב חטאת\u0004 משום מכבס. ומגבילים את הדין הזה: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דין זה \u0003אלא בחדתי\u0004 \u0005[ב\u0006בבגדים \u0005חדשים],\u0006 \u0003אבל בעתיקי\u0004 — \u0003לית לן\u0004 \u0005[בישנים\u0006 — \u0005אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא באוכמי\u0004 \u0005[ב\u0006בגדים \u0005שחורים],\u0006 \u0003אבל בחיורי וסומקי\u0004 — \u0003לית לן\u0004 \u0005[בלבנים ואדומים\u0006 — \u0005אין לנו]\u0006 \u0003בה\u0004 איסור לנער את האבק מעליהם, \u0003והוא\u0004 דווקא באופן \u0003דקפיד עלייהו\u0004 \u0005[שמקפיד עליהם\u0006 לנקותם\u0005],\u0006 שאם אינו מקפיד — אין בכך ליבון כלל.","ומסופר כי \u0003עולא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לפומבדיתא,\u0004 ושם \u0003חזא רבנן דקא מנפצי גלימייהו\u0004 \u0005[ראה חכמים שמנערים\u0006 את \u0005גלימותיהם]\u0006 \u0003אמר: קמחללין רבנן שבתא\u0004 \u0005[מחללים החכמים\u0006 את \u0005השבת]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב יהודה\u0004 לאותם החכמים: \u0003נפוצי ליה באפיה, אנן לא קפדינן מידי\u0004 \u0005[נערו לו בפניו\u0006 את בגדיכם, \u0005אנחנו\u0006 \u0005איננו מקפידים בדבר\u0006 כלל\u0005].\u0006","ומסופר עוד: \u0003אביי הוה קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003רב יוסף. אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כומתאי\u0004 \u0005[\u0006את \u0005כובעי].\u0006 \u0003חזא דאיכא טלא עליה, הוה קמחסם למיתבה ליה\u0004 \u0005[ראה\u0006 אביי \u0005שיש\u0006 \u0005טל עליו,\u0006 ו\u0005היה מהסס לתת\u0006 אותו \u0005לו],\u0006 שחשש שבניעור הטל יש חשש כיבוס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003נפוץ שדי, אנן לא קפדינן מידי\u0004 \u0005[נער\u0006 ו\u0005השלך, אנחנו איננו מקפידים בדבר].\u0006","\u0003אמר רב יצחק בר יוסף\u0004 שכך \u0003אמר ר' יוחנן: היוצא בטלית מקופלת\u0004 כשהיא \u0003מונחת לו על כתיפו בשבת\u0004 — \u0003חייב חטאת\u0004 משום נושא משא בשבת. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003סוחרי כסות היוצאים בטליתות מקופלות ומונחות על כתיפן בשבת\u0004 — \u0003חייבין חטאת. ולא סוחרי כסות בלבד אמרו, אלא כל אדם\u0004 חייב על כך. ולא השתמשו בביטוי זה \u0003אלא\u0004 מפני \u0003שדרכן של מוכרין לצאת כך.\u0004","\u0003ו\u0004כן \u0003חנוני היוצא במעות הצרורין לו בסדינו\u0004 שהוא הבגד שמתעטף בו — \u0003חייב חטאת. ולא חנוני בלבד אמרו\u0004 שחייב \u0003אלא כל אדם\u0004 חייב על כך. ולא השתמשו בביטוי זה \u0003אלא\u0004 מפני \u0003שדרכו של חנוני לצאת כך. והרטנין\u0004 (הרצים) \u0003יוצאין\u0004 בשבת \u0003בסודרין שעל כתיפן,\u0004 שכך דרך לבישתם. \u0003ולא רטנין בלבד אמרו\u0004 שמותרים לצאת כך \u0003אלא כל אדם אלא שדרכן של רטנין לצאת בכך.\u0004","\u0003אמר ר' יהודה: מעשה בהורקנוס בנו של ר' אליעזר בן הורקנוס שיצא בסודר שעל כתיפו בשבת, אלא שנימא\u0004 (חוט) מן הסודר היתה \u0003כרוכה לו באצבעו\u0004 שלא יפול הסודר מעליו כיון שהוא קשור בו, \u0003וכשבא הדבר לפני חכמים אמרו:\u0004 מותר לצאת בסודר \u0003אפילו אין נימא כרוכה לו באצבעו.\u0004 וכן \u0003דרש רב נחמן בר רב חסדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב חסדא: הלכה\u0004 היא שיכול \u0003לצאת בסודר שעל כתיפו בשבת אף על פי שאין נימא\u0004 (חוט) מהסודר \u0003כרוכה לו באצבעותיו.\u0004","\u0003עולא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003אסי בר היני, בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 בני הבית: \u0003מהו\u0004 הדין, האם מותר \u0003לעשות מרזב\u0004 בבגדו \u0003בשבת? אמר להו\u0004 \u0005[להם]\u0006 עולא, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' אלעי: אסור לעשות מרזב בשבת.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003מרזב\u0004 זה? \u0003אמר ר' זירא: כיסי בבלייתא\u0004 \u0005[כיסים בבליים],\u0006 שנהגו להרים את שולי הטלית התחתונים ולקשרם על הכתפים עד שנוצרים כעין כיסים צמודים לבגד.","ומסופר כי \u0003ר' ירמיה הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003ר' זירא. אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה לר זירא: \u0003הכי מאי\u0004 \u0005[כך,\u0006 באופן כזה, שהראה לו קיפול מסויים ושאל: \u0005מהו],\u0006 האם מותר לעשות כן בשבת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור.\u0004 חזר והראה לו דרך קיפול אחרת, ושאל: \u0003והכי מאי\u0004 \u0005[וכך מה\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אסור. אמר רב פפא: נקוט האי כללא\u0004 \u0005[נקוט,\u0006 החזק \u0005כלל זה]\u0006 \u0003בידך: כל\u0004 קיפול שהוא עושה \u0003אדעתא דלכנופי\u0004 \u0005[על דעת לאסוף]\u0006 את בגדו מן הקרקע — \u0003אסור,\u0004 ו\u0003כל אדעתא\u0004 \u0005[שעל דעת]\u0006 \u0003להתנאות\u0004 בקיפול זה — \u0003שרי\u0004 \u0005[מותר].\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי מתנאה בסדינו הוה\u0004 \u0005[היה]\u0006 ומקפל שוליו לנוי על כתפיו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: פעם אחת יצא רבי לשדה והיו שני צידי טליתו מונחין\u0004 לו \u0003על כתיפו. אמר לפניו יהושע בן זירוז בן חמיו של ר' מאיר:\u0004 וכי \u0003בזו לא חייב ר' מאיר חטאת? אמר ליה\u0004 \u0005[לו]\u0006 רבי: וכי \u0003דקדק ר' מאיר עד כאן,\u0004 וקבע שדבר זה הדומה לקיפול יש בו איסור חמור של משא בשבת? ואם אכן דקדק, מוטב איפוא שלא להיכנס לספק. מיד \u0003שלשל רבי טליתו\u0004 מעליו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר: לא יהושע בן זירוז הוה\u0004 \u0005[היה]\u0006 זה \u0003אלא יהושע בן כפוסאי היה, חתנו של ר' עקיבא,\u0004 והוא \u0003אמר:\u0004 וכי \u0003ב\u0004כגון \u0003זו לא חייב ר' עקיבא חטאת? אמר לו\u0004 רבי: וכי \u0003דקדק ר' עקיבא עד כאן,\u0004 וקבע שדבר זה הדומה לקיפול יש בו איסור חמור של משא בשבת? ואם אכן דקדק, מוטב איפוא שלא להיכנס לספק. מיד \u0003שלשל רבי טליתו\u0004 מעליו. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר רב יהודה אמר:\u0004 לא כך היה המעשה, ולא לבש רבי עצמו טלית מקופלת על כתיפיו בשבת, אלא \u0003\"נשאל\u0004 רבי \u0003\"איתמר\u0004 \u0005[נאמר],\u0006 שבאה שאלה כזו בפני רבי, ורצה להתיר עד שהעידו בפניו משום גדולי הדור שיש חשש איסור בדבר.","\u0003הרוחץ\u0004 בשבת \u0003במי מערה\u0004 (מי מקוה שבמערה) \u0003ובמי טבריא\u0004 (טבריה) \u0003ונסתפג אפילו בעשר אלונטיאות\u0004 (מגבות) — \u0003לא יביאם בידו,\u0004 שמא ישכח ויסחט מהן את המים. \u0003אבל עשרה בני אדם מסתפגין באלונטית אחת\u0004 את \u0003פניהם, ידיהם ורגליהם, ומביאין אותן בידן\u0004 ואף שהמגבת רטובה מאד, מכל מקום כיון שרבים הם הרי הם מזכירים זה לזה איסור שבת ואינם סוחטים.","אגב הזכרת מי טבריה, דנים בדיני מרחץ ורפואה בשבת. \u0003סכין\u0004 בשמן \u0003וממשמשין\u0004 ביד את הגוף, \u0003אבל לא מתעמלין\u0004 בכח כדי להזיע ולהתרפא. \u0003ולא מתגררין\u0004 מן השמן במגררת. וכן \u0003אין יורדין\u0004 בשבת \u0003לקורדימא\u0004 (נהר טובעני מלא בוץ), \u0003ואין עושין אפיקטויזין\u0004 (אמצעי הקאה), \u0003ואין מעצבין את\u0004 התינוק \u0003הקטן\u0004 ליישר את עצמותיו, \u0003ואין מחזירין את השבר\u0004 למקומו, ו\u0003מי שנפרקה\u0004 (נקעה) \u0003ידו ורגלו לא יטרפם\u0004 (ישים אותם במים וינענעם) \u0003בצונן,\u0004 שהוא דרך רפואה, \u0003אבל רוחץ הוא כדרכו, ואם נתרפא\u0004 — \u0003נתרפא.\u0004","\u0003קתני\u0004 \u0005[שנה]\u0006 התנא במשנה \u0003מי מערה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מי טבריא,\u0004 וכוונתו: \u0003מה מי טבריא\u0004 מים \u0003חמין\u0004 הם — \u0003אף מי מערה חמין\u0004 הם בדווקא. ומדקדקים בלשון המשנה שנאמר בה \u0003\"הרוחץ\"\u0004 ומשמעו: \u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שאם רחץ הריהו מסתפג אפילו בעשר מגבות (אלונטיאות), ואולם לרחוץ \u0003לכתחילה\u0004 — \u0003לא\u0004 ירחץ. שאם היתה הכוונה במשנה להתיר רחיצה זו לכתחילה היה עליה לנסח את המשפט כך: \"רוחץ אדם במי מערה\"! ו\u0003מכלל\u0004 הדברים אתה למד"],["\u0003להשתטף\u0004 (לשטוף את עצמו שלא כדרך רחיצה) \u0003כל גופו\u0004 במים חמים \u0003אפילו לכתחילה שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006 ושואלים: \u0003מני\u0004 \u0005[\u0006של \u0005מי היא\u0006 משנה זו\u0005]?\u0006 ומשיבים: לשיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא ישתטף אדם\u0004 בשבת \u0003בין ב\u0004מים \u0003חמין בין בצונן,\u0004 אלו \u0003דברי ר' מאיר. ר' שמעון מתיר\u0004 בשני המקרים. ו\u0003ר' יהודה\u0004 מחלק ולדעתו \u0003בחמין\u0004 — \u0003אסור, בצונן\u0004 — \u0003מותר.\u0004","שנינו במשנה דובר בענין היתר ההסתפגות במגבת אחר הרחיצה בשבת והוסיפה המשנה: \u0003ונסתפג אפילו בעשר אלונטיות.\u0004 ומעירים על סגנון המשנה: \u0003רישא רבותא קא משמע לן וסיפא רבותא קא משמע לן\u0004 \u0005[\u0006ב\u0005ראש,\u0006 תחילת המשנה, \u0005חידוש השמיע לנו\u0006 בסגנונו, \u0005ו\u0006ב\u0005סופה חידוש השמיע לנו].\u0006 ומפרטים: \u0003רישא רבותא קא משמע לן\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה \u0005חידוש השמיע לנו]\u0006 שנאמר בה \"אפילו בעשר אלונטיות\" וכוונת הדברים ש\u0003אפילו הני דלא נפישי בהו מיא\u0004 \u0005[אלה\u0006 עשר אלונטיות \u0005שאין המים מרובים בהן],\u0006 \u0003כיון דחד\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 \u0003הוא\u0004 המסתפג — \u0003אתי\u0004 \u0005[בא]\u0006 \u0003לידי סחיטה, וסיפא רבותא קא משמע לן\u0004 \u0005[ו\u0006ב\u0005סופה חידוש השמיע לנו]\u0006 ששנינו שאפילו עשרה מותרים להסתפג במגבת אחת, הכוונה היא ש\u0003אפילו הני דנפישי בהו מיא\u0004 \u0005[אלה,\u0006 עשרה אנשים \u0005ש\u0006בכולם גם יחד \u0005מרובים בהם המים],\u0006 \u0003כיון\u0004 ש\u0003רבים נינהו, מדכרי אהדדי\u0004 \u0005[הם\u0006 הרוחצים, \u0005מזכירים זה לזה]\u0006 לא לסחוט, ולכן הותר הדבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מסתפג אדם\u0004 בשבת \u0003באלונטית ומניחה בחלון\u0004 שבכותל בית המרחץ. \u0003ולא ימסרנה לאוליירין\u0004 (שמשי המרחץ), \u0003מפני שחשודים על אותו דבר\u0004 שיסחטו את המגבות. \u0003ר' שמעון אומר: מסתפג באלונטית אחת ומביאה בידו לתוך ביתו\u0004 ואין לחשוש שמא יסחוט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הלכתא מאי\u0004 \u0005[הלכה מה\u0006 היא\u0005]\u0006 לענין היתר הבאת המגבת לביתו אחר שנסתפג בה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' שמעון, הא\u0004 \u0005[הרי]\u0006 \u0003רבי, הא\u0004 \u0005[הרי]\u0006 \u0003שמואל, הא\u0004 \u0005[הרי]\u0006 \u0003ר' יוחנן\u0004 שכולם מתירים.","ומפרטים: \u0003ר' שמעון\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שמתיר לרחוץ ולהסתפג ולהביאו לביתו. \u0003רבי\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006ן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר רבי : כשהיינו למדין תורה אצל ר' שמעון בתקוע, היינו מעלין שמן ואלונטית מחצר לגג ומגג לקרפף\u0004 (מקום מגודר כעין חצר), \u0003עד שהיינו מגיעין\u0004 שלא דרך רשות הרבים \u0003אצל מעין שהיינו רוחצין בו,\u0004 הרי שלדעתו מותר לקחת ולהחזיר אלונטית. \u0003שמואל\u0004 — ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל\u0004 במפורש: \u0003מסתפג אדם באלונטית ומביאה בידו לתוך ביתו. ר' יוחנן\u0004 — ש\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: הלכה\u0004 היא ש\u0003מסתפג אדם באלונטית ומביאה בידו לתוך ביתו.\u0004","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל בפסק ההלכה: \u0003הלכה כסתם משנה\u0004 שלא צויין בה שם בעל ההלכה, \u0003ותנן\u0004 \u0005[ו\u0006במשנתינו \u0005שנינו]:\u0006 \u0003ונסתפג אפילו בעשר אלונטיות\u0004 ועם כל זה צויין במפורש ש\u0003לא יביאם בידו!\u0004 ומתרצים: שבגרסת ר' יוחנן לא היתה הלכה זו סתומה בלא שם אומרה אלא \u0003ההוא\u0004 — \u0003כ\u0004שיטת \u0003בן חכינאי מתני לה\u0004 \u0005[היה שונה אותה],\u0006 ודעת יחיד היא, שאין הלכה כמותו.","\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: האוליירין\u0004 (הבלנים) \u0003מביאין\u0004 בשבת את \u0003בלרי\u0004 (בגדי הרחיצה) של ה\u0003נשים לבי בני\u0004 \u0005[לבית המרחץ],\u0006 \u0003ובלבד שיתכסה בהן ראשן ורובן,\u0004 שיהיה זה כדרך לבוש ולא כנושא משא. ו\u0003סכניתא\u0004 שהיא כעין סודר גדול המונח גם על הכתף \u0003צריך לקשר שני ראשיה למטה\u0004 שלא תיפול מעליו. ו\u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן\u0004 הכוונה היא שיש לקושרה \u0003למטה מ\u0004ן ה\u0003כתפיים.\u0004 וכעין זה \u0003אמר רבא לבני\u0004 עירו \u0003מחוזא: כי מעבריתו מאני לבני חילא שרביבו בהו\u0004 \u0005[כאשר אתם מעבירים בגדים עבור החיילים\u0006 המתאכסנים בעיר \u0005שרבבו בהם,\u0006 אותם\u0005]\u0006 \u0003למטה מ\u0004ן ה\u0003כתפים,\u0004 שיהיו הבגדים מונחים כלבוש על נושאיהם.","שנינו במשנה ש\u0003סכין\u0004 בשמן \u0003וממשמשין\u0004 ביד את הגוף. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003סכין וממשמשין בבני מעיים בשבת\u0004 ואין בכך משום רפואה, \u0003ובלבד\u0004 שישנה \u0003שלא יעשה כדרך שהוא עושה בחול.\u0004 ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד עושה]\u0006 בשבת? \u0003ר' חמא בר חנינא אמר: סך\u0004 שמן קודם \u0003ואחר כך ממשמש.\u0004 ו\u0003ר' יוחנן אמר: סך וממשמש בבת אחת.\u0004","שנינו במשנה: \u0003אבל לא מתעמלין\u0004 בשבת. \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: אסור לעמוד בקרקעיתה של\u0004 מרחץ המרפא \u0003דיומסת\u0004 בשבת \u0003מפני שמעמלת ומרפא\u0004 אפילו אם אינו רוחץ ומתעמל. \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: כל ימיה של דיומסת\u0004 שיפה לרחוץ שם לרפואה \u0003עשרים ואחד יום ועצרת\u0004 (חג שבועות) \u0003מן המנין. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לתלמידים\u0005]:\u0006 \u0003עצרת להאי גיסא\u0004 \u0005[לצד זה,\u0006 בתחילה\u0005],\u0006 \u0003או להאי גיסא\u0004 \u0005[לצד זה,\u0006 בסוף\u0005]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר שמואל: כולהו שקייני מדיבחא ועד עצרתא מעלו\u0004 \u0005[כל שיקויי\u0006 הרפואה \u0005מן הפסח ועד העצרת\u0006 הם \u0005מעולים],\u0006 ומכאן נלמד שאף הרחיצה בדיומסת זמנה לפני עצרת! ודוחים: \u0003דילמא התם\u0004 \u0005[שמא שם,\u0006 ברפואות\u0005]\u0006 \u0003הוא\u0004 כך כיון שכל \u0003כמה דקריר עלמא מעלי\u0004 \u0005[שקריר העולם, מעולה יותר],\u0006 \u0003אבל הכא\u0004 \u0005[כאן,\u0006 במרחץ\u0005]\u0006 ש\u0003משום הבלא\u0004 \u0005[חום]\u0006 \u0003הוא,\u0004 ואם כן \u0003כיון דחמים עלמא טפי מעלי\u0004 \u0005[כיון שחם העולם, מעולה יותר],\u0006 ושמא טוב יותר לרחוץ אחר חג השבועות.","ואגב הזכרת דיומסת מביאים את מה ש\u0003אמר ר' חלבו: חמרא דפרוגייתא ומיא\u0004 \u0005[היין של פריגיה והמים]\u0006 של \u0003דיומסת\u0004 הם ש\u0003קיפחו\u0004 את \u0003עשרת השבטים מישראל,\u0004 שבני אותם שבטים נמשכו אחרי תענוגות השתיה והמרחצאות ולא עסקו בתורה.","מסופר ש\u0003ר' אלעזר בן ערך איקלע להתם\u0004 \u0005הזדמן לשם],\u0006 לפריגיה ודיומסת, \u0003אימשיך בתרייהו איעקר תלמודיה\u0004 \u0005[נמשך אחריהם\u0006 ו\u0005נעקר,\u0006 נשתכח ממנו \u0005תלמודו].\u0006 \u0003כי הדר אתא, קם למיקרי בספרא, בעא למיקרא\u0004 \u0005[כאשר חזר\u0006 ו\u0005בא, עמד לקרוא בספר\u0006 התורה והיה \u0005צריך לקרוא]\u0006 \u0003\"החדש הזה לכם\"\u0004 וכל כך נשתכח ממנו, שכמעט שכח את צורת האותיות ובמקום מילים אלה \u0003אמר \"החרש היה לבם\". בעו רבנן רחמי עליה והדר תלמודיה\u0004 \u0005[בקשו חכמים רחמים עליו וחזר תלמודו].\u0006","\u0003והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' נהוראי אומר: הוי גולה למקום תורה ואל תאמר שהיא תבא אחריך, ש\u0004כן אם תהיה במקום תורה, \u0003חבריך יקיימוה בידך, ואל בינתך אל תשען. תנא\u0004 \u0005[שנינו]:\u0006 \u0003לא ר' נהוראי שמו\u0004 האמיתי, \u0003אלא ר' נחמיה שמו. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' אלעזר בן ערך שמו.\u0004 והדברים שאמר היו מתוך נסיונו, משום ששכח את תלמודו כיון שלא רצה לגלות למקום תורה. \u0003ולמה נקרא שמו ר' נהוראי?\u0004 — כינוי הוא לו, \u0003שמנהיר\u0004 (מאיר) \u0003עיני חכמים בהלכה.\u0004","שנינו במשנה: \u0003אבל לא מתגררין\u0004 בשבת. \u0003תנו רבנן\u0004 \u0005שנו חכמים\u0006 בברייתא: \u0003אין גוררין במגררת בשבת. רבן שמעון בן גמליאל אומר: אם היו רגליו מלוכלכות בטיט ובצואה\u0004 — \u0003גורר כדרכו\u0004 במגררת \u0003ואינו חושש. רב שמואל בר יהודה עבדא ליה אימיה מגררתא דכספא\u0004 \u0005[עשתה לו אמו מגררת של כסף]\u0006 לשבת, כדי לעשות שינוי.","עוד שנינו במשנה ש\u0003אין יורדין לקורדימא\u0004 (נהר טובעני מלא בוץ). ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום פיקא\u0004 \u0005[הבוץ],\u0006 שקרוב לוודאי שיחליק ויפול לתוכו, ויבוא לידי סחיטה ורחיצה.","עוד שנינו במשנה: \u0003ואין עושין אפיקטויזין\u0004 (אמצעי הקאה) בשבת. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: לא שנו\u0004 שאסור \u0003אלא בסם\u0004 שהוא כדרך רפואה, \u0003אבל\u0004 אם מביא עצמו להקאה להקיא \u0003ביד\u0004 — \u0003מותר. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נחמיה אומר: אף בחול\u0004 אם אינו זקוק לכך לרפואה \u0003אסור\u0004 להביא לידי הקאה \u0003מפני הפסד אוכלין.\u0004","עוד שנינו במשנה: \u0003ואין מעצבין את\u0004 התינוק \u0003הקטן\u0004 ליישר את עצמותיו בשבת. \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: לפופי ינוקא\u0004 \u0005[חיתול התינוק\u0006 בחוזקה\u0005]\u0006 \u0003בשבת שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]\u0006 ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מעצבין!\u0004 ומשיבים: \u0003התם בחומרי\u0004 \u0005[שם\u0006 במשנה מדובר \u0005בעצמות]\u0006 ה\u0003שדרה דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבונה\u0004 אם מיישר אותן, ובכגון זה אכן אסור.","עוד שנינו במשנה: \u0003ואין מחזירין את השבר\u0004 בשבת למקומו. \u0003אמר ר' חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 שכך \u0003אמר שמואל:\u0004"],["\u0003הלכה\u0004 זו שהובאה במשנה בענין החזרת השבר למקומו בשבת לא כפי שכתובה לפנינו היא, אלא צריך לגרוס: \u0003מחזירין את השבר\u0004 בשבת למקומו. מסופר: \u0003רבה בר בר חנה איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לפומבדיתא,\u0004 ו\u0003לא על לפירקיה\u0004 \u0005[נכנס,\u0006 בא \u0005לדרשתו]\u0006 של \u0003רב יהודה. שדריה\u0004 \u0005[שלחו]\u0006 רב יהודה אל \u0003אדא דיילא\u0004 \u0005[הממונה],\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה לאדא: \u0003זיל גרביה\u0004 \u0005[לך ומשוך אותו],\u0006 את רבה בר בר חנה. \u0003אזיל גרביה\u0004 \u0005[הלך\u0006 ו\u0005משך אותו]\u0006 אדא בכוח לדרשה (ר\"ח). \u0003אתא\u0004 \u0005[בא]\u0006 רבה בר בר חנה, \u0003אשכחיה דקא דריש\u0004 \u0005[מצא אותו,\u0006 את רב יהודה \u0005שהוא דורש]:\u0006 \u0003אין מחזירין את השבר\u0004 בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנה לרב יהודה: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 שכך \u0003אמר שמואל: הלכה\u0004 היא במשנה ש\u0003מחזירין את השבר,\u0004 שכך, כאמור, היא הגירסה הנכונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הא\u0004 \u0005[הרי]\u0006 רב \u0003חנא\u0004 מבגדד הוא \u0003דידן\u0004 \u0005[משלנו,\u0006 מבבל\u0005],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שמואל\u0004 גם הוא \u0003דידן\u0004 \u0005[משלנו,\u0006 מבבל\u0005],\u0006 \u0003ו\u0004עדיין \u0003לא שמיע לי\u0004 \u0005[שמעתי]\u0006 הלכה זו, \u0003ולאו בדינא גרבתיך\u0004 \u0005[והאם לא בדין משכתי אותך]?\u0006","שנינו במשנה ש\u0003מי שנפרקה ידו\u0004 לא יטרפנה במים לריפוי. ומסופר: \u0003רב אויא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב יוסף\u0004 בשבת, ו\u0003שניא ליה ידיה\u0004 \u0005[נקעה לו ידו].\u0006 הראה רב אויא אופנים שונים של הנחת היד. ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 בשאלה: \u0003הכי מאי\u0004 \u0005[כך מה\u0006 הדין\u0005]?\u0006 האם מותר לשים יד באופן כזה או שיש בזה משום רפואה בשבת? אמר לו רב יוסף: \u0003אסור.\u0004 והוסיף רב אויא לשאול: \u0003והכי מאי\u0004 \u0005[וכך מה\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אסור. אדהכי איתפח ידיה\u0004 \u0005[בינתיים התרפאה ידו],\u0006 שחזרה למקומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מאי תיבעי\u0004 \u0005[מה מסופק]\u0006 \u0003לך, הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003מי שנפרקה ידו או רגלו\u0004 — \u0003לא יטרפם בצונן, אבל רוחץ\u0004 הוא \u0003כדרכו, ואם נתרפא\u0004 — \u0003נתרפא.\u0004 ומכאן שאסור לעשות בשבת כל דבר רפואה מיוחד לענין זה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אויא: מכאן אין ראיה, \u0003ו\u0004כי \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"אין מחזירין את השבר\", ואמר רב חנא בגדתאה\u0004 \u0005[מבגדד]\u0006 שכך \u0003אמר שמואל הלכה\u0004 ש\u0003מחזירין את השבר,\u0004 ויתכן שאף בענין רפואת הנקע כמו בענין החזרת השבר למקומו בשבת שנו להקל! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003כולהו בחדא מחיתא מחיתנהו\u0004 \u0005[\u0006את \u0005כולם באריגה אחת אתה אורג]?!\u0006 אין הדברים דומים: \u0003היכא דאיתמר\u0004 \u0005[היכן שנאמר]\u0006 במפורש שהגירסה שונה ולהקל — \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא איתמר\u0004 \u0005[נאמר]\u0006 — \u0003לא איתמר\u0004 \u0005[נאמר],\u0006 ואין לדמות שבר לנקע\u0005.\u0006","","\u0003שואל אדם מחבירו\u0004 בשבת \u0003כדי יין וכדי שמן, ובלבד שלא יאמר לו\u0004 בלשון \u0003\"הלויני\". וכן\u0004 שואלת \u0003האשה מחבירתה ככרות\u0004 לחם. \u0003ואם\u0004 המלוה \u0003אינו מאמינו\u0004 שיחזיר — \u0003מניח\u0004 הלווה \u0003טליתו אצלו\u0004 כמשכון, \u0003ועושה עמו חשבון לאחר שבת. וכן ערב פסח בירושלים שחל להיות בשבת, מניח,\u0004 עושה הקרבן, \u0003טליתו אצלו,\u0004 אצל בעל הטלה, \u0003ונוטל את\u0004 הטלה של קרבן \u0003פסחו, ועושה עמו חשבון לאחר יום טוב.\u0004 שנינו במשנה שעל אף ששואל אדם בשבת מחבירו \u0003כדי יין ועוד, מכל מקום אל יאמר לו בלשון \"הלויני\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הביטוי \u0003\"השאילני\" ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 הביטוי \u0003\"הלויני\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"השאילני\"\u0004 — \u0003לא אתי למיכתב\u0004 \u0005[יבוא לכתוב]\u0006 לפניו את החוב, ששאילה משמעה שלוקח חפץ ומחזירו בעינו כעבור זמן קצר. ואולם \u0003\"הלויני\",\u0004 כיון שסתם הלואה לזמן ממושך ואינה חוזרת בעינה — \u0003אתי למיכתב\u0004 \u0005[יבוא לכתוב].\u0006","","והקשה לו רבה בר רב חנן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כיון\u0004 ש\u0003ב\u0004ימות ה\u0003חול, זימנין דבעי למימר ליה\u0004 \u0005[פעמים שרוצה לומר לו]\u0006 \u0003\"הלויני\" ואמר ליה\u0004 \u0005[ואומר לו]\u0006 \u0003\"השאילני\" ולא קפיד עילויה\u0004 — \u0003ואתי למיכתב\u0004 \u0005[ ואינו מקפיד עליו,\u0006 על שינוי זה, ו\u0005בא לכתוב ],\u0006 ואם כן \u0003בשבת נמי אתי למיכתב\u0004 \u0005[גם כן בא לכתוב]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי, יש לחלק: \u0003בחול, דלא שנא כי אמר ליה\u0004 \u0005[שאינו שונה כאשר אומר לו]\u0006 \u0003\"הלויני\" לא שנא כי אמר ליה\u0004 \u0005[\u0006ו\u0005אינו שונה כאשר אומר לו]\u0006 \u0003\"השאילני\",\u0004 ו\u0003לא קפדינן עילויה\u0004 \u0005[איננו מקפידים עליו]\u0006 — ולכך יש חשש שמא \u0003אתי למיכתב\u0004 \u0005[יבוא לכתוב].\u0006 ואולם \u0003בשבת כיון\u0004 ש\u0003\"השאילני\" הוא דשרו ליה רבנן\u0004 \u0005[שהתירו לו חכמים]\u0006 לומר, ואולם \u0003\"הלויני\" לא שרו ליה\u0004 \u0005[התירו לו]\u0006 לומר — \u0003מינכרא מילתא\u0004 \u0005[ניכר הדבר],\u0006 \u0003ולא אתי למיכתב\u0004 \u0005[ולא יבוא לכתוב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי: מכדי\u0004 \u0005[הרי]\u0006 \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003כל מילי\u0004 \u0005[ענייני]\u0006 \u0003יום טוב\u0004 כל \u0003כמה\u0004 ש\u0003אפשר לשנויי\u0004 \u0005[לשנות]\u0006 מהדרך בה נעשה הדבר בימות החול — \u0003משנינן\u0004 \u0005[משנים אנו],\u0006 \u0003הני נשי דמליין חצבייהו מיא, מאי טעמא לא משנין\u0004 \u0005[הנשים הללו שממלאות\u0006 את \u0005כדיהן מים, מה טעם אין\u0006 הן \u0005משנות]\u0006 מדרך שאיבתן בימות החול? ענה לו: \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות זאת בדרך אחרת כי \u0003היכי לעבדי\u0004 \u0005[איך תעשנה]?\u0006 אם תאמר שאלה \u0003דמליין בחצבא רבא, לימלו בחצבא זוטא\u0004 \u0005[הממלאות\u0006 כרגיל \u0005בכד גדול,\u0006 \u0005תמלאנה\u0006 ביום \u0005טוב\u0006 \u0005בכד קטן]\u0006 — \u0003הא קא מפשו בהילוכא\u0004 \u0005[הרי\u0006 בכך הן \u0005מרבות בהילוך]\u0006 ובטירחה. ולהיפך, \u0003אלה דמליין בחצבא זוטא, לימלו בחצבא רבא\u0004 \u0005[הממלאות\u0006 כרגיל \u0005בכד\u0006 קטן, תמלאנה ביום טוב \u0005בכד גדול]\u0006 — הרי בכך \u0003קא מפשו במשוי\u0004 \u0005[הן מרבות במשא],\u0006 ואף שיש בכך שינוי, מכל מקום יש בכך תוספת עבודה ביום טוב, ואין לתקן תקנה זו.",""],["ואם תאמר כי כדי לשנות מבחול \u0003ניפרוס סודרא\u0004 \u0005[סודר]\u0006 על הכלי — \u0003אתי\u0004 \u0005[\u0006יכולה \u0005לבוא]\u0006 בכך \u0003לידי סחיטה.\u0004 ואם \u0003נכסייה בנכתמא\u0004 \u0005[נכסה אותו במכסה]\u0006 — \u0003זימנין דמיפסק, ואתי למקטריה\u0004 \u0005[פעמים ש\u0006הוא \u0005נקרע\u0006 מן החבית \u0005ובא לקושרו].\u0006 \u0003הלכך\u0004 כיון ש\u0003לא\u0004 \u0005[אי]\u0006 \u0003אפשר\u0004 בדרך אחרת לכן שואבות הנשים ביום טוב בדרך הרגילה, שלא בשינוי.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי:\u0004 הלא \u0003תנן\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003לא מספקין\u0004 (מוחאים כפים), \u0003ולא מטפחין\u0004 (בכף ידם על הגוף), \u0003ולא מרקדין ביום טוב. וקא חזינן דעבדין, ולא אמרינן להו ולא מידי\u0004 \u0005[ואנו רואים שעושים, ואין אנו אומרים להם דבר]!\u0006 אמר לו: \u0003ולטעמיך, הא\u0004 \u0005[ולטעמך,\u0006 לשיטתך, הלכה \u0005זו]\u0006 ש\u0003אמר רבא: לא ליתיב איניש אפומא דלחייא\u0004 \u0005[אל ישב אדם\u0006 בשבת \u0005על פי לחי\u0006 המבוי\u0005],\u0006 \u0003דילמא מיגנדר ליה\u0004 \u0005[שמא יתגלגל לו]\u0006 \u0003חפץ\u0004 לרשות הרבים \u0003ואתי לאיתויי\u0004 \u0005[ויבוא להביאו],\u0006 \u0003והא קא חזינן נמי דמותבי חצבי ויתבן אפומא דמבואה, ולא אמרינן להו ולא מידי!\u0004 \u0005[והרי אנו רואים גם כן ששמות\u0006 נשים את \u0005כדיהן ויושבות על פי המבוי, ואין אנו אומרים להן דבר].\u0006 \u0003אלא\u0004 בדברים אלה טעם אחר הוא שאנו אומרים: \u0003הנח לישראל\u0004 ואל תגער בהם, \u0003מוטב שיהו שוגגין ואל יהו מזידין,\u0004 שבין כה וכה לא יצייתו.","\u0003סבור מינה הני מילי בדרבנן\u0004 \u0005[\u0006היו ש\u0005סברו מתוך כך\u0006 ש\u0005דברים אלה\u0006 אמורים רק \u0005ב\u0006איסורים \u0005ש\u0006מדברי \u0005סופרים],\u0006 \u0003אבל בדאורייתא\u0004 \u0005ב\u0006איסורים \u0005שמן התורה]\u0006 — \u0003לא,\u0004 ובודאי צריך לגעור בעוברים. ואולם אומרים: \u0003ולא היא,\u0004 אין הדבר כך, \u0003לא שנא בדרבנן ולא שנא בדאורייתא\u0004 \u0005[אינו שונה ב\u0006דברי \u0005סופרים, ואינו שונה ב\u0006דברי \u0005תורה],\u0006 שבשניהם אין גוערים בעוברים מאותה סיבה. \u0003דהא\u0004 \u0005[שהרי]\u0006 החובה ב\u0003תוספת\u0004 של \u0003יום הכפורים,\u0004 להתחיל את הצום מבעוד יום הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא, וקא חזינן להו דקאכלי ושתו\u0004 \u0005[ואנו רואים אותם\u0006 הנשים \u0005שאוכלות ושותות]\u0006 בערב יום הכיפורים \u0003עד שתחשך ולא אמרינן להו ולא מידי\u0004 \u0005[ואין אנו אומרים להן דבר].\u0006 ומכאן שהדין כן אף באיסור שמן התורה.","שנינו במשנה ש\u0003אשה\u0004 שואלת \u0003מחבירתה ככרות\u0004 בשבת, ואולם אף היא כבדין הראשון לא תבקשם בלשון הלוואה. ושואלים: האם \u0003בשבת הוא דאסיר\u0004 \u0005[שאסור],\u0006 \u0003אבל בחול\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]\u0006 אף בלשון הלוואה? ואם תאמר שאכן כך הדין, אם כן \u0003לימא מתניתין דלא\u0004 \u0005[האם נאמר שמשנתנו אינה]\u0006 \u0003כ\u0004שיטת \u0003הלל, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכן היה הלל אומר: לא תלוה אשה ככר\u0004 לחם \u0003לחבירתה עד שתעשינה,\u0004 כלומר, תעריכנה ב\u0003דמים\u0004 (כסף) \u0003שמא\u0004 עד שתחזיר לה \u0003יוקרו\u0004 ה\u0003חטין, ונמצאו באות לידי רבית,\u0004 שאם תחזיר ככר בעינו, נמצא שהחזירה דבר השווה יותר ממה שלקחה בשעתו, ויש בכך משום ריבית. והרי שאף בכל ימות השנה אסור ליטול ככר לחם מאחר כהלוואה!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003הלל,\u0004 ואולם יש לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו במשנתנו שמתור בלשון הלוואה — הרי זה \u0003באתרא דקיץ דמיה\u0004 \u0005[במקום שקצובים דמיה]\u0006 של הככר, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר הלל — הרי זה \u0003באתרא דלא קיץ דמיה\u0004 \u0005[במקום שאין דמיה קצובים].\u0006","שנינו במשנה ש\u0003אם\u0004 המלווה \u0003אינו מאמינו\u0004 ללווה בשבת וביום טוב, משאיר הלווה את טליתו כמשכון. בקשר לזה מביאים את מה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 מחלוקת אמוראים בענין \u0003הלוואת יום טוב\u0004 (הלוואה ביום טוב), ש\u0003רב יוסף אמר: לא ניתנה ליתבע\u0004 בבית דין, שאמנם ראוי ללווה להחזיר, אבל אין המלווה יכול לכפותו בבית דין שיעשה כן. \u0003ורבה אמר:\u0004 הלוואה זו כשאר הלוואות היא ו\u0003ניתנה ליתבע.\u0004 ומסבירים את שיטותיהם: \u0003רב יוסף אמר\u0004 שהלוואת יום טוב \u0003לא ניתנה ליתבע\u0004 — \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 ש\u0003ניתנה ליתבע\u0004 קיים חשש שמא בשל כך \u0003אתי למיכתב\u0004 \u0005[יבוא לכתוב]\u0006 את דבר ההלוואה ביום טוב כדי שיוכל לתובעה לאחר מכן. ואילו \u0003רבה אמר\u0004 שהלוואת יום טוב \u0003ניתנה ליתבע\u0004 — \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 ש\u0003לא ניתנה\u0004 להיתבע — \u0003לא יהיב ליה\u0004 \u0005[יתן\u0006 \u0003לו,\u0004 לחבירו \u0003]\u0004 הלוואה, \u0003ואתי לאימנועי\u0004 \u0005[ויבוע\u0006 הלווה \u0005להימנע]\u0006 \u0003משמחת יום טוב.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003אם אינו מאמינו\u0004 — \u0003מניח טליתו אצלו\u0004 כמשכון. ורוצים להסיק: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי הלוואת יום טוב \u0003לא ניתנה ליתבע\u0004 כשיטת רב יוסף — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מניח טליתו אצלו ועושה עמו חשבון לאחר\u0004 ה\u0003שבת. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהלוואת יום טוב \u0003ניתנה ליתבע, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003מניח טליתו אצלו? ליתן ליה ולתבעיה\u0004 \u0005[שיתן לו, ויתבענו]\u0006 אם לא יחזיר! ודוחים: זו אינה ראיה, שכן המלווה \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]:\u0006 \u0003לא בעינא דליקום בדינא ודיינא\u0004 \u0005[אין אני רוצה לעמוד בדין ודיינים],\u0006 ועדיף לו לקחת משכון, שלא יצטרך אחר כך לבוא לידי דין.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אידי בר אבין\u0004 ממה ששנינו במשנה: \u0003השוחט את הפרה וחילקה\u0004 ללקוחותיו \u0003בראש השנה\u0004 של השנה שלאחר השמיטה, ועוד מזמן הבית היו חוגגים שני ימים טובים של ראש השנה, והיום הראשון הריהו ספק סוף אלול, ספק תחילת תשרי, ומעתה השאלה האם חוב הלקוחות נהיה בשנה השביעית ונשמט, או שמא בשמינית ואינו נשמט. ואמרו ש\u0003אם\u0004 התברר ש\u0003היה חדש\u0004 אלול של השנה שעברה \u0003מעובר\u0004 (בן שלושים יום) — \u0003משמט,\u0004 שכן דין שמיטת החובות חל רק ברגע האחרון של השנה השביעית, ואם התברר שיומה האחרון של שנה זו היה היום הראשון של ראש השנה החדשה, נמצא שחובם של הלקוחות למוכר הפרה פקע מכוח שנת השמיטה. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהיה זה יום ראשון של השנה הבאה — \u0003אינו משמט.\u0004","ומכאן הוא מסיק: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא ניתנה\u0004 הלוואת יום טוב \u0003ליתבע\u0004 — \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"משמט \"?\u0004 והרי בין כה וכה אינו יכול לתבוע החזרת חובו! ודוחים: \u0003שאני התם דאיגלאי מילתא\u0004 \u0005[שונה שם\u0006 שכאשר התברר \u0005בחודש אלול מעובר הרי\u0006 \u0005התברר הדבר]\u0006 שאותו יום — יום \u0003חול הוא,\u0004 שהרי אם היה זה יום שלושים באלול הרי הוא יום חול רגיל, והלוואה הניתנת בו ניתנה ליתבע, אלא שהיא משמטת מפני שנת השמיטה.","על כן רוצים להביא ראיה מסופה של המשנה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר \u0003מ\u0004מה ששנינו ב\u0003סיפא\u0004 \u0005[בסוף]\u0006 אותה משנה: \u0003אם לאו\u0004 \u0005[לא]\u0006 התברר חודש אלול כחודש מעובר, והיה זה היום הראשון של השנה הבאה — \u0003אינו משמט.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי הלוואת יום טוב \u0003ניתנה ליתבע\u0004 — \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 \u0003\"אינו משמט\",\u0004 שיכול לתבוע. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003\"לא ניתנה ליתבע\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו משמט?\u0004 הרי בין כה וכה אינו יכול לתבוע בבית דין! ומסבירים: אמנם הלוואת יום טוב לא ניתנה ליתבע, ואולם מאחר ואינו משמט, \u0003אי יהיב ליה\u0004 \u0005[אם נותן לו],\u0006 שרוצה להחזיר את החוב — \u0003שקיל\u0004 \u0005[נוטל]\u0006 המלוה.","ותוהים: \u0003מכלל\u0004 הדברים אתה למד \u0003דרישא אי יהיב ליה\u0004 \u0005[שבראש\u0006 המשנה מדובר ש\u0005אם נותן לו]\u0006 הלווה למלוה בחזרה את חובו — \u0003לא שקיל\u0004 \u0005[אינו נוטל]?!\u0006 והרי אין אדם חייב להמנע מלקחת הלוואה שהשביעית משמטת אותה, אלא מצווים רק שלא לתבוע ושלא לנגוש את הלווה. ואומרים: בכל זאת יש הבדל בין המקרים, \u0003רישא\u0004 \u0005[\u0006ב\u0005ראש\u0006 המשנה\u0005]\u0006 באופן שהתברר שהיה אלול מעובר והיה יום ההלוואה בשנה השביעית — \u0003צריך למימר ליה\u0004 \u0005[לומר לו]\u0006 \u0003\"משמט אני\",\u0004 ואילו \u0003סיפא\u0004 \u0005[בסוף\u0006 המשנה\u0005]\u0006 באופן שחודש אלול אינו מעובר — \u0003לא צריך\u0004 הוא \u0003למימר ליה\u0004 \u0005[\"\u0003משמט אני\u0004\"].\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המחזיר חוב בשביעית, יאמר לו\u0004 המלווה ללווה: \u0003\"משמט אני\".\u0004","\u0003ואם אמר לו\u0004 הלווה \u0003\"אף על פי כן\u0004 רצוני לתת לך \u0003\"\u0004— \u0003יקבל ממנו, משום שנאמר \"וזה דבר השמטה\u0004 שמוט כל בעל משה ידו אשר ישה ברעהו לא יגוש את רעהו ואת אחיו כי קרא שמטה לה'\" (דברים טו, ב), ומן המלים \"וזה דבר השמיטה\" למדים שאף שכאשר לבסוף מקבל המלווה את חובו בחזרה ואינו חייב להימנע מלקח, מכל מקום צריך שיהיה שם דיבור של השמטה, שיאמר ללווה: \"משמט אני\", ואילו בסוף המשנה כאשר התברר שההלוואה אינה של שנת השמיטה אף אינו צריך לומר \"משמט אני\".","מסופר כי בהלוואת יום טוב \u0003רב אויא שקיל משכונא\u0004 \u0005[והיה לוקח משכון].\u0006 \u0003רבה בר עולא מערים איערומי\u0004 \u0005[היה מערים]\u0006 ולוקח משהו משל הלווה לאחר יום טוב, עד שיחזיר לו חובו.","שנינו במשנה: \u0003וכן ערב פסח\u0004 בירושלים שחל להיות בשבת — מניח עושה הקרבן את טליתו אצל בעל הטלה כמשכון ונוטל ממנו את הטלה ועושה עמו חשבון לאחר השבת. \u0003אמר ר' יוחנן: מקדיש אדם פסחו בשבת, ו\u0004קרבן \u0003חגיגתו ביום טוב\u0004 עצמו. ומציעים: \u0003נימא\u0004 \u0005[האם נאמר]\u0006 שמה שנאמר במשנתנו \u0003מסייע ליה\u0004 \u0005[לו],\u0006 שכן שנינו בה: \u0003\"וכן ערב פסח בירושלים שחל להיות בשבת מניח\u0004 עושה הקרבן \u0003את טליתו אצלו\u0004, אצל בעל הטלה כמשכון \u0003ונוטל את\u0004 הטלה ל\u0003פסחו ועושה עמו חשבון לאחר יום טוב\".\u0004 נמצא אם כן שאת הטלה עצמו הוא מקדיש בשבת, וכדעת ר' יוחנן!","ודוחים: אין זה מחוייב, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בממנה אחרים עמו על פסחו,\u0004 כלומר, לא באדם הלוקח כבש של חולין ומקדישו, אלא שמצטרף עם שאר המנויים לטלה הקרבן, \u0003דמעיקרא מיקדש וקאי\u0004 \u0005[שמתחילה היה\u0006 כבר \u0005מוקדש ועומד].\u0006","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין נמנין על הבהמה בתחילה ביום טוב,\u0004 ואם כן הרי שאסור אף להימנות על הפסח ביום טוב וכל שכן בשבת! ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 שמדובר כאן במקרה מיוחד, ש\u0003כיון\u0004 ש\u0003רגיל אצלו\u0004 אותו אדם באכילת פסח כאחד מן המנויים בכל שנה — הרי \u0003כמאן דאימני ביה מעיקרא דמי\u0004 \u0005[כמי שנמנה בו מתחילה\u0006 הוא \u0005נחשב].\u0006","ועוד מקשים: \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' הושעיא: הולך אדם\u0004 הרוצה להקריב פסחו ואין לו טלה משלו \u0003אצל רועה\u0004 שהוא \u0003רגיל אצלו ונותן לו טלה ל\u0004צורך \u0003פסחו ומקדישו ויוצא בו!\u0004 ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 יש לומר שמדובר במקרה מיוחד, ש\u0003כיון\u0004 ש\u0003רגיל אצלו,\u0004 אצל הרועה בכל שנה לצורך אותה מטרה, הרי כבר \u0003אקדושי ליה מעיקרא\u0004 \u0005[הקדישו\u0006 הרועה \u0005מתחילה],\u0006 מערב שבת. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מקדיש\"\u0004 בלשון הווה \u0003קתני\u0004 \u0005[שנינו]!\u0006 ואם היה מקודש כבר — מה מקום יש להקדישו? ומשיבים: אכן אין זה הקדש ממש, אלא \u0003הקדש עילוי,\u0004 כעין תוספת הקדשה שיקדישו הבעלים עצמם את קרבנם. ודבר זה רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 הוא.","על עיקר הדברים שואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 ככלל קבוע: \u0003הלכה\u0004 היא \u0003כסתם משנה,\u0004 כלומר משנה שלא הוזכר בה שם אומר ההלכה, \u0003ותנן\u0004 \u0005[ושנויה\u0006 משנה\u0005]:\u0006 \u0003לא מקדישין, ולא מעריכין\u0004 ערכין למקדש, \u0003ולא מחרימין\u0004 חרמות לכהנים ולמקדש, \u0003ולא מגביהין\u0004 (מפרישים) \u0003תרומות ומעשרות, כל\u0004 איסורים \u0003אלו\u0004 — \u0003ביום טוב אמרו,\u0004 ו\u0003קל וחומר בשבת!\u0004 ואיך אם כן התיר ר' יוחנן להקדיש בשבת וביום טוב? ומשיבים: \u0003לא קשיא:\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003כאן\u0004 שהתיר ר' יוחנן הרי זה \u0003בחובות שקבוע להן זמן,\u0004 שאם לא יקדיש עכשיו תיבטל המצוה לגמרי, ואילו \u0003כאן\u0004 באותה משנה שאסרו להקדיש — \u0003בחובות שאין קבוע להן זמן\u0004 ויכול להקדיש אחר השבת.","\u0003מונה אדם את אורחיו\u0004 הבאים לסעודה \u0003ואת\u0004 מיני \u0003פרפרותיו\u0004 שמוסיף לסעודה \u0003מפיו\u0004 (בעל פה), \u0003אבל לא\u0004 יקרא רשימות אלה \u0003מן הכתב,\u0004 וכפי שיבואר טעם הדבר בגמרא. \u0003מפיס\u0004 (מטיל גורל) \u0003אדם עם בניו ועם בני ביתו על השולחן\u0004 בשבת מי יקבל מנה מסויימת, \u0003ובלבד שלא יתכוין לעשות מנה גדולה כנגד מנה קטנה\u0004 אלא שתהיינה המנות שוות. \u0003ומטילין חלשין\u0004 (גורלות) בין הכהנים \u0003על הקדשים ביום טוב, אבל לא על המנות.\u0004"],["שנינו במשנה: ובלבד שלא ימנה אדם בשבת את רשימות האורחים והפרפראות מתוך הכתב. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה\u0006 \u0005הטעם]\u0006 אסרו לקרוא בשבת מן הכתב? \u0003רב ביבי אמר: גזירה שמא ימחוק\u0004 כשיתחרט על שהזמין אחד האורחים או הוסיף בפרפראות. \u0003אביי אמר: גזירה שמא\u0004 מתוך כך יבוא לקרוא \u0003בשטרי הדיוטות,\u0004 כלומר, בשטרות של מקח וממכר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם],\u0006 בין שני ההסברים? ומסבירים: \u0003איכא בינייהו דכתב\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005כשכתוב]\u0006 על ה\u0003כותל ומידלי\u0004 \u0005[ומוגבה]\u0006 למעלה מאפשרותו להגיע אליו; \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהחשש הוא \u0003שמא ימחוק —\u0004 במקרה כגון זה \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שהרי אינו יכול להגיע אל הכתוב. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי\u0006 \u0005שאומר]\u0006 כי החשש הוא \u0003שמא יקרא\u0004 מתוך כך בשטרי הדיוטות — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהחשש הוא \u0003שמא ימחוק, ניחוש\u0004 \u0005[נחשוש]\u0006 גם \u0003שמא יקרא\u0004 בספרי הדיוטות! \u0003ותו\u0004 \u0005[ועוד],\u0006 וכי \u0003לשמא ימחוק לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 כשהדבר מצוי בגובה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יקרא לאור הנר\u0004 בשבת שמא יטה אליו את הנר. \u0003ואמר רבה: אפילו\u0004 היה הנר \u0003גבוה\u0004 כ\u0003שתי קומות\u0004 אדם, \u0003אפילו גבוה\u0004 כ\u0003שתי מרדעות, אפילו\u0004 גבוה \u0003עשרה בתים זה על גבי\u0004 זה — \u0003לא יקרא.\u0004 הרי שכאשר אנו חוששים למעשה איסור איננו מחלקים בין קרוב ורחוק.","\u0003אלא, איכא בינייהו דכתב\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005כשכתוב]\u0006 על ה\u0003כותל ומיתתי\u0004 \u0005[ומונמך];\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי\u0006 \u0005שאומר]\u0006 שהחשש הוא \u0003שמא ימחוק —\u0004 במקרה כגון זה \u0003חיישינן\u0004 \u0005[אנו חוששים],\u0006 שהרי יכול להגיע אל הכתוב ולמוחקו. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי החשש הוא \u0003שמא יקרא\u0004 מתוך כך בשטרי הדיוטות — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 כי \u0003גודא בשטרא לא מיחלף\u0004 \u0005[כותל בשטר אינו מתחלף]\u0006 ולא יבוא בשל כך לקרוא בשטרות.","ושוב שואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהחשש הוא \u0003שמא יקרא, ליחוש\u0004 \u0005[נחשוש]\u0006 גם \u0003שמא ימחוק! אלא, איכא בינייהו דחייק אטבלא ואפינקס\u0004 \u0005[יש ביניהם\u0006 הבדל כשהיה הדבר \u0005חקוק בטבלה ועל פנקס];\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהחשש הוא \u0003שמא ימחוק —\u0004 במקרה \u0003כגון זה לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 שהרי כשאינו כתוב בדיו אלא בחקיקה אין חשש למחיקה. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי החשש הוא \u0003שמא יקרא\u0004 מתוך כך בשטרי הדיוטות — \u0003חיישינן\u0004 \u0005[אנו חוששים],\u0006 שהרי לענין חשש זה אין משמעות לצורה בה מופיע הכתב.","ועוד שואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהחשש הוא \u0003שמא ימחוק, ליחוש\u0004 \u0005[נחשוש]\u0006 גם \u0003שמא יקרא\u0004 בספרי הדיוטות! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003טבלא ופינקס בשטרא לא מיחלף\u0004 \u0005[בשטר אינם מתחלפים]\u0006 — \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בפירוש: \u0003מונה אדם כמה\u0004 אורחים ישבו \u0003מבפנים וכמה מבחוץ וכמה מנות עתיד להניח לפניהם מ\u0004תוך \u0003כתב שעל גבי הכותל, אבל לא מ\u0004תוך \u0003כתב שעל גבי טבלא ופינקס!\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דכתיב מיכתב\u0004 \u0005[אם תאמר שהיה כתוב]\u0006 בדיו — \u0003מאי שנא הכא ומאי שנא הכא\u0004 \u0005[מה שונה כאן ומה שונה כאן]\u0006 בכותל או בפנקס. \u0003אלא לאו\u0004 \u0005[האם\u0006 לא] מדובר כאן באופן \u0003דחייק\u0004 \u0005[ש\u0006היה \u0005חקוק],\u0006 \u0003וקתני\u0004 \u0005[\u0006בכל זאת \u0005שנינו]:\u0006 \u0003מ\u0004תוך \u0003כתב שעל גבי הכותל\u0004 מותר לקרוא \u0003אבל לא מ\u0004תוך \u0003כתב שעל גבי טבלא\u0004 או \u0003פינקס!\u0004","\u0003אלא לעולם\u0004 תפרש \u0003דכתב\u0004 \u0005[כשכתוב]\u0006 על ה\u0003כותל ומידלי\u0004 \u0005[ומוגבה],\u0006 \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 מדברי \u0003רבה\u0004 \u0005[ושהיה קשה לך מדברי רבה]\u0006 בענין קריאה בשבת לאור הנר שלדעתו היא אסורה בין שהנר גבוה ובין נמוך, ואם כן אף כן לכאורה אין לחלק בין היה הכתב גבוה בין נמוך — שיטת \u0003רבה\u0004 כבר \u0003תנאי\u0004 \u0005[\u0006במחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 שנויה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מונה אדם את אורחיו ואת פרפרותיו מפיו, אבל לא מן הכתב. ר' אחא מתיר\u0004 לקרוא \u0003מ\u0004תוך \u0003כתב שעל גבי הכותל.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006 הדבר\u0005]?\u0006 \u0003אילימא דכתיב מתתא\u0004 \u0005[אם נאמר שכתוב מלמטה]\u0006 — \u0003ליחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא ימחוק! אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן באופן \u0003דכתב ומידלי\u0004 \u0005[שכתוב ומוגבה],\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ששיטת \u0003רבה תנאי\u0004 \u0005[\u0006במחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 שנויה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ומעירים שבענין זה כולו \u0003הני תנאי כהני תנאי\u0004 \u0005[תנאים אלה כתנאים אלה,\u0006 אחרים\u0005]\u0006 שנחלקו בכך. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין רואין במראה בשבת\u0004 שמא יראה על עצמו שערה מדולדלת ויתלשנה. \u0003ר' מאיר מתיר במראה הקבוע בכותל.\u0004 והבינו שדעתו כיון שקבועה המראה בכותל יש בכך משום היכר, וכפי שהותר לקרוא מכתב שעל הכותל.","ומקשים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 מראה \u0003הקבוע בכותל\u0004 — \u0003דאדהכי והכי מדכר\u0004 \u0005[שבין כה וכה נזכר],\u0006 שעד שהוא הולך להביא מספריים וכיוצא בהם נזכר ששבת היום, ומאחר שזו הסיבה אם כן מראה \u0003שאינו קבוע נמי\u0004 \u0005[גם כן]\u0006 אמור: \u0003אדהכי והכי מדכר\u0004 \u0005[בין כה וכה נזכר]!\u0006","אלא \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003במראה של מתכת עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003וכ\u0004מו ש\u0003רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה.\u0004 ש\u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה : מפני מה אמרו\u0004 חכמים ש\u0003מראה של מתכת אסורה\u0004 להסתכל בה בשבת — \u0003מפני שאדם עשוי להשיר בה\u0004 (במראה עצמה) \u0003נימין\u0004 (שערות) \u0003המדולדלין\u0004 שקצהו חד ועשוי גם לחתוך, ולכן אם קבועה בכותל — אין לחשוש לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כתב המהלך תחת הצורה\u0004 (תמונה) או \u0003תחת הדיוקנאות\u0004 — \u0003אסור לקרותו בשבת\u0004 שמא יקרא בשטרי הדיוטות. \u0003ודיוקנא\u0004 (תמונה) של עבודה זרה \u0003עצמה\u0004 — \u0003אף בחול אסור להסתכל בה, משום שנאמר \"אל תפנו אל האלילים\u0004 ואלוהי מסכה לא תעשו לכם אני ה' אלוהיכם\u0003\"\u0004 (ויקרא יט, ד) ושואלים: \u0003מאי תלמודא\u0004 \u0005[מהו הלימוד]\u0006 שמוצאים אנו בפסוק זה לאסור הסתכלות בצורות? \u0003אמר ר' חנין: אל תפנו אל מדעתכם,\u0004 כלומר, אל תוציאו את המחשבה בה' מלבכם על ידי הסתכלות זו (הערוך).","שנינו במשנה ש\u0003מפיס\u0004 (מטיל גורל) \u0003אדם עם בניו\u0004 ועם בני ביתו על השולחן בשבת מי יקבל מנה מסויימת. ומדייקים: \u0003עם בניו ועם בני ביתו אין\u0004 \u0005[כן,\u0006 מותר\u0005],\u0006 \u0003ו\u0004אולם \u0003עם אחר\u0004 — \u0003לא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומסבירים: הוא \u0003כ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל.\u0004 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל : בני חבורה\u0004 האוכלים יחד בשבת או ביום טוב \u0003המקפידין זה על זה\u0004 שלא יקבל אחד חלק גדול יותר מחבירו — \u0003עוברין משום מדה ומשום משקל ומשום מנין\u0004 של מסחר בשבת וביום טוב שאסור בכל אלה, \u0003ומשום\u0004 איסור של \u0003לווין ופורעין ביום טוב,\u0004"],["\u0003וכדברי הלל\u0004 עובר \u0003אף משום\u0004 איסור \u0003רבית,\u0004 שלדעתו אין מלווים חפצים בעין אלא אם כן העריכום בכסף.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש לחשוש לכל האיסורים הללו ב\u0003בניו ובני ביתו נמי\u0004 \u0005[גם כן]\u0006 נאסור עליו משום החששות הללו! ומשיבים: לענין זה \u0003בניו ובני ביתו היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 — \u0003כ\u0004דברי \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003רב: מותר להלוות בניו ובני ביתו ברבית כדי להטעימן טעם רבית\u0004 שילמדו כמה קשה תשלום של ריבית, וכיון שהכל, גם כסף התשלומים, משלו אין כאן איסור ריבית.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהכל משלו ולא נעשה אלא לשם חינוך, \u0003מנה גדולה כנגד מנה קטנה נמי\u0004 \u0005[גם כן]\u0006 יותר לו לחלק!","ומשיבים: \u0003אין הכי נמי, וחסורי מיחסרא והכי קתני\u0004 \u0005[כן כך\u0006 הוא \u0005גם כן, וחסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003מפיס אדם עם בניו ובני ביתו על השלחן אפילו מנה גדולה כנגד מנה קטנה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כ\u0004דעת \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003רב: עם בניו ועם בני ביתו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יכול הוא להפיס, ואולם \u0003עם אחרים\u0004 — \u0003לא. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כ\u0004דעת \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בשם \u0003שמואל: מנה גדולה כנגד מנה קטנה\u0004 — \u0003אף בחול לאחרים אסור. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום\u0004 האיסור שבמשחק \u0003קוביא,\u0004 שיש בו משום גזל מדברי חכמים.","שנינו במשנה ש\u0003מטילין חלשין\u0004 (גורלות) \u0003על\u0004 הקרבנות, אבל לא על המנות. לשון זו אינה ברורה, ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 המשמעות\u0005]\u0006 של מה שאמרו: \u0003אבל לא על המנות? אמר ר' יעקב בריה\u0004 \u0005[בנה]\u0006 של \u0003בת יעקב,\u0004 הכוונה היא: \u0003אבל לא\u0004 מטילים גורל \u0003על המנות של חול ביום טוב.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"\u0004אך איש אל ירב ואל יוכח איש \u0003ועמך כמריבי כהן\"\u0004 (הושע ד, ד), וכאן למדים שהכהנים בעלי מריבה הם, ואולי כדי למנוע מריבה ביניהם, \u0003אפילו\u0004 על \u0003מנות\u0004 של \u0003חול נמי\u0004 \u0005[גם כן]\u0006 יתירו להטיל גורלות על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין היתר בכגון זה.","ובשל הזכרת דברי אמורא זה מוסיפים ומביאים עוד את מה ש\u0003אמר ר' יעקב בריה\u0004 \u0005[בנה]\u0006 של \u0003בת יעקב: כל\u0004 מי שגרם \u0003שחבירו נענש על ידו\u0004 — \u0003אין מכניסין אותו במחיצתו של הקדוש ברוך הוא\u0004 אפילו אם היה צודק. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בנבואת מיכיהו \u0003\"ויאמר ה' מי יפתה את אחאב ויעל ויפל ברמת גלעד ויאמר זה בכה וזה אמר בכה. ויצא הרוח ויעמד לפני ה' ויאמר אני אפתנו\u0004 ויאמר ה' אליו במה. \u0003ויאמר אצא והייתי רוח שקר בפי כל נביאיו ויאמר תפתה וגם תוכל צא ועשה כן\"\u0004 (מלכים א, כב, כ-כב),","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 היא \u0003רוח\u0004 זו? \u0003אמר ר' יוחנן: זה רוחו של נבות\u0004 היזרעאלי שביקש לנקום מאחאב שהרגו. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"צא\"\u0004 שאמר לו השם? \u0003אמר רב:\u0004 הכוונה היא שאמנם ניתנה לך רשות לעשות כן, אבל \u0003צא ממחיצתי.\u0004 ולכאורה הוצא ממחיצת השם משום שגרם להעניש את אחאב. ודוחים: \u0003ודילמא התם היינו טעמא\u0004 \u0005[ושמא שם זהו הטעם]\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"דבר שקרים, לא יכון\u0004 לנגד עיני\" (תהלים קא, ז), ורק מחמת טעם זה הוצא ממחיצתו של הקדוש ברוך הוא?!","\u0003אלא מהכא\u0004 \u0005[מכאן]:\u0006 שהפסוק \u0003\"שבעת קלון מכבוד שתה גם אתה והערל\u0004 תסוב עליך כוס ימין ה' וקיקלון על כבודך\u0003\"\u0004 (חבקוק ב' טז), נדרש: \u0003\"שבעת קלון מכבוד\u0004 — \u0003זה נבוכדנצר, \"שתה גם אתה והערל\"\u0004 — \u0003זה צדקיה,\u0004 שאף הוא נענש משום שגרם לנבוכדנצר שייענש, וכמו שיבואר בהמשך הדברים. אך יש לדחות את הראיה: \u0003חדא, דכוליה קרא\u0004 \u0005[אחת, שכל הכתוב]\u0006 הזה \u0003בנבוכדנצר כתיב\u0004 \u0005[נאמר].\u0006 \u0003ועוד: צדקיה צדיקא\u0004 \u0005[הצדיק]\u0006 \u0003מאי הוה ליה למיעבד ליה\u0004 \u0005[מה היה יכול לעשות לו],\u0006 וכפי ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב\u0004 להלן בענין זה: \u0003בשעה שבקש אותו רשע לעשות לאותו צדיק כך\u0004 נמשכה ערלתו וכו'.","\u0003אלא\u0004 לא מכאן הראיה כי אם \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"גם ענוש לצדיק לא טוב\"\u0004 (משלי יז כו), כלומר, לא טוב שהצדיק מעניש, \u0003אין \"לא טוב\" אלא רע, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי לא אל חפץ רשע אתה לא יגרך רע\"\u0004 (תהילים ה, ה), כלומר, \u0003צדיק אתה ה' ולא יגור במגורך\u0004 \u0005[\u0006יחד \u0005אתך]\u0006 \u0003רע.\u0004 והצדיק המעניש אף הוא קרוי \"רע\".","ושואלים: \u0003מאי משמע דהאי\u0004 \u0005[שזה]\u0006 הלשון ששנינו במשנה \u0003\"חלשים\" לישנא דפורא\u0004 \u0005[לשון של גורל]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"איך נפלת משמים הילל בן שחר נגדעת לארץ חולש על גוים\"\u0004 (ישעיה יד, יב), ו\u0003אמר רבה בר רב הונא:\u0004 פסוק זה \u0003מלמד שהיה מטיל פור\u0004 (\"חולש\") \u0003על גדולי מלכות\u0004 (גויים), \u0003לידע איזה בן יומו של משכב זכור. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כל מלכי גוים כלם\u0004 שכבו בכבוד איש בביתו\u0003\"\u0004 (ישעיה יד, יח), ו\u0003אמר ר' יוחנן:\u0004 משמעו של הכתוב — \u0003שנחו ממשכב זכור.\u0004","\u0003ואמר ר' יוחנן: כל ימיו של אותו רשע לא נמצא שחוק בפה כל בריה, שנאמר: \"נחה שקטה כל הארץ פצחו רנה\"\u0004 (ישעיה יד, ז), ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לא הוה\u0004 \u0005[היתה]\u0006 \u0003רנה.\u0004","\u0003ואמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן: אסור לעמוד\u0004 כעת אפילו \u0003ב\u0004חורבות \u0003ביתו של אותו רשע\u0004 (נבוכדנצר) בבבל, \u0003ש\u0004כן \u0003נאמר\u0004 על אותו מקום: \u0003\"ושעירים ירקדו שם\"\u0004 (ישעיה יג, כא), ויש לחשוש מפני המזיקים המצויים שם (מהרש\"א).","\u0003ואמר רב יהודה\u0004 שכך \u0003אמר רב: בשעה שביקש אותו רשע,\u0004 נבוכדנצר, \u0003לעשות לאותו\u0004 ה\u0003צדיק,\u0004 צדקיה, \u0003כך, נמשכה ערלתו שלש מאות אמה, והיתה מחזרת על כל המסיבה כולה. שנאמר:\u0004 \"הוי משקה רעהו מספח חמתך ואף שכר למען הביט על מעוריהם. \u0003שבעת קלון מכבוד שתה גם אתה והערל\"\u0004 (חבקוק ב' טו-טז), \u0003ער\"ל בגימטריא שלש מאות הוי\u0004 \u0005[הם].\u0006","\u0003ו\u0004עוד\u0003 אמר רב יהודה\u0004 שכך \u0003אמר רב : בשעה שירד אותו רשע לגיהנם רעשו כל יורדי גיהנם,\u0004 ו\u0003אמרו: שמא למשול עליהם הוא בא, או ליחלות כמותם הוא בא? שנאמר:\u0004 \"כולם יענו ויאמרו אליך \u0003גם אתה חלית כמונו אלינו נמשלת\"\u0004 (ישעיה יד, י) \u0003יצאתה\u0004 (יצאה) \u0003בת קול ואמרה: \"ממי נעמת רדה והשכבה את ערלים\"\u0004 (יחזקאל לב, יט), לומר שמעמדו בגיהנם כשל כל יורדי הגהינם האחרים.","ובאותו ענין, על מה שנאמר: \u0003\"\u0004ונשאת המשל הזה על מלך בבל ואמרת \u0003איך שבת נגש שבתה מדהבה\"\u0004 (ישעיה יד, ד), \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב :\u0004 משמעות הכתוב היא ש\u0003שבתה אומה זו שאמרה\u0004"],["\u0003מדוד והבא\u0004 ממון רב. \u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שמשמעות הכתוב היא \u0003שאמרה \"מאד מאד הביא בלא מדה\".\u0004","ועוד על נבוכדנצר, נאמר בו \u0003\"ורבו יתירה הוספת לי\"\u0004 \u0005[וגדולה יתירה נוספה לי]\u0006 (דניאל ד, לג), ועל כך \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב ירמיה בר אבא: מלמד שרכב\u0004 נבוכדנצר \u0003על ארי זכר, וקשר תנין בראשו,\u0004 וכל זה \u0003לקיים\u0004 את \u0003מה שנאמר\u0004 בו: \u0003\"וגם את חית השדה נתתי לו לעבדו\"\u0004 (ירמיה כז, ו).","\u0003לא ישכור אדם פועלים בשבת\u0004 שיעשו מלאכתו לאחר השבת, לפי שאף דיבורי חול אסורים בשבת. \u0003ו\u0004כן \u0003לא יאמר אדם לחבירו\u0004 בשבת \u0003לשכור לו פועלים.\u0004 אף \u0003אין מחשיכין\u0004 לשהות סמוך למוצאי שבת \u0003על\u0004 קצה \u0003התחום\u0004 של שבת, כדי שיוכל מיד עם יציאת השבת ללכת מחוץ לתחום \u0003לשכור לו פועלים ו\u0004כן \u0003להביא פירות, אבל מחשיך הוא\u0004 על התחום כדי \u0003לשמור\u0004 פירות שמחוץ לתחומו, \u0003ו\u0004כמו כן הוא \u0003מביא\u0004 מלכתחילה \u0003פירות בידו\u0004 אם לא נתכוון מתחילה להחשיך על קצה התחום לשם כך. \u0003כלל אמר אבא שאול: כל שאני זכאי\u0004 (מותר) \u0003באמירתו\u0004 בשבת — \u0003רשאי אני להחשיך עליו.\u0004","שנינו בתחילת המשנה שלא ישכור אדם פועלים בשבת, וכן לא יאמר לחבירו לשכור לו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003הוא ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003חבירו?\u0004 שאם אסור לאדם לשכור פועלים — הרי גם לחבירו אסור! \u0003אמר רב פפא:\u0004 מדובר כאן ב\u0003חבר גוי. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 הלא דבר זה אסור מצד עצמו, שכן \u0003אמירה לגוי\u0004 לעשות דבר האסור לישראל אף היא אסורה משום \u0003שבות!\u0004","\u0003אלא אמר רב אשי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר ב\u0003חבירו ישראל,\u0004 יש לומר כי החידוש אינו בעצם הדברים, כי אם במה שאפשר ללמוד מהם, ו\u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003לא יאמר אדם לחבירו\u0004 במפורש בשבת \u0003\"שכור לי פועלים\", אבל אומר אדם לחבירו \"הנראה שתעמוד עמי לערב\"\u0004 במוצאי שבת? ושניהם מבינים שכוונתו לשכרו. \u0003ומתניתין מני\u0004 \u0005[ומשנתנו\u0006 כשיטת \u0005מי היא]\u0006 — \u0003כ\u0004שיטת \u0003ר' יהושע בן קרחה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יאמר אדם לחבירו\u0004 בשבת \u0003\"הנראה שתעמוד עמי לערב\".\u0004 ו\u0003ר' יהושע בן קרחה אומר: אומר אדם לחבירו\u0004 בשבת \u0003\"הנראה שתעמוד עמי לערב\".\u0004","\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: הלכה כ\u0004שיטת \u0003ר' יהושע בן קרחה. ואמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהושע בן קרחה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפסוק שממנו למדים אנו עיקרו של איסור זה: \u0003\"\u0004וכבדתו מעשות דרכיך \u0003ממצוא חפצך ודבר דבר\"\u0004 (ישעיה נח, יג), ונדייק: \u0003דיבור\u0004 מפורש — \u0003אסור, הרהור\u0004 — \u0003מותר.\u0004","\u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב אחא בר רב הונא לרבא: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יוחנן\u0004 כלל ש\u0003דיבור אסור\u0004 ו\u0003הרהור מותר,\u0004 ומאחר וידוע שכך אמר, וכאמור, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הרהור לאו\u0004 \u0005[לא]\u0006 \u0003כדיבור דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: בכל מקום מותר להרהר\u0004 בדברי תורה, \u0003חוץ מבית המרחץ ומבית הכסא,\u0004 ונמצא איפוא שאף הרהור כדיבור, שהרי באותם מקומות אסור גם הדיבור! ומשיבים: \u0003שאני התם, דבעינן\u0004 \u0005[שונה שם, שאנו צריכים],\u0006 ביחס לדברי תורה, לקיים את הכתוב \"כי ה' אלוהיך מתהלך בקרב מחנך להצילך ולתת אויביך לפניך \u0003והיה מחניך קדוש\u0004 ולא יראה בך ערות דבר ושב מאחריך\" (דברים כג, טו), \u0003ו\u0004במקום המטונף \u0003ליכא\u0004 \u0005[אין]\u0006 תנאי זה של \"מחנך קדוש\", כמבואר בכתוב.","ומקשים: והלא \u0003הכא נמי כתיב\u0004 \u0005[כאן\u0006 בבית המרחץ ובית הכסא \u0005גם כן נאמר]\u0006 \u0003\"ולא יראה בך ערות דבר\"\u0004 ונוכל לדייק באותו אופן: דיבור ולא הרהור. ומשיבים: הכתוב \u0003ההוא\u0004 לא לענין דיבור נאמר, אלא \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004מה שאמר \u0003רב יהודה\u0004 שכן \u0003אמר רב יהודה: גוי ערום\u0004 — \u0003אסור לקרות קרית שמע כנגדו\u0004 משום שאף בכך יש משום \"ערות דבר\".","ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 איסור זה דווקא ב\u0003גוי, אפילו ישראל נמי\u0004 \u0005[גם כן\u0006 אסור\u0005]?!\u0006 ומשיבים: \u0003\"לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003\" קאמר\u0004 \u0005[אמר].\u0006 ומפרשים: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003ישראל\u0004 שבוודאי \u0003אסור\u0004 לקרוא כנגדו כשהוא ערום, \u0003אבל גוים כיון דכתיב ביה\u0004 \u0005[שנאמר בו,\u0006 בהם\u0005]:\u0006 \u0003\"אשר בשר חמורים בשרם\"\u0004 (יחזקאל כג, כ), ואין כאן דין ערוה, ואם כן \u0003אימא שפיר דמי\u0004 \u0005[אמור\u0006 ש\u0005יפה הדבר,\u0006 מותר\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף בגוי אסור.","ושואלים: \u0003אימא הכי נמי\u0004 \u0005[\u0006ו\u0005אמור\u0006 ש\u0005כך\u0006 הוא \u0005גם כן\u0006 הדין\u0005],\u0006 שבפני גוי ערום יהא מותר?! ודוחים: כבר \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בבני נח: \u0003\"\u0004וילכו אחורנית ויכסו את ערות אביהם ופניהם אחורנית \u0003וערות אביהם לא ראו\"\u0004 (בראשית ט, כג), משמע שאף זו קרויה \"ערוה\".","על עיקרו של הדין שואלים: \u0003ודיבור\u0004 בשבת \u0003מי אסיר\u0004 \u0005[האם אסור]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חסדא ורב המנונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003חשבונות של מצוה\u0004 — \u0003מותר לחשבן בשבת. ואמר ר' אלעזר:\u0004 כוונת הדברים היא ש\u0003פוסקים צדקה לעניים בשבת. ואמר ר' יעקב בר אידי\u0004 שכך \u0003אמר ר' יוחנן: מפקחין\u0004 (דואגים) ל\u0003פיקוח נפש ופיקוח רבים\u0004 לעשות בדברים הנוגעים לצרכי הרבים \u0003בשבת, והולכין לבתי כנסיות לפקח על עסקי רבים בשבת.\u0004","\u0003ואמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יוחנן: הולכין לטרטיאות\u0004 (תיאטרונות) \u0003ולקרקסאות ולבסילקאות\u0004 (היכלות שבהם נערכים משפטים) \u0003לפקח על עסקי רבים בשבת. ו\u0004כן \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: משדכין\u0004 (עושים את הסידורים וההסכמים) \u0003על התינוקות ליארס\u0004 (להתארס) זה לזה \u0003בשבת, ו\u0004כן מגיעים להסכם \u0003על התינוק ללמדו\u0004 לקרוא ב\u0003ספר וללמדו אומנות,\u0004 ואם דיבור אסור בשבת, איך יעשו כל אלה?! ומשיבים: כל אלה מותרים, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ממצוא חפצך ודבר דבר\",\u0004 ומשמע: רק \u0003חפציך\u0004 — \u0003אסורים\u0004 בדיבור בהם בשבת, ואולם \u0003חפצי שמים\u0004 — \u0003מותרין.\u0004","\u0003אמר רב יהודה אמר שמואל: חשבונות של מלך\u0004 (=\"מה לך\"), כלומר, של דברים שמה לו ולהם, שאין לו נגיעה בהם ואינם חשבונותיו שלו, \u0003ושל מה בכך,\u0004 שהם דברים שאין להם חשיבות מעשית — \u0003מותר לחשבן בשבת. תניא נמי הכי\u0004 \u0005[שנויה\u0006 תוספתא \u0005גם כן כך]:\u0006 \u0003חשבונות\u0004 של דברים \u0003שעברו ושעתידין להיות\u0004 — \u0003אסור לחשבן\u0004 בשבת. ואולם חשבונות \u0003של מלך\u0004"],["\u0003ושל מה בכך\u0004 — \u0003מותר לחושבן.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003חושבין חשבונות שאינן צריכין, ואין מחשבין חשבונות שצריכין, בשבת. כיצד? אומר אדם לחבירו: \"כך וכך פועלים הוצאתי על שדה זו, כך וכך דינרין הוצאתי על דירה זו\". אבל לא יאמר לו: \"כך וכך הוצאתי, וכך וכך אני עתיד להוציא\"!\u0004 נמצא שדברים שעברו מותר לחשבן בשבת.","ודוחים: \u0003ולטעמיך, קשיא\u0004 \u0005[ולטעמך,\u0006 לשיטתך \u0005קשה]\u0006 \u0003לך היא,\u0004 התוספתא שהובאה ראשונה, \u0003גופא\u0004 \u0005[עצמה]!\u0006 שהרי אוסרת חשבונות שעברו, ומתירה חשבונות של מה בכך. \u0003אלא,\u0004 יש להסביר: \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאסור לחשב חשבונות עבר — הרי זה באופן \u0003דאיכא אגרא דאגירא גביה\u0004 \u0005[שיש שכר השכיר בידו]\u0006 ועדיין לא שילם. שאף שהוא חשבון של עבר יש בכך תועלת גם לעתיד. ואולם \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמותר — הרי זה באופן \u0003דליכא אגרא דאגירא גביה\u0004 \u0005[שאין שכר השכיר בידיו],\u0006 ולכך אין לכך כל משמעות.","שנינו במשנה ש\u0003אין מחשיכין\u0004 על תחום שבת כדי שיוכל מיד עם צאת השבת לשכור לו פועלים או להביא פירות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בחסיד אחד שנפרצה לו פרץ בתוך\u0004 הגדר שב\u0003שדהו, ונמלך עליה,\u0004 כשראה את הפרצה, \u0003לגודרה, ונזכר ששבת הוא, ונמנע אותו חסיד ולא גדרה\u0004 אף פעם, משום שהרהר בשבת לעשות את הדבר, \u0003ונעשה לו נס, ועלתה בו\u0004 באותו מקום פרוץ \u0003צלף\u0004 שסגר את הפרצה, \u0003וממנה\u0004 (מפירותיה) גם \u0003היתה\u0004 אחר כך \u0003פרנסתו ופרנסת אנשי ביתו.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מותר לאדם לומר לחבירו\u0004 בשבת \u0003\"לכרך פלוני אני הולך למחר\", ש\u0004כן \u0003אם יש בורגנין\u0004 (בתים קטנים של שומרי השדות והתחומים) — הרי הם מחשיבים את שני המקומות כעיר אחת, ו\u0003הולך\u0004 מלכתחילה ממקום למקום, שהרי גם בשבת עצמה מותר היה לו ללכת שם. ומאחר ובמקום שיש בורגנים בין הערים מותר לו ללכת, לכן גם אם אין בורגנים מותר לו לומר \u0003שהולך\u0004 לכרך אחר. שדבר שיש אפשרות מסויימת לעשותו בשבת בהיתר, מותר לדבר בו ולהכינו גם אם אין ההיתר מצוי במקרה זה.","\u0003תנן\u0004 \u0005[\u0006במשנתנו \u0005שנינו]:\u0006 \u0003אין מחשיכין על התחום לשכור פועלים ולהביא פירות. בשלמא\u0004 \u0005[נניח]\u0006 שאסור \u0003לשכור פועלים\u0004 משום ש\u0003בשבת לא מצי אגר\u0004 \u0005[אינו יכול לשכור]\u0006 בכל דרך, \u0003אלא להביא פירות\u0004 מדוע אסור? \u0003לימא\u0004 \u0005[שיאמר]:\u0006 \u0003ש\u0004הרי \u0003אם יש שם מחיצות\u0004 — \u0003מביא\u0004 מלכתחילה, ועל כן יותר לו להחשיך להביאם גם כשאין מחיצות על פי שיטתו של רב יהודה בדבר! ומשיבים: \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות של איסור גמור לקחת פירות \u0003בפירות המחוברים,\u0004 שאין כל דרך היתר לתולשם בשבת.","ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' אושעיא: אין מחשיכין על התחום להביא תבן וקש, בשלמא\u0004 \u0005[נניח]\u0006 מה ששנינו שאסור להחשיך לצורך הבאת \u0003קש,\u0004 שבכגון זה מובן הדבר, שהרי \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות לאיסור \u0003ב\u0004קש שעדיין \u0003מחובר,\u0004 ואין דרך לקוצצו. \u0003אלא תבן\u0004 שהוא קש קצוץ, \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 אפשרות שיהיה אסור לטלטלו בשבת גם על ידי מחיצות? ומשיבים: \u0003בתיבנא סריא\u0004 \u0005[בתבן שהסריח],\u0006 שאסור לטלטלו בשבת משום מוקצה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר ממה ששנינו במקום אחר: \u0003מחשיכין\u0004 בשבת \u0003על התחום\u0004 כדי \u0003לפקח\u0004 (לדאוג) \u0003על עסקי כלה ועל עסקי המת.\u0004 ונדייק: \u0003על עסקי כלה ומת\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 \u0003על עסקי אחר\u0004 — \u0003לא.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אחר דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כלה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות שיהא בכך דבר האסור בשבת כגון: \u0003למיגזא ליה אסא\u0004 \u0005[לחתוך לו הדס],\u0006 כדרך שעושים לכלה, ודבר זה אסור לעשותו בשבת. \u0003אלא מת מאי ניהו\u0004 \u0005[מה הוא]\u0006 הדבר שיש לעשות עבורו? — \u0003להביא לו ארון ותכריכין. וקתני\u0004 \u0005[ושנינו]\u0006 שב\u0003מת\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר, \u0003אבל\u0004 ב\u0003אחר\u0004 — \u0003לא.\u0004","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 ייאסר? \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003ש\u0004כן \u0003אם יש שם מחיצות\u0004 — הלא \u0003מביא,\u0004 ואם כן אף כאשר אין מחיצות מותר להחשיך שם כדי להביאת בצאת השבת, לפי כללו של רב יהודה! ומשיבים: ב\u0003מת נמי משכחת לה\u0004 \u0005[גם כן מוצא אתה אותה]\u0006 אפשרות שהוא מחשיך כדי \u0003למיגזא ליה גלימא\u0004 \u0005[לחתוך עבורו גלימה,\u0006 תכריך\u0005]\u0006 שאין לדבר היתר בשבת כלל, ולכן אסור גם להחשיך על התחום אלא עבור צורך המת שיש בכך מצוה.","שנינו במשנה: \u0003אבל מחשיכין\u0004 על התחום לשמור פירות. ושואלים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא אבדיל\u0004 \u0005[הבדיל,\u0006 ברך ברכת הבדלה\u0005]\u0006 במוצאי שבת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר בן אנטיגנוס משום\u0004 (בשם) \u0003ר' אליעזר בן יעקב: אסור לו לאדם שיעשה חפציו\u0004 של חול במוצאי שבת \u0003קודם שיבדיל! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 מדובר כאן באופן \u0003דאבדיל\u0004 \u0005[ש\u0006כבר \u0005הבדיל]\u0006 \u0003בתפלה\u0004 בנוסח שהתקינו חכמים להבדיל במוצאי שבת בברכת \"חונן הדעת\" — \u0003והאמר\u0004 \u0005[והרי\u0006 כבר \u0005אמר]\u0006 \u0003רב יהודה\u0004 שכך \u0003אמר שמואל: המבדיל בתפלה צריך\u0004 בכל זאת \u0003שיבדיל על הכוס! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר כאן באופן \u0003דאבדיל\u0004 \u0005[ש\u0006כבר \u0005הבדיל]\u0006 \u0003על הכוס, כוס בשדה מי איכא\u0004 \u0005[האם ישנה]?!\u0006 \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003ר' נתן בר אמי קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא :\u0004 במקרה מיוחד שהיה קצה התחום \u0003בין הגיתות\u0004 ולקח יין מן הגת והבדיל עליו \u0003שנו\u0004 כאן.","הסבר אחר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: במערבא אמרינן הכי\u0004 \u0005[במערב,\u0006 בארץ ישראל \u0005אומרים אנו כך]\u0006 לאחר צאת השבת: \u0003\"המבדיל בין קודש לחול\" ועבדינן צורכין\u0004 \u0005[ואנו עושים צרכינו],\u0006 ואין צורך בהבדלה על הכוס כדי להתיר לעשות מלאכה, וייתכן איפוא שהמשנה מדברת במקרה כגון זה. וכעין זה \u0003אמר רב אשי: כי הוינא בי\u0004 \u0005[כאשר הייתי בבית]\u0006 \u0003רב כהנא\u0004 ראיתי כי \u0003הוה אמר\u0004 \u0005[היה אומר]\u0006 בצאת השבת \u0003\"המבדיל בין קודש לחול\" ומסלתינן סילתי\u0004 \u0005[והיינו חותכים עצים]\u0006 להארה ולהסקה.","שנינו במשנה: \u0003כלל אמר אבא שאול: כל שאני\u0004 זכאי (מותר) באמירתו בשבת — מותר להחשיך עליו. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003אבא שאול אהייא\u0004 \u0005[על איזה]\u0006 חלק מן המשנה מוסבים דבריו? \u0003אילימא ארישא קאי\u0004 \u0005[אם תאמר\u0006 כי \u0005על ראש\u0006 המשנה הוא \u0005עומד,\u0006 מתייחס\u0005]\u0006 ששנינו בה: \u0003\"אין מחשיכין על התחום לשכור פועלים\u0004 ו\u0003להביא פירות\"\u0004 —"],["הלא \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"כל שאני זכאי\u0004 (מותר) \u0003באמירתו רשאי אני בחשיכתו\"\u0004 אינו מתאים, אלא להיפך בלשון שלילה: \u0003\"כל שאיני זכאי באמירתו איני רשאי בחשיכתו\" מיבעי ליה\u0004 \u0005[צריך לו]\u0006 לומר, כנוסח תחילת המשנה! \u0003אלא\u0004 אם נאמר כי \u0003אסיפא קאי\u0004 \u0005[על סוף\u0006 המשנה \u0005הוא עומד,\u0006 מתייחס\u0005]\u0006 ששנינו: \u0003\"אבל מחשיך הוא לשמור ומביא פירות בידו\",\u0004 אולם אף כך אין הלשון מתאימה, ולהיפך \u0003\"כל שאני זכאי בחשיכתו רשאי אני באמירתו\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר!","ומסבירים: \u0003לעולם אסיפא קאי\u0004 \u0005[על סוף\u0006 המשנה \u0005הוא עומד,\u0006 מתייחס\u0005],\u0006 \u0003ואבא שאול אהא קאי\u0004 \u0005[על\u0006 דבר \u0005זה עומד,\u0006 מתייחס\u0005]\u0006 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: מותר לאדם לומר לחבירו\u0004 בשבת \u0003\"שמור לי פירות\u0004 שלי \u0003שבתחומך, ואני אשמור לך פירות\u0004 שלך \u0003שבתחומי\", ו\u0004הוא הדבר ש\u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003אבא שאול לתנא קמא\u0004 \u0005[הראשון]:\u0006 \u0003מי לא מודית\u0004 \u0005[האם אינך מודה]\u0006 ש\u0003מותר אדם לומר לחבירו\u0004 בכגון זה: \u0003\"שמור לי פירות שבתחומך ואני אשמור לך פירות שבתחומי\",\u0004 שהתיר אבא שאול גם להחשיך על התחום לצורך שמירה כזו.","ועדיין מקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 רק: \u0003\"כל שאני זכאי באמירתו\u0004 — \u0003רשאי אני להחשיך עליו\",\u0004 ואולם הביטוי \u0003\"כלל\u0004 אמר אבא שאול \u0003\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 בא? ומשיבים: \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא,\u0006 לרבות את \u0005זה ששנו חכמים]\u0006 בתוספתא: \u0003אין מחשיכין על התחום\u0004 כדי \u0003להביא\u0004 בצאת השבת \u0003בהמה. היתה עומדת חוץ לתחום\u0004 — \u0003קורא לה והיא באה. כלל אמר אבא שאול: כל שאני זכאי באמירתו\u0004 — \u0003רשאי אני להחשיך עליו.\u0004 שכיון שזכאי בקריאה (אמירה) לבהמה — מותר לו גם להחשיך על התחום לצורך זה.","ועוד אמרו: \u0003ומחשיכין\u0004 לדעת הכל כדי \u0003לפקח על עסקי כלה ועל עסקי המת להביא לו ארון ותכריכין. ואומרים לו\u0004 לשליח בשבת: \u0003\"לך למקום פלוני\u0004 לקנותם, \u0003ואם לא מצאת במקום פלוני\u0004 — \u0003הבא ממקום פלוני. לא מצאת במנה\u0004 \u0005[מאה\u0006 דינרים\u0005]\u0006 — \u0003הבא במאתים\".\u0004 ואילו \u0003ר' יוסי בר' יהודה אומר:\u0004 מותר לתת הוראות לשליח \u0003ובלבד שלא יזכיר לו סכום מקח\u0004 וכספים במפורש.","\u0003מחשיכין על התחום לפקח\u0004 (לדאוג) \u0003על עסקי כלה, ועל עסקי המת להביא לו ארון ותכריכים. גוי שהביא חלילין בשבת\u0004 כדי לחלל בהם בתוך ההספד והלוויה — \u0003לא יספוד בהן ישראל, אלא אם כן באו ממקום קרוב\u0004 שהיה בתוך התחום, שלא נעשתה עבירה בהבאת החלילים. מי ש\u0003עשו לו\u0004 גויים \u0003ארון וחפרו לו קבר\u0004 בשבת, אם נמלכו למסור את הקבר לאחר — \u0003יקבר בו ישראל. ואם בשביל ישראל\u0004 נעשה מתחילה — \u0003לא יקבר בו עולמית.\u0004","שנינו במשנה שהגוי המביא ממקום קרוב מותר לישראל להשתמש בו. ושאלו \u0003: מאי\u0004 \u0005[מהו\u0006 בדיוק\u0005]\u0006 \u0003ממקום קרוב? רב אמר: ממקום קרוב ממש,\u0004 שאנו יודעים בדיוק מהיכן הובאו. \u0003ושמואל אמר:\u0004 גם אם אין אנו יודעים, \u0003חיישינן\u0004 \u0005[חוששים,\u0006 משערים \u0005אנו]\u0006 \u0003שמא חוץ לחומה לנו\u0004 החפצים ובתוך תחום שבת, ולא נעשתה אם כן עבירה בהבאתם. ואין איסור בכך אלא אם כן ידוע בבירור שהובאו ממקום רחוק. על כל פנים מצאנו שנחלקו רב ושמואל במקרה סתם שלא נתבררו כל פרטיו, האם להחמיר או להקל בו.","ומעירים: \u0003דיקא מתניתין כוותיה\u0004 \u0005[מדוייקת המשנה כשיטתו]\u0006 של \u0003שמואל, דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה: \u0003\"עשה לו\u0004 הגוי \u0003ארון\u0004 לצורך מישהו מסויים \u0003וחפר לו קבר\u0004 אם אחר כך נמלך להעבירו לרשות אחר — \u0003יקבר בו ישראל\" אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מספיקא שרי\u0004 \u0005[מספק מותר]\u0006 ואין מניחים שעבור ישראל עשה מתחילה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בהבאת החלילים \u0003מספיקא שרי\u0004 \u0005[מספק מותר].\u0006","\u0003ותניא כוותיה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: עיר שישראל וגוים דרים בה, והיתה בה מרחץ המרחצת בשבת, אם רוב גוים\u0004 בעיר — \u0003לערב,\u0004 במוצאי שבת, \u0003רוחץ בה\u0004 ישראל \u0003מיד.\u0004 ו\u0003אם רוב ישראל\u0004 בעיר — \u0003ימתין\u0004 במוצאי שבת \u0003עד כדי שיחמו חמין,\u0004 שלא יהנה ממה שעשו בשבת. \u0003מחצה\u0004 ישראל \u0003על מחצה\u0004 גוים — \u0003אסור וימתין עד כדי שיחמו חמין. ר' יהודה אומר: באמבטי קטנה, אם יש בה\u0004 בעיר \u0003רשות\u0004 (שלטון, פקיד גבוה) \u0003רוחץ בה מיד.\u0004","ושאלו: ו\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רשות\" אמר רב יהודה\u0004 שכך \u0003אמר רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה:\u0004 הכוונה היא ש\u0003אם יש בה\u0004 בעיר \u0003אדם חשוב שיש לו עשרה עבדים שמחממין לו עשרה קומקומין בבת אחת באמבטי קטנה\u0004 — \u0003מותר לרחוץ בה מיד\u0004 במוצאי שבת, שאפשר לומר שאותה אמבטי לא חיממה ביום השבת אלא מיד במוצאי שבת, שכן ייתכן שחוממה עבור הרשות.","שנינו במשנה שאם \u0003עשו לו\u0004 גוים \u0003ארון וחפרו לו קבר\u0004 ונמלכו — מותר לקבור בו ישראל. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לפחות \u0003ימתין\u0004 במוצאי שבת \u0003בכדי שיעשו\u0004 קבר כזה! ומשיבים: \u0003אמר עולא:\u0004 מדובר \u0003בעומד\u0004 הקבר \u0003באסרטיא\u0004 \u0005[ברחוב],\u0006 שכרגיל אין ישראל נקברים במקום כזה, ומוכח שנעשה לצורך גוי. ועדיין שואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 \u0003קבר\u0004 כפי שהברנו, ואולם ב\u0003ארון מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע אין ממתינים במוצאי שבת בכדי שיעשו? \u0003אמר ר' אבהו:\u0004 בשהיה הארון \u0003מוטל\u0004 כבר \u0003על קברו\u0004 של גוי, ומוכח שעבורו נעשה.","\u0003עושין\u0004 בשבת את \u0003כל צרכי המת: סכין\u0004 אותו בשמן, \u0003ומדיחין אותו\u0004 במים, \u0003ובלבד שלא יזיז בו אבר\u0004 כאשר סכו או מדיחו, משום מוקצה. ו\u0003שומטין את הכר מתחתיו, ו\u0004בשעת הצורך אף \u0003מטילין אותו על החול\u0004 הצונן \u0003בשביל\u0004"],["\u0003שימתין\u0004 (שלא ימהר להסריח). וכן \u0003קושרין את הלחי\u0004 של המת ההולכת ונפתחת, \u0003לא\u0004 שיזיזנו ממש \u0003שיעלה\u0004 ויחזור למקומו, \u0003אלא שלא יוסיף\u0004 להיפתח יותר. \u0003וכן קורה\u0004 של גג \u0003שנשברה\u0004 בשבת — \u0003סומכין אותה בספסל או בארוכות\u0004 (במוטות הארוכים של) \u0003המטה, לא שתעלה\u0004 הקורה למקומה, \u0003אלא שלא תוסיף\u0004 להתמוטט.","על ההיתר לסוך את המת שואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה\u0004 שכך \u0003אמר שמואל: מעשה בתלמידו של ר' מאיר שנכנס אחריו לבית המרחץ\u0004 בשבת, \u0003ביקש\u0004 התלמיד \u0003להדיח קרקע, אמר לו\u0004 ר' מאיר: \u0003אין מדיחין.\u0004 ביקש התלמיד \u0003לסוך קרקע, אמר לו\u0004 ר' מאיר: \u0003אין סכין.\u0004 ומכאן נלמד שדבר האסור בטלטול אין סכים ומדיחים בשבת! ודוחים: \u0003קרקע בקרקע\u0004 — \u0003מחלפא\u0004 \u0005[מתחלפת],\u0006 ומתוך חשש שמא יבוא לרחוץ קרקע שיש בו גומות, אסרו, אבל \u0003מת בקרקע\u0004 — \u0003לא מיחלף\u0004 \u0005[אינו מתחלף],\u0006 ומותר.","שנינו במשנה: \"עושים כל צרכי המת\". ושאלו: \u0003\"כל\"\u0004 זה \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]?\u0006 ומשיבים, \u0003לאתויי הא דתנו רבנן\u0004 \u0005[להביא,\u0006 לרבות את \u0005זה ששנו חכמים]:\u0006 \u0003מביאין כלי מיקר\u0004 (כלים קרירים) \u0003וכלי מתכות, ומניחין על כריסו\u0004 של המת \u0003כדי שלא תפוח\u0004 (תתנפח). \u0003ופוקקין את נקביו כדי שלא תיכנס בהן הרוח\u0004 ויתנפח.","\u0003ואף שלמה אמר בחכמתו\u0004 על הזיקנה והמוות: \"עד אשר לא ירתק חבל הכסף ותרוץ גולת הזהב ותשבר כד על המבוע ונרוץ הגלגל אל הבור\" (קהלת יב, ו), שפרשוהו: \u0003\"עד שלא ירתק חבל הכסף\"\u0004 — \u0003זה חוט השדרה, \"ותרץ גלת הזהב\"\u0004 — \u0003זה אמה\u0004 שהיא כמעיין (גולה), \u0003\"ותשבר כד על המבוע\"\u0004 — \u0003זה הכרס\u0004 הנראית ככד המתנפחת ונבקעת. \u0003\"ונרץ הגלגל אל הבור\"\u0004 — \u0003זה פרש\u0004 (\"גלגל\" מלשון גללים) היוצא החוצה.","\u0003וכן הוא אומר: \"וזריתי פרש על פניכם פרש חגיכם\"\u0004 (מלאכי ב, ג). \u0003אמר רב הונא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב חגא:\u0004 כוונת הכתוב ל\u0003אלו בני אדם שמניחין\u0004 ועוזבים \u0003דברי תורה, ועושין כל ימיהם כחגים\u0004 ועל כן נקראים הם \"חגיכם\". \u0003אמר ר' לוי\u0004 שכך \u0003אמר רב פפי\u0004 שכך \u0003אמר ר' יהושע: לאחר שלשה ימים,\u0004 אחר המוות, \u0003כריסו\u0004 של אדם \u0003נבקעת ונופלת לו על פניו, ואומרת לו \"טול מה שנתת בי \".\u0004","\u0003אין מעצמין את\u0004 עיני \u0003המת בשבת,\u0004 משום איסור מוקצה, \u0003ו\u0004אף \u0003לא\u0004 מעצמים עיניו אף \u0003בחול עם יציאת נפש.\u0004 אלא, יש להמתין עד שימות. \u0003והמעצים עם יציאת הנפש\u0004 — \u0003הרי זה שופך דמים,\u0004 שהוא מקרב על ידי כך את המוות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המעצמו\u0004 למת \u0003עם יציאת הנפש\u0004 — \u0003הרי זה שופך דמים. משל לנר שכבה והולכת,\u0004 והיתה הבערה יכולה להימשך עוד זמן מסויים, ואולם אם \u0003אדם מניח אצבעו עליה\u0004 — \u0003מיד כבתה. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: הרוצה שיתעצמו עיניו של מת\u0004 — \u0003נופח לו יין בחוטמו, ונותן שמן בין ריסי עיניו, ואוחז בשני גודלי רגליו, והן\u0004 העינים, \u0003מתעצמין מאליהן.\u0004","ואגב דברים אלה שנאמרו במת מביאים \u0003את מה שתניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: תינוק בן יומו חי\u0004 — \u0003מחללין עליו את השבת. דוד מלך ישראל מת — אין מחללין עליו את השבת. תינוק בן יומו חי מחללין עליו את השבת\u0004 וטעמו של דבר, \u0003אמרה תורה: \"חלל עליו שבת אחד, כדי שישמור שבתות הרבה \".\u0004 ואפילו \u0003דוד מלך ישראל,\u0004 כש\u0003מת\u0004 — \u0003אין מחללין עליו\u0004 את השבת. \u0003כיון שמת אדם, בטל מן המצות\u0004 ואין עוד ערך לו. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן\u0004 על הכתוב: \u0003\"במתים חפשי\u0004 כמו חללים שוכבי קבר אשר לא זכרתם עוד\u0003\"\u0004 (תהלים פח, ו) — \u0003כיון שמת אדם, נעשה חפשי מן המצו‍ת.\u0004","\u0003ו\u0004עוד \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: תינוק בן יומו חי\u0004 — \u0003אין צריך לשומרו מן החולדה ומן העכברים,\u0004 שהם בורחים מפניו. \u0003אבל\u0004 אפילו \u0003עוג מלך הבשן\u0004 כשהוא \u0003מת\u0004 — \u0003צריך לשומרו מן החולדה ומן העכברים. שנאמר: \"ומוראכם וחתכם יהיה\u0004 על כל חית הארץ ועל כל עוף השמים\u0003\"\u0004 (בראשית ט, ב), ודורשים: \u0003כל זמן שאדם חי\u0004 — \u0003אימתו מוטלת על הבריות\u0004 (בעלי חיים). \u0003כיון שמת\u0004 — \u0003בטלה אימתו.\u0004","\u0003אמר רב פפא, נקיטינן\u0004 \u0005[מוחזק בידינו]:\u0006 \u0003אריה אבי תרי\u0004 \u0005[על שני\u0006 אנשים\u0005]\u0006 — \u0003לא נפיל\u0004 \u0005[אינו מתנפל].\u0006 ומקשים: \u0003הא קא חזינן דנפיל\u0004 \u0005[\u0006ו\u0005הרי רואים אנו ש\u0006הוא \u0005מתנפל]\u0006 ומשיבים: את המאמר \u0003ההוא\u0004 שהביא רב פפא יש להסביר \u0003כ\u0004דבר זה ש\u0003אמר רמי בר אבא: אין חיה שולטת באדם עד שנדמה לו כבהמה, שנאמר: \"\u0004ו\u0003אדם ביקר בל ילין נמשל כבהמות נדמו\"\u0004 (תהילים מט, יג). אבל על בני אדם שיש להם דמות רוחנית של אדם, אין חיה מתנפלת. ועל אותו דרך \u0003אמר ר' חנינא: אסור לישן בבית יחידי, וכל הישן בבית יחידי\u0004 — \u0003אחזתו לילית\u0004 (רוח רעה).","\u0003ו\u0004עוד \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 בשבח החיים, \u0003ר' שמעון בן אלעזר אומר: עשה\u0004 מצוות \u0003עד שאתה מוצא\u0004 אפשרות, \u0003ומצוי לך\u0004 הכסף והאמצעים, \u0003ו\u0004אתה עצמך \u0003עודך בידך. ואף שלמה אמר בחכמתו: \"וזכר את בוראך בימי בחורתיך עד אשר לא יבאו ימי הרעה\u0004 והגיעו שנים אשר תאמר אין לי בהם חפץ\u0003\"\u0004 (קהלת יב, א) ומפרש: \"ימי הרעה\" — \u0003אלו ימי הזקנה. \"והגיעו שנים אשר תאמר אין לי בהם חפץ\"\u0004 — \u0003אלו ימי המשיח, שאין בהם לא זכות ולא חובה.\u0004","\u0003ו\u0004מעירים: הסבר זה \u0003פליגא\u0004 \u0005[חלוק]\u0006 על דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל : אין בין העולם הזה לימות המשיח אלא שיעבוד מלכיות בלבד\u0004 שיתבטל אז, וכפי \u0003שנאמר: \"כי לא יחדל אביון מקרב הארץ\u0004 על כן אנכי מצוך לאמור פתוח תפתח את ידך לאחיך לענייך ולאביונך בארצך\u0003\"\u0004 (דברים טו, יא), משמע שסדרי העולם ואף עוני ועושר שבו לא יתבטלו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אלעזר הקפר אומר: לעולם יבקש אדם רחמים על מדה זו\u0004 של עניות, \u0003שאם הוא לא בא\u0004 לה — \u0003בא בנו, ואם בנו לא בא\u0004 לעניות — \u0003בן בנו בא,\u0004 וכפי \u0003שנאמר:\u0004 \"נתון תתן לו ולא ירע לבבך בתתך לו \u0003כי בגלל הדבר הזה\u0004 יברכך ה' אלהיך בכל מעשיך ובכל משלח ידיך\" (דברים טו, י). ועל כך \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 \"בגלל הדבר\", כלומר, \u0003גלגל הוא שחוזר\u0004 (מסתובב) \u0003בעולם,\u0004 אלה עולים ואלה יורדים. \u0003אמר רב יוסף, נקיטינן\u0004 \u0005[מוחזק בידינו]:\u0006 \u0003האי צורבא מרבנן לא מיעני\u0004 \u0005[תלמיד חכם אינו נעשה עני].\u0006 ומקשים: \u0003והא קא חזינן דמיעני\u0004 \u0005[והרי אנו רואים שנעשה עני]!\u0006 ומשיבים: אף על פי כן \u0003אם איתא דמיעני\u0004 \u0005[יש ש\u0006הוא \u0005נעשה עני],\u0006 בכל זאת \u0003אהדורי אפתחא לא מיהדר\u0004 \u0005[על הפתחים אינו מחזר].\u0006","באותו ענין מסופר כיבאותו ענין מסופר כי \u0003אמר לה ר' חייא לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003כי אתי עניא\u0004 \u0005[כאשר בא עני]\u0006 — \u0003אקדימי ליה ריפתא, כי היכי דלקדמו\u0004 \u0005[הקדימי\u0006 ותני \u0005לו לחם, כדי שיקדימו]\u0006 ויתנו גם \u0003לבניך. אמרה ליה\u0004 \u0005[לו]\u0006 לר חייא בעלה: האם \u0003מילט קא לייטת להו\u0004 \u0005[אתה מקלל אותם\u0006 את בניך\u0005]?!\u0006 \u0003אמר לה: קרא קא כתיב\u0004 \u0005[מקרא הוא\u0006 ש\u0005נאמר]\u0006 \u0003\"כי בגלל הדבר הזה\", ותנא דבי רבי ישמעאל\u0004 — \u0003גלגל הוא שחוזר בעולם.\u0004 ובדומה לזה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן גמליאל ברבי\u0004 \u0005[בנו של רבי]\u0006 \u0003אומר:\u0004 מה שנאמר \u0003\"ונתן לך רחמים ורחמך והרבך\"\u0004 (דברים יג, יח) מלמדנו כי \u0003כל המרחם על הבריות\u0004 — \u0003מרחמין עליו מן השמים. וכל שאינו מרחם על הבריות\u0004 — \u0003אין מרחמין עליו מן השמים.\u0004","ומכאן חוזרים לפסוקי קהלת המדברים בזקנה ובמוות. נאמר: \u0003\"עד אשר לא תחשך\u0004 השמש והאור והירח והכוכבים ושבו העבים אחר הגשם\u0003\"\u0004 (קהלת יב, ב), ודרשו חכמים: \u0003\"השמש והאור\"\u0004 — \u0003זו פדחת\u0004 (מצח) \u0003והחוטם,\u0004 שהם הבולטים בפניו של אדם. \u0003\"והירח\"\u0004 — \u0003זו נשמה,\u0004 המאירה בו. \u0003\"והכוכבים\"\u0004 — \u0003אלו הלסתות\u0004 (לחיים). \u0003\"ושבו העבים אחר הגשם\"\u0004 נדרש — \u0003זו מאור עיניו של אדם, שהולך\u0004 ומתמעט (כמתכסה בעבים) \u0003אחר הבכי\u0004 (\"הגשם\"). ו\u0003אמר שמואל: האי דמעתא\u0004 \u0005[דמעה זו],\u0006 \u0003עד ארבעין שנין\u0004 \u0005[ארבעים שנה]\u0006 — \u0003הדרא\u0004 \u0005[חוזרת]\u0006 לאדם, וראייתו נשארת כשהיתה. \u0003מכאן ואילך\u0004 מגיל ארבעים והלאה — \u0003לא הדרא\u0004 \u0005[אינה חוזרת],\u0006 וכל דמעה מעוורת את העינים.","\u0003ו\u0004בדומה לכך, \u0003אמר רב נחמן: האי כוחלא\u0004 \u0005[כחול זה]\u0006 שנותנים בעיניים \u0003עד ארבעין שנין\u0004 \u0005[ארבעים שנה]\u0006 — \u0003מרווח\u0004 ומועיל לעיניים, \u0003מכאן ואילך\u0004 — \u0003אפילו מליא כאביסנא דגירדאי\u0004 \u0005[ממלא כמנור אורגים]\u0006 — \u0003אוקומי מוקים\u0004 \u0005[להעמיד\u0006 הוא \u0005מעמיד],\u0006 ואולם \u0003ארווחי לא\u0004 \u0005[לרווח\u0006 שוב \u0005אינו]\u0006 \u0003מרווח,\u0004 אינו מועיל. ואגב כך שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב נחמן בביטויו שממלא הרבה כמנור אורגים. ומשיבים: בדרך כלל כל \u0003כמה דאלים מכוחלא\u0004 \u0005[שעבה המכחול]\u0006 — \u0003טפי מעלי\u0004 \u0005[מועיל יותר].\u0006","מסופר כי \u0003ר' חנינא שכיבא ליה ברתיה\u0004 \u0005[מתה לו בתו],\u0006 \u0003לא הוה קא בכי עלה\u0004 \u0005[היה בוכה עליה].\u0006 \u0003אמרה ליה דביתהו\u0004 \u0005[אשתו]:\u0006 וכי \u0003תרנגולתא אפיקת\u0004 \u0005[תרנגולת הוצאת]\u0006 \u0003מביתך\u0004 שאינך מגלה כל סימן צער?! \u0003אמר לה:\u0004 ואם אבכה הרי יהיו בידי \u0003תרתי\u0004 \u0005[שתים]:\u0006 \u0003תכלא ועיורא\u0004 \u0005[שכול ועוורון].\u0006 ומסבירים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בן קצרתה: שש\u0004 מיני \u0003דמעות הן\u0004 אצל האדם: \u0003שלש\u0004 מהן \u0003יפות\u0004 לעיניים, \u0003ושלש\u0004 מהן \u0003רעות.\u0004 ומפרט: דמעות \u0003של\u0004 (הבאות מחמת) \u0003עשן, ושל בכי\u0004 מתוך צער"],["\u0003ושל\u0004 ייסורי \u0003בית הכסא\u0004 — \u0003רעות\u0004 לעינים. \u0003של סם ושל שחוק ושל פירות\u0004 חריפים — \u0003יפות\u0004 לעינים.","וממשיכים לבאר עוד את פסוקי ספר קהלת. נאמר: \u0003\"ביום שיזעו שמרי הבית והתעותו\u0004 אנשי החיל ובטלו הטוחנות כי מעטו וחשכו הרואות בארובות\" (קהלת יב, ג), ומפרשים: \u0003\"ביום שיזעו שמרי הבית\"\u0004 — \u0003אלו הכסלים\u0004 (המתניים) \u0003והצלעות\u0004 המקיפות את גופו של אדם, \u0003\"והתעותו אנשי החיל\"\u0004 — \u0003אלו שוקים,\u0004 שכוחו של אדם עליהן. \u0003\"ובטלו הטחנות\"\u0004 — \u0003אלו שינים\u0004 הנושרות, \u0003\"וחשכו הראות בארבות\"\u0004 — \u0003אלו עינים\u0004 המתכהות.","ומסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לר' יהושע בן חנניה: מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אתית לבי\u0004 \u0005[באת לבית]\u0006 \u0003אבידן?\u0004 שהיה מקום המיועד לשיחות ולוויכוחים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן חנניה בלשון חכמה: \u0003טור תלג סחרוני גלידין\u0004 \u0005[הר שלג הקיפו קרח],\u0006 כלומר, השערות הלבינו. \u0003כלבוהי לא נבחין\u0004 \u0005[כלביו אינם נובחים],\u0006 כלומר, קולו אינו נשמע. \u0003טחנוהי לא טוחנין\u0004 \u0005[טוחניו אינם טוחנים],\u0006 כלומר, שיניו נשרו. \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב אמרי\u0004 \u0005[אמרו]\u0006 והוסיפו: \u0003אדלא אבידנא, בחישנא\u0004 \u0005[אחרי מה שלא אבדתי, אני מחפש],\u0006 שהזקן הולך כפוף ונראה כמחפש אבידה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר קיסמא אומר: טבא תרי מתלת\u0004 \u0005[טובות שתי\u0006 הרגליים של ימי הצעירות \u0005משלוש\u0006 בצירוף המקל של ימי הזקנה\u0005].\u0006 \u0003ווי\u0004 \u0005[אוי]\u0006 \u0003לה לחדא דאזלא ולא אתיא\u0004 \u0005[לאחת שהולכת ואינה באה]\u0006 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 זו? \u0003אמר רב חסדא: ינקותא\u0004 \u0005[הבחרות].\u0006 וכעין זה, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: ינקותא\u0004 — \u0003כלילא דוורדא\u0004 \u0005[הינקות\u0006 היא \u0005נזר ורדים],\u0006 \u0003סבותא\u0004 — \u0003כלילא דחילפא\u0004 \u0005[הזקנה\u0006 היא \u0005עטרת קוצים].\u0006 \u0003תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' מאיר: דוק בככי ותשכח בניגרי\u0004 \u0005[טחן בשיניים ותמצא ברגליים],\u0006 שיהיה ברגליו כח לשאתו, \u0003שנאמר: \"ונשבע לחם ונהיה טובים ורעה לא ראינו\"\u0004 (ירמיה מד, יז). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003שרי שקיך ועייל\u0004 \u0005[התר\u0006 את \u0005שקך,\u0006 פיך, \u0005והכנס]\u0006 בו את \u0003לחמך. עד ארבעין שנין\u0004 \u0005[ארבעים שנה]\u0006 — \u0003מיכלא מעלי\u0004 \u0005[אוכל מעולה],\u0006 \u0003מכאן ואילך\u0004 — \u0003משתי מעלי\u0004 \u0005[שתיה מעולה].\u0006","כיון שהוזכרו פתגמי חכמה שונים מספרים: \u0003אמר ליה ההוא גוזאה\u0004 \u0005[לו סריס אחד]\u0006 שהיה מין \u0003לר' יהושע בן קרחה\u0004 בלשון רמז וגנאי \u0003: מהכא\u0004 \u0005[מכאן]\u0006 עד \u0003ל\u0004מקום \u0003קרחינא כמה\u0004 מרחק \u0003הוי\u0004 \u0005[הוא]?\u0006 \u0005שרמז לו שהוא קרח.\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמהכא לגוזניא\u0004 \u0005[כמו מכאן ל\u0006הרי \u0005גוזן]\u0006 ורמז לו לסריסותו (\"גוזא\") (ריעב\"ץ). \u0003אמר ליה\u0004 \u0005[לו]\u0006 המין: \u0003ברחא קרחא\u0004 \u0005[תיש קרח]\u0006 מוכרים \u0003בארבעה\u0004 דינרים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עיקרא שליפא בתמניא\u0004 \u0005[תיש מסורס\u0006 מוכרים \u0005בשמונה].\u0006","\u0003חזייה דלא סיים מסאניה\u0004 \u0005[ראהו\u0006 המין לר' יהושע \u0005שאינו נועל מנעליו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 כך אומרים: זה הרוכב \u0003על סוס\u0004 — \u0003מלך.\u0004 זה הרוכב \u0003על חמור\u0004 — \u0003בן חורין, ודמנעלי בריגלוהי\u0004 \u0005[ושמנעלים ברגליו]\u0006 — הוא לפחות \u0003בר איניש\u0004 \u0005[בן אדם].\u0006 \u0003דלא הא\u0004 \u0005[שאינו זה]\u0006 \u0003ולא הא\u0004 \u0005[זה]\u0006 — זה \u0003דחפיר וקביר טב מיניה\u0004 \u0005[שחפור וקבור טוב ממנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003גוזא גוזא, תלת\u0004 \u0005[סריס סריס, שלושה\u0006 דברים\u0005]\u0006 \u0003אמרת לי, תלת שמעת\u0004 \u0005[שלושה\u0006 דברים \u0005אתה שומע].\u0006 מקובלים אנו: \u0003הדרת פנים\u0004 — \u0003זקן, שמחת לב\u0004 — \u0003אשה, \"נחלת ה'\u0004 — \u0003בנים\"\u0004 (תהלים קכז, ג), \u0003ברוך המקום שמנעך מכולם\u0004 שלסריס אין זקן אף לא אשה ובנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו סריס לר' יהושע בן קרחה: \u0003קרחא מצויינא\u0004 \u0005[קרח מתקוטט]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עיקרא שליפא\u0004 \u0005[תיש מסורס]\u0006 ואמר דברי \u0003תוכחה!\u0004","ושוב דנים בענין זיקנה, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לר' שמעון בן חלפתא\u0004 בלשון נימוס: \u0003מפני מה לא הקבלנו פניך ברגל, כדרך שהקבילו אבותי לאבותיך?\u0004 כלומר, מדוע לא באת לבקרני? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מפני שהזקנתי. כי הנה \u0003סלעים\u0004 שבדרך \u0003נעשו גבוהים,\u0004 דברים \u0003קרובים נעשו רחוקים, משתים נעשו שלש\u0004 (רגלים), שני רגליו ומקל ההליכה, \u0003משים שלום בבית\u0004 (תאות המין שבשלה משלימים בני הזוג) \u0003בטל.\u0004","ועוד אמרו על הנאמר \"וסגרו דלתים בשוק בשפל קול הטחנה ויקום לקול הצפור וישחו כל בנות השיר\" (קהלת יב, ד): \u0003\"וסגרו דלתים בשוק\"\u0004 — \u0003אלו נקביו של אדם\u0004 שאינם פועלים כהלכה. \u0003\"בשפל קול הטחנה\"\u0004 — \u0003בשביל קורקבן שאינו טוחן. \"ויקום לקול הצפור\"\u0004 — ששנתו אינה עמוקה ו\u0003אפילו צפור מנערתו משנתו. \"וישחו כל בנות השיר\"\u0004 — \u0003שאפילו קול שירים ושירות דומות עליו כשוחה\u0004 (שיחה, דיבור) בלבד, ואינו נהנה מן המנגינה.","\u0003ואף ברזילי הגלעדי אמר לדוד: \"בן שמנים שנה אנכי היום\u0004 האדע בין טוב לרע אם יטעם עבדך את אשר אוכל ואת אשר אשתה אם אשמע עוד בקול שרים ושרות\" (שמואל ב' יט, לו). ומפרשים: \u0003\"האדע בין טוב לרע\"\u0004 — \u0003מכאן שדעותן של זקנים משתנות\u0004 ואין הם מבחינים עוד בדברים. \u0003\"אם יטעם עבדך את אשר אכל ואת אשר אשתה\"\u0004 — \u0003מכאן ששפתותיהן של זקנים מתרפטות\u0004 (מתבקעות ומתבלות). \u0003\"אם אשמע עוד בקול שרים ושרות\"\u0004 — \u0003מכאן שאזניהם של זקנים מתכבדות\u0004 (נעשות כבדות).","\u0003אמר רב: ברזילי הגלעדי שקרא הוה\u0004 \u0005[שקרן היה]\u0006 ורצה להשתמט מלהיות אצל דוד, שכן זקן בן שמונים איננו תשוש עד כדי כך. \u0003דההיא אמתא דהויא בי\u0004 \u0005[שמשרתת אחת שהיתה בבית]\u0006 \u0003רבי בת תשעין ותרתין שנין\u0004 \u0005[תשעים ושנים שנה]\u0006 היתה, \u0003והות טעמא קידרא\u0004 \u0005[והיתה טועמת\u0006 את המאכלים המתבשלים \u0005בקדרות].\u0006 \u0003רבא אמר:\u0004 אמת אמר ברזילי, אלא \u0003שברזילי הגלעדי שטוף בזמה הוה\u0004 \u0005[היה],\u0006 \u0003וכל השטוף בזמה\u0004 — \u0003זקנה קופצת עליו\u0004 לפני זמנו. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל בר' יוסי אומר : תלמידי חכמים כל זמן שמזקינין\u0004 — \u0003חכמה נתוספת בהם, שנאמר: \"בישישים חכמה וארך ימים תבונה\"\u0004 (איוב יב, יב). \u0003ועמי הארץ כל זמן שמזקינין\u0004 — \u0003טפשות נתוספת בהן, שנאמר: \"מסיר שפה לנאמנים וטעם זקנים יקח\"\u0004 (איוב יב, כ).","וממשיכים עוד בבירור פסוקי ספר קהלת. נאמר: \"גם מגבוה יראו וחתחתים בדרך וינאץ השקד ויסתבל החגב ותפר האביונה כי הולך האדם אל בית עולמו וסבבו בשוק הסופדים\" (קהלת יב, ה). ומסבירים: \u0003\"גם מגבה ייראו\"\u0004 כוונתו: \u0003שאפילו גבשושית קטנה\u0004 שבדרך \u0003דומה עליו\u0004 על הזקן, \u0003כהרי הרים, \"וחתחתים בדרך\"\u0004 — \u0003בשעה שמהלך בדרך נעשו לו תוהים\u0004 (פחדים) שמא ינזק או יפול בה. \u0003\"וינאץ השקד\"\u0004 — \u0003זו קליבוסת\u0004 (עצם הירך) שמתבלטת מבשרו של הזקן. \u0003\"ויסתבל החגב\"\u0004 — בחילוף האותיות ח' וע' \u0003אלו עגבות\u0004 שנעשות כבדות (סבל). \u0003\"ותפר האביונה\"\u0004 — \u0003זו חמדה\u0004 של תאות התשמיש המתבטלת.","מסופר, \u0003רב כהנא הוה פסיק סידרא קמיה\u0004 \u0005[היה\u0006 קורא את \u0005הפסוקים לפני]\u0006 \u0003רב. כי מטא להאי קרא, נגיד ואתנח\u0004 \u0005[כאשר הגיע לפסוק זה, נאנח\u0006 רב\u0005],\u0006 \u0003אמר\u0004 רב כהנא: \u0003שמע מינה\u0004 \u0005[למד מכאן ]\u0006 כי \u0003בטל ליה חמדיה\u0004 \u0005[בטלה\u0006 כבר \u0005תאותו ]\u0006 של \u0003רב.\u0004 וכן \u0003אמר רב כהנא : מאי דכתיב\u0004 \u0005[מה\u0006 פירוש זה \u0005שנאמר]\u0006 \u0003\"כי הוא אמר ויהי הוא צוה ויעמוד\"\u0004 (תהלים לג, ט) — שהקדוש ברוך הוא צוה ויצר בתוך האדם רצונות שיעשה דברים שלא היה עושה מעצמו אם היה נוהג רק על פי שכלו בלבד. \u0003\"כי הוא אמר ויהי\"\u0004 — \u0003זו אשה\u0004 שאדם נושא. \u0003\"הוא צוה ויעמד\"\u0004 — \u0003אלו בנים\u0004 שהוא טורח בגידולם. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: \u0003אשה\u0004 היא בעצם \u0003חמת\u0004 (כלי, נאד) \u0003מלא צואה, ופיה מלא דם\u0004 (כלומר, ששופעת דם נדה), ובכל זאת אין המחשבה על כך מרתיעה אנשים, \u0003והכל רצין אחריה\u0004 ומתאוים לה.","עוד נאמר בפסוק שהוזכר (קהלת יב, ה): \u0003\"כי הלך האדם אל בית עלמו\" אמר ר' יצחק: מלמד שכל צדיק וצדיק נותנין לו\u0004 בעולם הבא \u0003מדור לפי כבודו,\u0004 ולכל אחד בית עולם מיוחד לו. \u0003משל למלך שנכנס הוא ועבדיו לעיר, כשהן נכנסין\u0004 — \u0003כולן בשער אחד נכנסין,\u0004 ואולם \u0003כשהן לנין\u0004 — \u0003כל אחד ואחד נותנין לו מדור לפי כבודו,\u0004 וכן הוא גם אחרי המות שהכל מתים בשווה, אך לא לכולם שכר גן העדן בשווה.","\u0003ואמר ר' יצחק : מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005זה שנאמר]\u0006 \u0003\"כי הילדות והשחרות הבל\"\u0004 (קהלת יא, י) — יש לפרש: \u0003דברים\u0004 של עבירה \u0003שאדם עושה בילדותו\u0004 — \u0003משחירים פניו\u0004 מבושה \u0003לעת זקנתו\u0004 (ריא\"ף)\u0003.\u0004","\u0003ואמר ר' יצחק : קשה רימה\u0004 (תולעת) האוכלת את ה\u0003מת כ\u0004דקירת \u0003מחט בבשר החי, שנאמר\u0004 במתים: \u0003\"אך בשרו עליו יכאב\u0004 ונפשו עליו תאבל\u0003\"\u0004 (איוב יד, כב). \u0003אמר רב חסדא: נפשו של אדם מתאבלת עליו כל שבעה\u0004 ימים אחר מותו, \u0003שנאמר: \"ונפשו עליו תאבל\", וכתיב\u0004 \u0005[ונאמר]\u0006 עוד: \u0003\"ויעש לאביו אבל שבעת ימים\"\u0004 (בראשית נ, י).","\u0003אמר רב יהודה: מת שאין לו מנחמין,\u0004 כלומר, שאין אנשים המתאבלים עליו — \u0003הולכין עשרה בני אדם ויושבין במקומו\u0004 ומקבלים עליו תנחומים. ומסופר: \u0003ההוא דשכיב בשבבותיה\u0004 \u0005[אחד שמת בשכנותו]\u0006 של \u0003רב יהודה,\u0004 ו\u0003לא היו לו מנחמין\u0004"],["\u0003כל יומא הוה דבר\u0004 \u0005[יום היה מביא]\u0006 \u0003רב יהודה בי עשרה\u0004 \u0005[יחד עשרה\u0006 אנשים\u0005],\u0006 \u0003ויתבי בדוכתיה\u0004 \u0005[ו\u0006היו \u0005יושבים במקומו].\u0006 \u0003לאחר שבעה ימים איתחזי ליה בחילמיה\u0004 \u0005[נראה לו\u0006 המת \u0005בחלומו]\u0006 ל\u0003רב יהודה, ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003תנוח דעתך שהנחת את דעתי.\u0004","\u0003אמר ר' אבהו: כל\u0004 דבר \u0003שאומרים בפני המת,\u0004 המת \u0003יודע, עד שיסתם הגולל. פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בדבר זה \u0003ר' חייא ור' שמעון ברבי\u0004 \u0005[בנו של רבי]:\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 ידיעת המת היא \u0003עד שיסתם הגולל\u0004 (כיסוי הקבר) (תוספות), \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 ידיעת המת היא \u0003עד שיתעכל הבשר.\u0004","\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שידיעת המת היא \u0003עד שיתעכל הבשר,\u0004 הראיה לשיטתו היא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך בשרו עליו יכאב ונפשו עליו תאבל\"\u0004 (איוב יד, כב), הרי שיודע המת בצער בשרו שבקבר. ו\u0003מאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר\u0004 שידיעת המת היא \u0003עד שיסתם הגולל,\u0004 הראיה לשיטתו היא ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישב העפר על הארץ כשהיה\u0004 והרוח תשוב אל האלהים אשר נתנה\u0003\"\u0004 (קהלת יב, ז), כלומר, שעם שוב הגוף לאדמה שבה אף הנפש למקומה, ושוב אינו יודע כלום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 את הפסוק \u0003\"והרוח תשוב אל האלהים אשר נתנה\"\u0004 (קהלת יב, ז), יש לפרש כך: \"אשר נתנה\" כוונתו — כאשר נתנה, לאמור: \u0003תנה לו כמו שנתנה לך,\u0004 שמאחר ונתנה לך \u0003בטהרה\u0004 — \u0003אף אתה\u0004 תן לו אותה \u0003בטהרה. משל למלך בשר ודם שחלק בגדי מלכות לעבדיו.\u0004 מה עשו בהם? \u0003פקחין שבהן, קיפלום והניחום בקופסא\u0004 לשמרם. \u0003טפשים שבהן, הלכו ועשו בהן מלאכה. לימים ביקש המלך את כליו\u0004 (בגדיו) בחזרה, ואז ה\u0003פקחין שבהן החזירום לו כשהן מגוהצין\u0004 כפי שקבלום, \u0003טפשין שבהן החזירום לו כשהן מלוכלכין. שמח המלך לקראת\u0004 ה\u0003פקחין, וכעס לקראת\u0004 ה\u0003טפשין.\u0004","\u0003על\u0004 ה\u0003פקחין אמר: ינתנו כלי\u0004 שוב \u0003לאוצר, והם ילכו לבתיהם לשלום. ועל\u0004 ה\u0003טפשין אמר: כלי ינתנו לכובס\u0004 כדי לחדשם, \u0003והן\u0004 הטפשים, \u0003יתחבשו\u0004 (יאסרו) \u0003בבית האסורים\u0004 כעונש על שביזו את בגדי המלך לצורך עצמם.","\u0003אף הקדוש ברוך הוא\u0004 נוהג כן, \u0003על גופן של\u0004 ה\u0003צדיקים\u0004 שהוא ככלי מלכות שנשמרו יפה, \u0003אומר: \"יבוא שלום ינוחו על משכבותם\u0004 הולך נכוחו\u0003\"\u0004 (ישעיה נז, ב). \u0003ועל נשמתן הוא אומר: \"והיתה נפש אדני צרורה בצרור החיים\u0004 את ה' אלהיך\u0003\"\u0004 (שמואל א' כה, כט). ומאידך, \u0003על גופן של\u0004 ה\u0003רשעים הוא אומר: \"אין שלום אמר ה' לרשעים\"\u0004 (ישעיה נז, כא), \u0003ועל נשמתן הוא אומר: \"ואת נפש אויביך יקלענה בתוך כף הקלע\"\u0004 (שמואל א' כה, כט).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: נשמתן של\u0004 ה\u0003צדיקים גנוזות תחת כסא הכבוד, שנאמר: \"והיתה נפש אדני צרורה בצרור החיים\". ושל רשעים זוממות\u0004 (קשורות) \u0003והולכות, ומלאך אחד עומד בסוף העולם\u0004 האחד, \u0003ומלאך אחר עומד בסוף העולם\u0004 האחר, \u0003ומקלעין נשמתן\u0004 של רשעים \u0003זה לזה,\u0004 והוא \u0003שנאמר: \"ואת נפש אויביך יקלענה בתוך כף הקלע\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לרב נחמן:\u0004 נשמותיהם \u0003של בינונים מאי\u0004 \u0005[מה\u0006 מתארע להן\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: יפה עשית ששאלתני, \u0003איכא שכיבנא\u0004 \u0005[אם הייתי מת],\u0006 \u0003לא אמרי לכו האי מילתא\u0004 \u0005[הייתי\u0006 יכול \u0005לומר לכם דבר זה],\u0006 שכן \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: אלו ואלו ל\u0004מלאך \u0003דומה\u0004 הממונה על הרוחות הם \u0003נמסרין,\u0004 אלא \u0003הללו,\u0004 הבינונים, \u0003יש להן מנוח, והללו,\u0004 הרשעים, \u0003אין להן מנוח. אמר רב מרי: עתידים\u0004 אפילו ה\u0003צדיקים דהוו עפרא\u0004 \u0005[שיהיו עפר]\u0006 ואין גופם נשמר בשלמותו לעולם, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וישב העפר על הארץ כשהיה\"\u0004 (קהלת יב, ז).","אגב מאמר זה מסופר: \u0003הנהו קפולאי דהוו קפלי בארעא\u0004 \u0005[אותם חופרים שהיו חופרים באדמה]\u0006 של \u0003רב נחמן.\u0004 הגיעו לקבר ו\u0003נחר בהו\u0004 \u0005[גער בהם]\u0006 \u0003רב אחאי בר יאשיה\u0004 שהיה קבור שם. \u0003אתו\u0004 \u0005[באו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן: נחר בן גברא\u0004 \u0005[גער בנו אדם\u0006 שמת\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 רב נחמן \u0003ואמר ליה\u0004 \u0005[לו]\u0006 לשוכן העפר: \u0003מאן ניהו מר\u0004 \u0005[מי הוא אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003אחאי בר יאשיה. אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: כיצד נשמר גופך, \u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003אמר רב מרי: עתידי צדיקי דהוו עפרא\u0004 \u0005[עתידים הצדיקים שיהיו עפר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחאי: \u0003ומני\u0004 \u0005[ומיהו]\u0006 \u0003מרי\u0004 זה \u0003דלא ידענא ליה\u0004 \u0005[שאינני מכיר אותו\u0006 ואינני חושש לדבריו\u0005]?,\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: אף בלא דברי רב מרי, \u0003והא קרא כתיב\u0004 \u0005[והרי מקרא\u0006 מפורש \u0005נאמר]:\u0006 \u0003\"וישב העפר על הארץ כשהיה\"!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחאי: \u0003דאקרייך\u0004 \u0005[\u0006מי \u0005שלימד אותך]\u0006 את מקראות ספר \u0003קהלת, לא אקרייך\u0004 \u0005[לימד אותך]\u0006 את מקראות ספר \u0003משלי, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בספר משלי: \u0003\"\u0004חיי בשרים לב מרפא \u0003ורקב עצמות קנאה\"\u0004 (משלי יד, ל), ומשמעו: \u0003כל מי שיש לו קנאה בלבו\u0004 בחייו — \u0003עצמותיו מרקיבים,\u0004 ו\u0003כל שאין לו קנאה בלבו\u0004 — \u0003אין עצמותיו מרקיבים.\u0004","\u0003גששיה\u0004 \u0005[מיששו],\u0006 \u0003חזייה דאית ביה מששא\u0004 \u0005[\u0006ו\u0005ראה שיש בו ממש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ליקום מר לגוויה דביתא\u0004 \u0005[יעמוד אדוני\u0006 וילך \u0005לתוך הבית].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחאי: \u0003גלית אדעתך\u0004 \u0005[גילית דעתך]\u0006 ש\u0003אפילו נביאי\u0004 \u0005[נביאים]\u0006 \u0003לא קרית\u0004 \u0005[למדת],\u0006 ולא רק כתובים אינך יודע, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"וידעתם כי אני ה' בפתחי את קברותיכם\u0004 ובהעלותי אתכם מקברותיכם עמי\u0003\"\u0004 (יחזקאל לז, יג), וכל עוד לא הצטוו המתים לצאת מן הקברים, אסור להם לצאת מקברם.","חזר רב נחמן לשאול בענין הישארות הגוף ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לאחאי: \u0003והכתיב\u0004 \u0005[והרי\u0006 בכל זאת \u0005נאמר]:\u0006 \u0003\"כי עפר אתה ואל עפר תשוב \"!\u0004 (בראשית ג, יט), ומדוע גופך לא שב להיות עפר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הפסוק \u0003ההוא\u0004 מתקיים בצדיקים רק \u0003שעה אחת קודם תחיית המתים.\u0004 כדי שיבראו אף הם מחדש (מהרש\"א).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' אבהו:\u0004 הרי \u0003אמריתו\u0004 \u0005[אתם אומרים]\u0006 כי \u0003נשמתן של צדיקים גנוזות תחת כסא הכבוד,\u0004 אם כן \u0003אובא טמיא היכא אסקיה\u0004 \u0005[בעלת האוב איך העלתה]\u0006 את \u0003שמואל בנגידא\u0004 \u0005[באוב]?\u0006 והרי שוב אין מקומה כאן בעולם הזה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בתוך שנים עשר חדש\u0004 לפטירתו היה הדבר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל שנים עשר חדש גופו\u0004 של המת \u0003קיים, ונשמתו עולה ויורדת,\u0004 ופעמים מצויה היא בעולם הזה עם גופו. \u0003לאחר שנים עשר חדש הגוף בטל\u0004"],["\u0003ונשמתו עולה\u0004 תחת כסא הכבוד, \u0003ושוב אינה יורדת.\u0004","\u0003אמר רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב : מהספדו של אדם\u0004 אם הצטערו ובכו עליו שומעי ההספד \u0003ניכר, אם בן העולם הבא הוא\u0004 הנספד \u0003אם לאו\u0004 \u0005[לא].\u0006 ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר ליה\u0004 \u0005[והרי אמר לו]\u0006 \u0003רב לרב שמואל בר שילת: אחים בהספידא, דהתם קאימנא\u0004 \u0005[חמם\u0006 את הלבבות \u0005בהספד\u0006 שלי, מפני \u0005ששם אעמוד\u0006 ואקשיב לדבריך\u0005],\u0006 והרי אף שהיה רב אדם גדול ובודאי היה בן עולם הבא, מכל מקום הוצרך להזהיר על \u0005הספדו!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהוא בן עולם הבא — הרי זה באופן \u0003דמחמו ליה ואחים\u0004 \u0005[כשמלהיבים\u0006 את הלב עבורו \u0005ו\u0006אנשים \u0005נלהבים].\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו את בקשת רב לרב שמואל בר שילת — הרי זה באופן \u0003דמחמו ליה ולא אחים,\u0004 ומכיון שידע רב שכך עלול להיות, לכך הזהירו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: כגון מר דסנו ליה כולהו פומבדיתאי, מאן אחים הספידא\u0004 \u0005[אדוני ששונאים אותו כל בני פומבדיתא\u0006 עירו, \u0005מי יתלהב בהספדו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיסתיא את\u0004 \u0005[די לי אתה]\u0006 \u0003ורבה בר רב חנן.\u0004","","\u0003בעא מניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' אלעזר מרב: איזהו בן העולם הבא? אמר ליה\u0004 \u0005[לו]\u0006 רב: בדברי הכתוב \u0003\"ואזניך תשמענה דבר מאחריך לאמר זה הדרך לכו בו כי תאמינו וכי תשמאילו\"\u0004 (ישעיה ל, כא), כלומר, שהמספידים אחרי מיטתו (\"מאחריך\") יאמרו עליו דברים טובים. \u0003ר' חנינא אמר: כל שדעת רבותינו נוחה הימנו,\u0004 סימן הוא לו שהוא בן עולם הבא. כדי לפרש את הפסוק בקהלת \u0003\"וסבבו בשוק הסופדים\"\u0004 (קהלת יב, ה), \u0003בני גלילא אמרי\u0004 \u0005[הגליל אומרים]:\u0006 \u0003עשה דברים\u0004 שלבסוף ייאמרו בהספד \u0003לפני מטתך,\u0004 ו\u0003בני יהודה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003עשה דברים\u0004 שלבסוף ייאמרו בהספד \u0003לאחר מטתך.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים],\u0006 אלא \u0003מר כי אתריה, ומר כי אתריה\u0004 \u0005[זה כ\u0006מנהג \u0005מקומו, וזה כ\u0006מנהג \u0005מקומו].\u0006 שבגליל היו הספדנים עומדים לפני מטת המת, וביהודה היו הספדנים עומדים אחריה.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם],\u0006 \u0003ר' אליעזר אומר: שוב יום אחד לפני מיתתך. שאלו תלמידיו את ר' אליעזר: וכי אדם יודע איזהו יום ימות? אמר להן: וכל שכן,\u0004 שעצה זו טובה היא, \u0003ישוב\u0004 כבר \u0003היום, שמא ימות למחר, ונמצא כל ימיו בתשובה. ואף שלמה אמר בחכמתו: \"בכל עת יהיו בגדיך לבנים ושמן על ראשך אל יחסר\"\u0004 (קהלת ט, ח), הרי שצריך אדם להיות מוכן תמיד. ובדומה לזה \u0003אמר רבן יוחנן בן זכאי: משל למלך שזימן את עבדיו לסעודה, ולא קבע להם זמן. פיקחין שבהן קישטו את עצמן וישבו על פתח בית המלך, אמרו: כלום חסר\u0004 דבר \u0003לבית המלך\u0004 לצרכי סעודה? ובוודאי יכול המלך לזמנם מיד לסעודה. \u0003טיפשין שבהן הלכו למלאכתן, אמרו: כלום יש סעודה בלא טורח?\u0004 ובינתיים עד שיטרחו בסעודה יעסקו הם בענין אחר. \u0003פתאום ביקש המלך את עבדיו\u0004 שיבואו לסעודה. \u0003פיקחין שבהן נכנסו לפניו כשהן מקושטין, והטיפשים נכנסו לפניו כשהן מלוכלכין. שמח המלך לקראת\u0004 ה\u0003פיקחים וכעס לקראת\u0004 ה\u0003טיפשים. אמר\u0004 המלך: \u0003הללו\u0004 הפקחים \u0003שקישטו את עצמן לסעודה\u0004 — \u0003ישבו ויאכלו וישתו,\u0004 ואילו \u0003הללו\u0004 הטפשים \u0003שלא קישטו עצמן לסעודה\u0004 — \u0003יעמדו ויראו.\u0004 וכן הוא לגבי אנשים הסבורים שיום המות והדין רחוק מהם ואינם מכינים עצמם לקראתו. \u0003חתנו של ר' מאיר משום\u0004 (בשם) חמיו \u0003ר' מאיר אמר:\u0004 אילו היה עונשם של אלה שלא הכינו עצמם רק בזה שהם עומדים ורואים לא היה זה מספיק, שכן \u0003אף הן נראין כמשמשין\u0004 בסעודה, ואין בכך בזיון ועונש כל כך. \u0003אלא אלו ואלו יושבין, הללו\u0004 הפקחים, הצדיקים — \u0003אוכלין. והללו\u0004 הטפשים, הרשעים — \u0003רעבין, הללו,\u0004 הצדיקים — \u0003שותין, והללו\u0004 הרשעים — \u0003צמאים, ש\u0004כן \u0003נאמר: \"\u0004לכן \u0003כה אמר ה'\u0004 אלהים \u0003הנה עבדי יאכלו ואתם תרעבו הנה עבדי ישתו ואתם תצמאו\u0004 הנה עבדי ישמחו ואתם תבשו \u0003הנה עבדי ירנו מטוב לב ואתם תצעקו מכאב לב\"\u0004 (ישעיה סה, יג-יד). \u0003דבר אחר:\u0004 דרשו על הפסוק \u0003\"בכל עת יהיו בגדיך לבנים\"\u0004 — \u0003אלו\u0004 הבגדים שיש בהם \u0003ציצית,\u0004 שהציציות לבנות הן, \u0003\"ושמן על ראשך אל יחסר\"\u0004 — \u0003אלו\u0004 ה\u0003תפילין\u0004 של ראש, שבלשון זה רימז עליהם. \u0003מי ש\u0004היה הולך בערב שבת בדרך ו\u0003החשיך\u0004 לו היום, והגיעה השבת בעודו \u0003בדרך\u0004 — \u0003נותן כיסו\u0004 (ארנקו) שיש בו ממון \u0003לגוי\u0004 ההולך עמו, \u0003ואם אין עמו גוי\u0004 — \u0003מניחו על החמור. הגיע לחצר החיצונה\u0004 של העיר, למקום שבו ניתנים הדברים להישמר — \u0003נוטל\u0004 מעל החמור \u0003את הכלים הניטלין בשבת. ו\u0004ביחס לכלים \u0003שאינן ניטלין בשבת\u0004 — \u0003מתיר החבלים\u0004 הקושרים את השקים לבהמה, \u0003והשקין נופלין מאיליהם,\u0004 עם הכלים שבהם.","","","","","","","שנינו במשנה שכאשר החשיך לו היום ונכנסה שבת בעודו בדרך, שנותן כיסו לגוי. ושואלים: \u0003מאי טעמא שרו ליה רבנן למיתב כיסיה\u0004 \u0005[מה טעם התירו לו חכמים לתת\u0006 את \u0005כיסו]\u0006 \u0003לגוי?\u0004 והרי אסור אפילו לומר לגוי לעשות מלאכה עבור ישראל! ומשיבים: \u0003קים להו לרבנן\u0004 \u0005[מוחזק להם לחכמים]\u0006 ש\u0003אין אדם מעמיד עצמו\u0004 (מתאפק ומוותר) \u0003על ממונו,\u0004 ולכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שרית ליה\u0004 \u0005[תתיר לו]\u0006 על ידי גוי — \u0003אתי לאיתויי\u0004 \u0005[יבוא להביאו,\u0006 לטלטלו\u0005]\u0006 בעצמו \u0003ארבע אמות ברשות הרבים,\u0004 ויעבור על דברי תורה.","\u0003אמר רבא:\u0004 ההיתר הזה \u0003לתת לגוי הוא דוקא\u0004 ב\u0003כיסו\u0004 שלו, \u0003אבל\u0004 ב\u0003מציאה\u0004 שמצא בשבת — \u0003לא\u0004 התירו. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הדבר, שהלא \u0003\"כיסו\" תנן\u0004 \u0005[שנינו]\u0006 ולא דבר אחר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הוא הדין אפילו\u0004 ב\u0003מציאה\u0004 שמותר לתיתה לגוי, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003\"כיסו\"\u0004 — \u0003אורחא דמילתא קתני\u0004 \u0005[כדרך\u0006 הנהוגה \u0005בדבר\u0006 זה \u0005שנה],\u0006 שכרגיל מצוי כיס בידי אדם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה רק שימוש לשון מקובל אלא קביעת הלכה מדוייקת. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שבמציאה אסור לתיתה לגוי, \u0003אלא\u0004 באופן ש\u0003לא אתי לידיה\u0004 \u0005[באה לידו]\u0006 המציאה מבעוד יום, \u0003אבל\u0004 אם כבר \u0003אתי לידיה\u0004 \u0005[באה\u0006 לידו] מבעוד יום — \u0003ככיסיה דמי\u0004 \u0005[ככיסו\u0006 היא \u0005נחשבת].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ועוסקים בבעיה זו בלשון אחרת, ולפיה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מציאה הבאה לידו מהו\u0004 הדין, האם נאמר כי \u0003כיון דאתא לידיה\u0004 \u0005[ש\u0006כבר \u0005באה לידו]\u0006 — הרי \u0003ככיסיה דמי\u0004 \u0005[ככיסו\u0006 היא \u0005נחשבת]?\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא טרח בה\u0004 — \u0003לאו ככיסיה דמי\u0004 \u0005[ככיסו\u0006 היא \u0005נחשבת]\u0006 ויהא מוכן לוותר עליה, ולכן לא הוצרכו חכמים להתיר על ידי גוי. לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה. שנינו במשנה שאם \u0003אין עמו גוי\u0004 — מניח על החמור. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 ש\u0003אין עמו גוי. הא\u0004 \u0005[הרי]\u0006 אם \u0003יש עמו גוי\u0004 — \u0003לגוי יהיב ליה\u0004 \u0005[נותן אותן]\u0006 את הכיס, ואינו מניחו על החמור. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו? ומשיבים: \u0003חמור\u0004 של ישראל — \u0003אתה מצווה על שביתתו\u0004 בשבת, \u0003גוי\u0004 — \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מצווה על שביתתו\u0004 ואין בכך איסור מן התורה.","","והלכה נוספת: אם לא היה גוי, אבל היו עמו \u0003חמור וחרש שוטה וקטן\u0004 — על ה\u0003חמור מנח ליה\u0004 \u0005[מניח אותו],\u0006 ואילו \u0003לחרש שוטה וקטן לא יהיב ליה\u0004 \u0005[אינו נותן אותו].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003הני\u0004 \u0005[אלה]\u0006 — אף על פי שאינם חייבים במצוות, מכל מקום בכלל \u0003אדם\u0004 הם, ואולם \u0003האי\u0004 \u0005[זה\u0006 החמור\u0005]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003אדם\u0004 הוא, ולכן עדיף לתת עליו מאשר לחרש שוטה וקטן. \u0005ו\u0006אם היו עמו \u0003חרש ושוטה\u0004 — נותן \u0003לשוטה. שוטה וקטן\u0004 — נותן \u0003לשוטה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 אם היו עמו \u0003חרש וקטן\u0004 מה יעשה ולמי יתן את הכיס? ומסבירים: \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' אליעזר לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, שלשיטתו יש לחרש דעת במידה מסויימת ודעתו נחשבת יותר משל הקטן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יצחק אומר משום\u0004 (בשם) \u0003ר' אליעזר: תרומת חרש,\u0004 כלומר, תרומה שהפריש חרש מן הפירות \u0003—\u0004"],["\u0003לא תצא\u0004 אותה תרומה \u0003לחולין\u0004 כדבר שאין בו קדושה כלל, \u0003מפני שהוא ספק\u0004 אם בר דעת הוא. נמצא שלשיטה זו החרש הוא בר דעת במידה מסויימת, ועדיף מבחינת חיובו במצוות על הקטן.","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים],\u0006 \u0003דתנן\u0004 \u0005[ששנויה\u0006 משנה\u0005]:\u0006 \u0003חמשה\u0004 הם אלו ש\u0003לא יתרומו\u0004 לכתחילה, \u0003ו\u0004אף \u0003אם תרמו אין תרומתן תרומה\u0004 כלל, \u0003אלו הן: חרש שוטה וקטן, והתורם את שאינו שלו, וגוי שתרם את של ישראל אפילו ברשותו\u0004 של הישראל, כיון שאין גוי נעשה שליח להפרשת תרומה וכל שכן שאינו מפרישה בעצמו.","ומכאן למדנו שאין כל הבדל בין חרש וקטן, ומתעוררת שאלה ביחס לנתינת הכיס בשבת, \u0003מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 האם \u0003לחרש יהיב ליה\u0004 \u0005[נותן אותו],\u0006 שהרי \u0003קטן אתי\u0004 \u0005[בא]\u0006 לאחר זמן \u0003לכלל דעת,\u0004 ומוטב אם כן שלא להרגילו בעבירה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לקטן יהיב ליה\u0004 \u0005[נותן אותו],\u0006 שהרי אם יתננו ל\u0003חרש אתי לאחלופי\u0004 \u0005[יבואו להחליפו]\u0006 \u0003בגדול פיקח,\u0004 ויחשבו שלכל גדול פיקח מותר הדבר, ולכן מוטב לתת לקטן, שהכל יודעים שאינו מחוייב במצוות. והשאלה היא מה עושים המקרה כזה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003לחרש יהיב ליה\u0004 \u0005[נותן אותו],\u0006 ו\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003לקטן יהיב ליה\u0004 \u0005[נותן אותו],\u0006 ולא הגיעה הבעיה לכלל סיכום נוסף.","ושואלים עוד: אם \u0003אין שם\u0004 עמו בדרך \u0003לא גוי ולא חמור ולא חרש ולא שוטה ולא קטן מאי\u0004 \u0005[מה\u0006 יעשה\u0005]?\u0006 \u0003אמר ר' יצחק: עוד\u0004 עצה \u0003אחרת היתה\u0004 לטפל בכיס זה, \u0003ולא רצו חכמים לגלותה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 אותה עצה אותה הזכיר כי \u0003\"עוד אחרת היתה\"?\u0004 ומסבירים: עצה זו היא ש\u0003מוליכו\u0004 את הכיס בכל פעם \u0003פחות פחות מארבע אמות,\u0004 ובאופן זה יכול להעבירו ברשות הרבים בלי לעבור על דברי תורה. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא רצו חכמים לגלותה?\u0004 — ומסבירים: \u0003משום\u0004 הכתוב \u0003\"כבד אלהים הסתר דבר וכבד מלכים חקר דבר\"\u0004 (משלי כה, ב). ושואלים: \u0003והכא, מאי\u0004 \u0005[וכאן, מה]\u0006 \u0003\"כבד אלהים\" איכא\u0004 \u0005[יש]\u0006 שבגללו יש להסתיר את הדבר? ומשיבים: אם יעשה כן יש \u0003לחשוש דילמא אתי לאתויי\u0004 \u0005[שמא\u0006 ישכח ו\u0005יבוא להביא]\u0006 \u0003ארבע אמות ברשות הרבים.\u0004","תקנה זו שנותן כיסו לגוי ואינו מטלטלו בעצמו פחות מארבע אמות היא אחד משמונה עשר דבר שגזרו, כשיטת בית שמאי (מפורטות כולן בפרק ראשון במסכת שבת). על הגזירות הללו נחלקו דעות חכמים בדור מאוחר יותר. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר:\u0004 יפה עשו ו\u0003בו ביום\u0004 שגזרו \u0003גדשו סאה,\u0004 והוסיפו דברים של שמירה וסייג לתורה. \u0003ר' יהושע אומר:\u0004 לא יפה עשו ו\u0003בו ביום מחקו סאה,\u0004 שגזירות אלה קשה לקיימן, והסוף הוא שעוברים גם עליהן וגם על דברי תורה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 במקום אחר: \u0003משל\u0004 משלו להבין את שיטת \u0003ר' אליעזר, למה הדבר דומה\u0004 — \u0003לקופה\u0004 (סל) \u0003מלאה קישואין ודילועין, אדם נותן לתוכה חרדל\u0004 — \u0003והיא מחזקת\u0004 גם את החרדל ותוספת זו רק לתועלת היא. ואילו \u0003משל\u0004 להבין את שיטת \u0003ר' יהושע, למה הדבר דומה\u0004 — \u0003לעריבה\u0004 (קערה גדולה) \u0003מלאה דבש,\u0004 אם אדם \u0003נותן לתוכה רימונים ואגוזים\u0004 — \u0003והיא מקיאה\u0004 מתוכה אף את הדבש שהיה בה.","קודם לכן שנינו ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שכאשר \u0003אין עמו גוי\u0004 — \u0003מניחו\u0004 את כיסו \u0003על החמור.\u0004 ומקשים: \u0003והלא\u0004 נמצא \u0003מחמר\u0004 (מוליך חמור טעון), \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 \"ויום השביעי שבת לה' אלהיך \u0003לא תעשה כל מלאכה\u0004 אתה ובנך ובתך עבדך ואמתך ובהמתך וגרך אשר בשעריך\" (שמות כ, י), והרי נמצא עושה מלאכת העברה ברשות הרבים על ידי החמור!","\u0003אמר רב אדא בר אהבה: מניחו עליה כשהיא מהלכת\u0004 ובכך גורם שאין נעשית כאן מלאכה גמורה של הוצאה והעברה בשבת, שכן מלאכת ההוצאה אין בה חיוב מן התורה אלא אם כן היו בה גם עקירה וגם הנחה. ואם לא עקרה הבהמה את המשא (שהרי הונח עליה בשעת הילוכה) אין כאן עקירה, ואין כאן חיוב עשיית מלאכה גמורה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אי אפשר\u0004 ש\u0003לא קיימא\u0004 \u0005[תעמוד]\u0006 הבהמה לאחר שהתחילה להלך, כדי \u0003להשתין מים ולהטיל גללים, ואיכא\u0004 \u0005[ויש]\u0006 אם כן \u0003עקירה והנחה!\u0004 ומשיבים: אף לכך יש תקנה, ש\u0003כשהיא,\u0004 הבהמה, \u0003מהלכת\u0004 — \u0003מניחו\u0004 לכיס \u0003עליה, כשהיא עומדת\u0004 — \u0003נוטלו הימנה\u0004 (ממנה). ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא עושה, אם כך הוא עושה \u0003אפילו\u0004 על \u0003חברו\u0004 ישראל \u0003נמי\u0004 \u0005[גם כן]\u0006 יכול לשים את משאו, ולא תהא בכך עקירה והנחה.","\u0003אמר רב פפא: כל\u0004 דבר \u0003ש\u0004עושה \u0003בגופו\u0004 ו\u0003חייב חטאת\u0004 על המעשה, אם עשה \u0003בחברו\u0004 הרי זה \u0003פטור אבל אסור,\u0004 ו\u0003כל ש\u0004אם עשה כך ב\u0003חבירו פטור אבל אסור\u0004 — \u0003בחמורו מותר לכתחלה.\u0004","\u0003אמר רב אדא בר אהבה:\u0004 היה מהלך בערב שבת בדרך ו\u0003היתה חבילתו מונחת לו על כתיפו\u0004 והחשיך היום — \u0003רץ תחתיה,\u0004 כלומר, רץ עם החבילה \u0003עד שמגיע לביתו.\u0004 ומדגישים: \u0003דוקא רץ, אבל קלי קלי\u0004 \u0005מעט מעט\u0006 בהליכה רגילה — \u0003לא,\u0004","ויש לברר אם כן: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון דלית ליה היכירא\u0004 \u0005[שאין לו היכר]\u0006 בהליכה רגילה, יש חשש שמא \u0003אתי למיעבד\u0004 \u0005[יבוא לעשות]\u0006 \u0003עקירה והנחה,\u0004 כגון שיעמוד לנוח באמצע הדרך. ומקשים: \u0003סוף סוף, כי מטא לביתיה\u0004 \u0005[כאשר מגיע לביתו]\u0006 \u0003אי אפשר\u0004 ש\u0003לא קאי פורתא\u0004 \u0005[יעמוד מעט],\u0006 \u0003וקמעייל\u0004 \u0005[ו\u0006נמצא ש\u0005הוא מכניס]\u0006 \u0003מרשות הרבים לרשות היחיד!\u0004 ומשיבים: מדובר כאן באופן זה, שכאשר מגיע לביתו אינו מכניס את החבילה כדרכה, אלא \u0003דזריק ליה\u0004 \u0005[שזורק אותה]\u0006 \u0003כלאחר יד\u0004 ולא בדרך הרגילה, וכיון שלא עשה את המלאכה כדרכה אין בכך איסור מן התורה.","כיון שהוזכר ענין המחמר בשבת, מביאים את מה ש\u0003אמר רמי בר חמא: המחמר אחר בהמתו בשבת,\u0004 אם עשה זאת \u0003בשוגג\u0004 — \u0003חייב\u0004 להביא קרבן \u0003חטאת,\u0004 ואם \u0003במזיד\u0004 — \u0003חייב סקילה.\u0004 ושואלים \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? על סמך מה אומר הוא דבר זה? \u0003אמר רבא: דאמר קרא\u0004 \u0005[ש\u0006כן \u0005אמר הכתוב]:\u0006 \u0003\"לא תעשה כל מלאכה אתה ובהמתך\",\u0004 ומכאן נלמד: \u0003בהמתו דומיא דידיה\u0004 \u0005[בדומה לו];\u0006 \u0003מה הוא\u0004 אם עשה \u0003בשוגג\u0004 — \u0003חייב חטאת,\u0004 ו\u0003במזיד\u0004 — \u0003חייב סקילה. אף\u0004 אם עשה מלאכה ב\u0003בהמתו נמי\u0004 \u0005[גם כן]\u0006 אם עשה \u0003בשוגג\u0004 — \u0003חייב חטאת,\u0004 ו\u0003במזיד\u0004 — \u0003חייב סקילה.\u0004","\u0003אמר רבא: שתי תשובות\u0004 יש לדחות את ה\u0003דבר; חדא\u0004 \u0005[אחד],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"תורה אחת יהיה לכם לעשה בשגגה והנפש אשר תעשה ביד רמה\u0004 מן האזרח ומן הגר את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\u0003\"\u0004 (במדבר טו, כט-ל), ודבר זה נאמר בדין חטאת על שגגת עבודה זרה, ו\u0003הוקשה\u0004 (הושוותה) בפסוק \u0003כל התורה כולה ל\u0004איסור \u0003עבודה זרה,\u0004 ובין השאר נלמד מכך: \u0003מה עבודה זרה\u0004 אינו חייב אלא \u0003דעביד מעשה בגופיה\u0004 \u0005[שעושה מעשה בגופו,\u0006 בעצמו\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אינו חייב \u0003עד דעביד\u0004 \u0005[שעושה]\u0006 \u0003מעשה בגופיה\u0004 \u0005[בגופו,\u0006 בעצמו\u0005]\u0006 ולא על דבר שעושה בהמתו.","\u0003ועוד\u0004 שואלים: \u0003אמרנו שאם עשה במזיד חייב סקילה, ודבר זה קשה, שהרי תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 המונה את החייבים סקילה בין השאר גם את \u0003המחלל את השבת בדבר שחייבין על שגגתו חטאת ועל זדונו סקילה.\u0004 ונדייק: \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא מידי\u0004 \u0005[שיש דבר]\u0006 בין איסורי התורה ש\u0003אין חייבין על שגגתו חטאת ולא על זדונו סקילה,\u0004","\u0003ומאי ניהו\u0004 \u0005[ומה הוא],\u0006 האם לא איסור ה\u0003\"לאו\"\u0004 (\"לא תעשה\") של \u0003מחמר?\u0004 ומכאן נלמד שאיסור מחמר כשאר עבודה בבהמתו אף שנאמר בתורה מכל מקום אין בו חיוב סקילה! ודוחים: אין זה מחוייב, יתכן שהכוונה היא לאיסור \u0003תחומין\u0004 שאין לצאת מהם בשבת \u0003ואליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003ר' עקיבא\u0004 הסבור שדיני תחומין נאמרו בתורה אף כי אין חייבים על שגגתם חטאת ועל זדונם סקילה. \u0003ו\u0004כן איסור \u0003הבערה\u0004 של אש בשבת \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יוסי,\u0004 הסבור כי אין חיוב סקילה על הבערת אש בשבת אלא איסור לאו ועונש מלקות בלבד."],["\u0003רב זביד מתני הכי\u0004 \u0005[היה שונה כך,\u0006 בדרך אחרת\u0005],\u0006 שלדעתו \u0003אמר רמי בר חמא: המחמר אחר בהמה בשבת,\u0004 אם עשה כן \u0003בשוגג\u0004 — \u0003אינו חייב חטאת, במזיד\u0004 — \u0003חייב סקילה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003המחלל את השבת בדבר שחייבין על שגגתו חטאת\u0004 — \u0003חייבין על זדונו סקילה.\u0004 ומכאן נדייק \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין חייבין על שגגתו חטאת\u0004 — אף \u0003אין חייבין על זדונו סקילה\u0004 וקשה לרמי בר חמא!","ומתרצים: \u0003מי קתני\u0004 \u0005[האם שנינו]\u0006 את הדיוק \u0003\"הא אין חייבין\u0004 על שגגתו אף אין חייבים על זדונו סקילה\", הלא יש אפשרות להבנה אחרת ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003דבר שחייבין על שגגתו חטאת\u0004 — \u0003חייבין על זדונו סקילה\u0004 בכל מקרה, \u0003ו\u0004אולם \u0003יש דבר שאין חייבין על שגגתו חטאת ו\u0004בכל זאת \u0003חייבין על זדונו סקילה, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 — \u0003מחמר.\u0004","שיטה אחרת בהלכות מחמר הביא \u0003רבא אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב מרי בר רחל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב מרי בר רחל.\u0004 ואגב מעירים: \u0003ללישנא בתרא\u0004 \u0005[ללשון האחרונה],\u0006 שרבא זה היה אביו של מרי בר רחל \u0003קשיא הא\u0004 \u0005[קשה זה]\u0006 ש\u0003רב אכשריה\u0004 \u0005[הכשירו]\u0006 \u0003לרב מרי בר רחל ומנייה בפורסיה\u0004 \u0005[ומינה אותו בין פקידי]\u0006 \u0003בבל.\u0004 שמאותו מעשה נלמד שאביו של רב מרי בר רחל לא היה מישראל, והיה צורך להכשיר אותו למינוי על סמך העובדה שאמו היא יהודיה מלידה. ואולם אם חכם בשם רבא היה אביו של רב מרי בר רחל, מה צורך היה למצוא לו הכשר משום אמו? ומשיבים: אין להוכיח מזה שבר, שכן \u0003דילמא תרי\u0004 \u0005[שמא שני]\u0006 \u0003מרי בר רחל הוו\u0004 \u0005[היו],\u0006 אחד בן גר והשני בנו של חכם שנקרא רבא.","מכל מקום חכם זה \u0003הוה מתני להא שמעתיה משמיה\u0004 \u0005[היה שונה את הלכתו זו משמו]\u0006 של \u0003ר' יוחנן לפטור.\u0004 ש\u0003אמר ר' יוחנן: המחמר אחר בהמתו בשבת פטור מכלום.\u0004","ומפרטים: אם עשה זאת \u0003בשוגג לא מחייב\u0004 \u0005[אינו חייב]\u0006 \u0003חטאת\u0004 — כיון \u0003דהוקשה\u0004 \u0005[שהושוותה]\u0006 \u0003כל התורה כולה ל\u0004איסור \u0003עבודה זרה,\u0004 ומשם נלמד שאין אדם מתחייב אלא על מעשה שעשה הוא עצמו, כאמור. ואם עשה זאת \u0003במזיד נמי לא מיחייב\u0004 \u0005[גם כן אינו מתחייב]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 המונה את החייבים סקילה בין השאר גם את \u0003המחלל את השבת בדבר שחייבין על שגגתו חטאת ועל זדונו סקילה,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אין חייבין על שגגתו חטאת\u0004 — אף \u0003אין חייבין על זדונו סקילה.\u0004","וכמו כן אף \u0003בלאו נמי לא מיחייב\u0004 \u0005[ב\u0006איסור \u0005לא\u0006 תעשה \u0005גם כן אינו מתחייב],\u0006 ואינו נענש במלקות כדין העובר על מצוות לא תעשה שבתורה — שאף שנאמרו בתורה כמה איסורים אזהרות וציוויים שלא לעשות מלאכה בשבת, מכל מקום \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003לאו\u0004 (\"לא תעשה\") \u0003שניתן\u0004 מיסודו לא לצורך עונש מלקות אלא \u0003לאזהרת\u0004 (כלומר, שיש איסור המחייב) \u0003מיתת בית דין, וכל לאו שניתן\u0004 מיסודו \u0003לאזהרת מיתת בית דין,\u0004 אם מאיזה טעם שהוא לא נתקיים עונש המוות \u0003אין לוקין עליו.\u0004"],["\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003לוקין\u0004 על לאו שניתן לאזהרת מיתת בית דין, הרי אפשר בדין מחמר ללמוד הלכה זו מדיוק לשון הכתוב, שכן די היה כי \u0003ליכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003\"לא תעשה כל מלאכה ובהמתך\",\u0004 ואולם נאמר בפסוק \"אתה ובהמתך\", ותוספת מלת \u0003\"אתה\" למה לי?\u0004 אלא ללמד כי \u0003הוא ניהו\u0004 \u0005[זה]\u0006 ש\u0003מתחייב\u0004 על מעשה של חילול שבת, אבל על מעשה \u0003בהמתו לא מיחייב\u0004 אינו מתחייב.","נאמר במשנה שאחר ש\u0003הגיע לחצר החיצונה\u0004 מתיר את החבלים והשקים נופלים מאליהם מהבהמה. \u0003אמר רב הונא: היתה בהמתו טעונה כלי זכוכית\u0004 ואם יתיר את החבלים ויפלו השקים ובתוכם הכלים מאליהם ישברו הכלים, הריהו \u0003מביא כרים וכסתות ומניח תחתיה, ומתיר\u0004 את \u0003החבלים והשקין נופלים\u0004 על הכרים.","ושואלים: ומדוע יש צורך בטרחה זו בקשר לכלי הזכוכית, \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003נוטל את הכלים הניטלין בשבת,\u0004 וכלי זכוכית הלא כלים ניטלים הם, ואם כן יכול להוציא את כלי הזכוכית ולהתיר אחר כך את השקים?","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב הונא\u0004 הלכה זו, היה זה \u0003בקרני דאומנא, דלא חזיא ליה\u0004 \u0005[בכלי של אומן\u0006 מקיז הדם, \u0005שאינם ראויים לו]\u0006 לשום מלאכה, ומוקצים הם מחמת איסור ומיאוס. ומקשים: \u0003והא קא\u0004 \u0005[והרי הוא]\u0006 \u0003מבטל\u0004 בכך \u0003כלי מהיכנו,\u0004 שהכרים נאסרים מעתה בטלטול והלא פסקו חכמים שכלי המותר בטלטול בשבת אין מניחים אותו במקום שיפסיק להיות מוכן וראוי לטלטול! ומשיבים: מדובר כאן \u0003בשליפי זוטרי\u0004 \u0005[בצרורות קטנים]\u0006 שיוכל לשמוט אחר כך את הכרים מתחתיהם, ולא ישברו.","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003היתה בהמתו טעונה טבל\u0004 (תבואה שלא הופרשו ממנה מעשרות) \u0003ועששיות\u0004 (של זכוכית) — \u0003מתיר את החבלים והשקין נופלין, ואף על פי שמשתברין.\u0004 והרי שלא התירו לשים כרים תחתיהם! ומשיבים: \u0003התם בכולסא\u0004 \u0005[שם\u0006 מדובר \u0005בגושי זכוכית]\u0006 העומדים לשבירה ולהתכה כדי לעשות מהם כלים. ומעירים: \u0003דיקא נמי, דקתני דומיא\u0004 \u0005[מדוייק גם כן\u0006 הסבר זה \u0005ש\u0006כן \u0005שנינו\u0006 עששיות \u0005בדומה]\u0006 ל\u0003טבל; מה טבל\u0004 — \u0003דלא חזי ליה\u0004 \u0005[שאינו ראוי לו],\u0006 \u0003אף הכא נמי לא חזי ליה\u0004 \u0005[כאן\u0006 בעששיות \u0005גם כן\u0006 מדובר באופן ש\u0005אינו\u0006 ראוי לו].","ומסבירים: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"אף על פי שמשתברין\",\u0004 שהרי אם מדובר בגושים גלמיים הרי אין קורה דבר כשהם נשברים — אלא \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003להפסד מועט נמי\u0004 \u0005[גם כן]\u0006 \u0003חששו,\u0004 שהרי עם זריקת השקים בהכרח ינתזו שברים קטנים מן הזכוכית וילכו לאיבוד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא בברייתא שמשום הפסד מועט זה לא התירו חכמים לטלטל את המוקצה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: היתה בהמתו טעונה שליף\u0004 (ערימה) \u0003של תבואה\u0004 — \u0003מניח ראשו תחתיה, ומסלקו,\u0004 את השליף, \u0003לצד אחר, והוא נופל מאליו.\u0004 שאמנם לא התירו טלטול כדרכו, אבל באופן זה שמטלטל בשינוי — אין לחשוש.","ומסופר: \u0003חמורו של רבן גמליאל היתה טעונה דבש ולא רצה לפורקה עד מוצאי שבת, למוצאי שבת מתה\u0004 מחמת עייפות. ושואלים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 ש\u0003נוטל\u0004 את ה\u0003כלים הניטלין,\u0004 ומדוע אם כן לא נטל רבן גמליאל את הדבש? ומשיבים: \u0003כשהדביש\u0004 (התקלקל הדבש). ושואלים שוב: \u0003הדביש למאי חזי\u0004 \u0005[למה ראוי]?\u0006 ולשם מה הביאו רבן גמליאל? ומשיבים שהוא ראוי \u0003לכתיתא דגמלי\u0004 \u0005[ל\u0006משוח בו \u0005פצעי גמלים].\u0006","ושואלים: \u0003ויתיר\u0004 את ה\u0003חבלים ויפלו\u0004 ה\u0003שקין\u0004 מאליהם! ומשיבים: לא עשה זאת משום החשש שמא \u0003מיצטרו זיקי\u0004 \u0005[יבקעו הנאדות]\u0006 שהדבש מונח בהם. ושואלים: \u0003ויביא כרים וכסתות ויניח תחתיהן!\u0004 ומשיבים: יש חשש שמא \u0003מטנפי\u0004 \u0005[יתלכלכו]\u0006 \u0003וקמבטל\u0004 \u0005[ו\u0006הרי \u0005הוא מבטל]\u0006 בכך \u0003כלי מהיכנו.\u0004 ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בדבר משום \u0003צער בעלי חיים\u0004 וראוי לו לוותר על הפסדו משום כך! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רבן גמליאל שאיסור \u0003צער בעלי חיים\u0004 אינו מן התורה אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, ואינו חייב להפסיד משום כך (רמב\"ן).","מסופר: \u0003אביי אשכחיה ליה\u0004 \u0005[מצא אותו]\u0006 את \u0003רבה דקא\u0004 \u0005[שהוא]\u0006 \u0003משפשף ליה לבריה אגבא דחמרא\u0004 \u0005[את בנו\u0006 לשעשעו \u0005על גב החמור]\u0006 בשבת \u0003אמר ליה\u0004 \u0005[לו]:\u0006 והלא \u0003קא משתמש מר\u0004 \u0005[משתמש הוא אדוני]\u0006 \u0003בבעלי חיים,\u0004 ואסרו חכמים כל שימוש בבעלי חיים בשבת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: לא הנחתי את הילד על גבי החמור אלא בצידו, \u0003וצדדין הן, וצדדין לא גזרו בהו רבנן\u0004 \u0005[גזרו בהם חכמים]\u0006 איסור. \u0003מנא תימרא\u0004 \u0005[מנין תאמר]\u0006 שכן הוא — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מתיר\u0004 את ה\u0003חבלים והשקין נופלין\u0004 מאליהם. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004אופן ש\u0003חבר\u0004 את השקים כדרך \u0003גוולקי,\u0004 שהצמידם באמצעות רצועות לבהמה באופן אינו יכול להתיר את השקים אלא אם כן ישען על צידי הבהמה ויתירם, ונמצא \u0003דהוו להו\u0004 \u0005[שהרי הם]\u0006 \u0003צדדין וצדדין לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 איסור.","ענה לו אביי: \u0003לא,\u0004 אין זו הוכחה גמורה ויתכן שכאן מדובר \u0003בחבר\u0004 את השקים כדרך \u0003אגלווקי,\u0004 שלא הצמידם לבהמה בקשר טוב שכדי להתירו צריך להשען על צידי הבהמה, אלא תפוסים לאוכף על ידי וו שדי בשמיטתו בקלות כדי לנתקם מן הבהמה, ואין צריך להשען על צידי הבהמה לשם כך, \u0003דלא הוו\u0004 \u0005[שאין אלה]\u0006 בכלל \u0003צדדין. אי נמי, בלכתא\u0004 \u0005[או גם כן, בחבל]\u0006 שהיו השקים קשורים לצידי הבהמה בחבל, ויכול להתירם בלא להשען עליה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה שאמרו במשנה: סוכה שבנה לה \u0003שתים\u0004 (שתי דפנות) \u0003בידי אדם\u0004 על הקרקע, \u0003ו\u0004דופן \u0003אחת באילן\u0004 — הרי זו סוכה \u0003כשרה\u0004 למצוותה, \u0003ו\u0004אולם \u0003אין עולין לה\u0004 ואין משתמשים בה \u0003ביום טוב,\u0004 שאסור להשתמש בשבת ויום טוב באילנות המחוברים לארץ. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן באופן \u0003דחק ביה\u0004 \u0005[שחקק בו]\u0006 \u0003באילן\u0004 ובתוך החור שנוצר הכניס קורה המחזיקה את הדופן \u0003דהוו להו צדדין ו\u0004נמצא משתמש בצידי האילן, הרי ש\u0003צדדין אסורין!\u0004","ודחה רבה: \u0003לא,\u0004 מדובר כאן באופן \u0003דכפייה\u0004 \u0005[שכפפו]\u0006 \u0003לאילן ואנח\u0004 \u0005[והניח]\u0006 \u0003סיכוך\u0004 (סכך) \u0003עילויה דקמשמש\u0004 \u0005[על גביו שהרי הוא משתמש]\u0006 \u0003באילן\u0004 עצמו. והקשה לו אביי: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמר את סופה\u0006 של המשנה] \u0003שלש\u0004 דפנות \u0003בידי אדם ואחת באילן;\u0004 הרי זו סוכה \u0003כשרה, ועולין לה ביום טוב. ואי דכפייה לאילן\u0004 — \u0003אמאי\u0004 \u0005[ואם כפף את האילן\u0006 ובנה עליו, \u0005מדוע]\u0006 \u0003עולין לה ביום טוב?\u0004","ודחה רבה: \u0003ואלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 ש\u0003צדדין אסורין?\u0004 ואולם גם אם צדדים אסורים קיימת אותה בעייה: \u0003סוף סוף אמאי\u0004 \u0005[מדוע]\u0006 \u0003עולין לה ביום טוב? אלא\u0004 בעל כרחך עליך לפרש באופן אחר: \u0003התם בגואזא פרסכנא\u0004 \u0005[שם בענפים פרושים]\u0006 שה\u0003אילן גופיה\u0004 \u0005[עצמו]\u0006 \u0003דופן בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא דשוויה\u0004 \u0005[שעשאו],\u0006 ולא סמך דופן אחר לאילן. \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 כהסבר זה, ולכן אם הדופן היא חלק מהכשר הסוכה ושצריכה שלוש דפנות — אין להשתמש בה, אבל כדופן רביעית אינה פוסלת משימוש ביום טוב, ששנינו \u0003זה הכלל: כל אילו שינטל האילן ויכולה\u0004 הסוכה עדיין \u0003לעמוד\u0004 — \u0003עולין לה ביום טוב.\u0004 נמצא שאין הדפנות נשענות באילן, אלא האילן עצמו משמש דופן. ומסכמים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 ש\u0005כ\u0006מחלוקת \u0005תנאים]\u0006 היא שנויה בענין שימוש בצדדים, ששנינו בתוספתא לגבי סוכה הנשענת באילן ש\u0003אין עולין לה ביום טוב. ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר: עולין לה ביום טוב. מאי לאו, בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה נחלקו];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]\u0006 ש\u0003צדדין אסורין ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר \u0005סבור]:\u0006 \u0003מותרין?\u0004","\u0003אמר אביי: לא,\u0004 אפשר לפרש כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003צדדין אסורין, ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בצדי צדדין קמיפלגי\u0004 \u0005[נחלקו],\u0006 כלומר,: לא בדבר הנשען על האילן עצמו, אלא בדופן הנתמכת בקורה והקורה נשענת בצידו של האילן. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים \u0005סבור]\u0006 ש\u0003צדי צדדין אסורין, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר \u0005סבור]\u0006 ש\u0003צדי צדדין מותרין.\u0004","\u0003רבא אמר: מאן דאסר\u0004 \u0005[מי שאוסר]\u0006 \u0003בצדדין\u0004 — \u0003אסר נמי\u0004 \u0005[גם כן]\u0006 \u0003בצדי צדדין, מאן דשרי\u0004 \u0005[מי שהתיר]\u0006 \u0003בצדי צדדין\u0004 — \u0003שרי נמי\u0004 \u0005[התיר גם כן]\u0006 \u0003בצדדין. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב משרשיא לרבא\u0004 ממה ששנינו: \u0003נעץ\u0004"],["\u0003יתד באילן ותלה בה כלכלה\u0004 (סל) שרוחבו ארבעה על ארבעה טפחים, ובאותו סל הניח את עירוב התחומים שלו. אם היה הסל \u0003למעלה מעשרה טפחים\u0004 — \u0003אין עירובו עירוב,\u0004 כיון שאינו יכול להוציאו משם בשבת, שהרי סל זה שרחבו ארבעה טפחים ומוגבה עשרה הריהו כרשות היחיד, והוא ברשות אחרת. ואם היה \u0003למטה מעשרה טפחים\u0004 — \u0003עירובו עירוב.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא ש\u0003נעץ יתד באילן\u0004 ועליה תלה את הסל, ורק בכגון זה בלמטה מעשרה עירובו עירוב, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נעץ\u0004 יתד באילן לשם כך אלא קשר את הכלכלה באילן עצמו, \u0003אפילו למטה מעשרה טפחים\u0004 — \u0003אין עירובו עירוב,\u0004 משום שהוא משתמש בצידי האילן כשבא ליטול את הפת. נמצא איפוא כי \u0003הא האי תנא דקאסר\u0004 \u0005[הרי תנא זה האוסר]\u0006 \u0003בצדדין, ו\u0004עם כל זה \u0003קשרי\u0004 \u0005מתיר]\u0006 \u0003בצדי צדדין,\u0004 ושלא כדברי רבא!","\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 \u0003בכלכלה דחוקה\u0004 שפיה צר וקשורה בחזקה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שכיון שאינו יכול להוציא מתוכה ברווח, \u0003דבהדי דשקיל ליה\u0004 \u0005[שכאשר נוטל אותו]\u0006 את ה\u0003עירוב\u0004 — \u0003קמניד ליה\u0004 \u0005[מניד הוא אותו],\u0006 את ה\u0003אילן, וקמשמש\u0004 \u0005[ומשתמש]\u0006 \u0003באילן גופיה\u0004 \u0005[עצמו],\u0006 ונמצא שאין כאן ענין של צידי צדדים אלא של צדדים ואילן עצמו. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא ש\u0003צדדין אסורין\u0004 בשימוש בין באילן בין בבהמה, \u0003צדי צדדין\u0004 — \u0003מותרין.\u0004","\u0003אמר רב אשי: השתא דאמרת\u0004 \u0005[עכשיו שאומר אתה]\u0006 כי להלכה \u0003צדדין אסורין, האי דרגא דמדלא\u0004 \u0005[סולם זה ש\u0006הוא \u0005מוגבה]\u0006 — \u0003לא לינחיה איניש אדיקלא\u0004 \u0005[יניחנו אדם על הדקל\u0006 עצמו\u0005],\u0006 \u0003דהוו להו\u0004 \u0005[שהרי הם]\u0006 בכלל \u0003צדדין\u0004 ואסור להשתמש אף בצידי אילן בשבת. \u0003אלא, לינחיה אגוואזי לבר מדיקלא\u0004 \u0005[יניחנו על יתדות שנועץ בדקל\u0006 גופו\u0005],\u0006 \u0003וכי סליק\u0004 \u0005[וכאשר\u0006 הוא \u0005עולה]\u0006 — ש\u0003לא לינח כרעיה אגוואזי\u0004 \u0005[יניח רגלו על היתדות\u0006 עצמן\u0005],\u0006 \u0003אלא ליתנח אקנין\u0004 \u0005[יניח על הקנים,\u0006 שלבי הסולם\u0005],\u0006 מאותו טעם שאסור להשתמש בצידי האילן.","\u0003מתירין\u0004 בשבת \u0003פקיעי עמיר\u0004 (חבילות תבואה) \u0003לפני בהמה, ומפספסין\u0004 (מדללים, מרופפים) \u0003את הכיפין, אבל לא את הזירין. אין מרסקין\u0004 בשבת \u0003לא את השחת ולא את החרובין לפני בהמה\u0004 כדי להקל עליה את האכילה, \u0003בין\u0004 לצורך בהמה \u0003דקה ובין\u0004 לצורה ה\u0003גסה. ר' יהודה מתיר\u0004 לרסק \u0003בחרובין לדקה,\u0004 שקשה לה ללעוס את החרובים הקשים.","\u0003אמר רב הונא: הן הן פקיעין, הן הן כיפין,\u0004 ששניהם חבילות של שיבלים, אלא, ההבדל הוא כי \u0003פקיעין\u0004 הן חבילות הקשורות ב\u0003תרי\u0004 \u0005[שני]\u0006 קשרים, \u0003כיפין\u0004 ב\u0003תלתא\u0004 \u0005[שלושה]\u0006 קשרים. ו\u0003זירין\u0004 שנאסר לטפל בהם בשבת הם חבילות \u0003דארזי\u0004 \u0005[של\u0006 ענפי \u0005ארז],\u0006 שראויים לבהמה בעודם לחים וקטנים. \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש לפרש את המשנה: \u0003מתירין פקיעי עמיר לפני בהמה, ומפספסין. והוא הדין לכיפין, אבל לא את הזירין\u0004 — שאותם אסור \u0003לא לפספס ולא להתיר. אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב הונא\u0004 — \u0003קא סבר\u0004 \u0005[הוא סבור]\u0006 ש\u0003למטרח באוכלא\u0004 \u0005[לטרוח באוכל]\u0006 — \u0003טרחינן\u0004 \u0005[טורחים אנו],\u0006 ואולם \u0003לשוויי אוכלא לא משוינן\u0004 \u0005[לעשות אוכל אין אנו עושין]\u0006 ולכן, העמיר שהוא מאכל הראוי לבהמה — מותר לטפל בו כדי להכשירו יותר, אבל ענפי הארז שאין הבהמה יכולה לאוכלם בעודם אגודים ויש צורך לעשותם כשרים למאכלה אין להתיר לטרוח ולעסוק בדבר זה.","\u0003רב יהודה אמר\u0004 הסבר אחר לדברי המשנה, ולדעתו \u0003הן הן פקיעין,\u0004 ו\u0003הן הן זירין,\u0004 ששניהם חבילות של שיבלים, אלא, ההבדל הוא כי \u0003פקיעין\u0004 קשורים ב\u0003תרי\u0004 \u0005[שני\u0006 קשרים\u0005],\u0006 ואילו \u0003זירין\u0004 ב\u0003תלתא\u0004 \u0005[שלושה],\u0006 ו\u0003כיפין\u0004 הן חבילות \u0003דארזי\u0004 \u0005[של\u0006 ענפי \u0005ארז].\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש לפרש את המשנה: \u0003מתירין פקיעי עמיר לפני בהמה, אבל פספוסי\u0004 \u0005[לפספס]\u0006 — \u0003לא\u0004 התירו, \u0003וכיפין\u0004 — \u0003פספוסי נמי מפספסינן\u0004 \u0005[לפספס גם כן מפספסים אנו],\u0006 \u0003אבל לא הזירין,\u0004 שאותם אסור \u0003לפספס אלא להתיר\u0004 בלבד. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 היפך שיטתו של רב הונא: \u0003שווי אוכלא\u0004 \u0005[לעשות\u0006 דבר ל\u0005אוכל]\u0006 — \u0003משוינן\u0004 \u0005[עושים אנו],\u0006 ואולם \u0003מטרח באוכלא\u0004 \u0005[לטרוח באוכל]\u0006 — \u0003לא טרחינן\u0004 \u0005[אין אנו טורחים]\u0006 שכיון שהדבר ראוי למאכל לבהמה גם אין לטרוח בכך טרחה יתירה בשבת.","\u0003תנן\u0004 \u0005[שנינו\u0006 בהמשך \u0005המשנה]:\u0006 \u0003אין מרסקין את השחת ואת החרובין לפני בהמה, בין דקה ובין גסה. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003חרובין דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שחת, מה שחת דרכיכי\u0004 \u0005[ש\u0006הם \u0005רכים],\u0006 \u0003אף חרובין\u0004 מדובר באופן \u0003דרכיכי\u0004 \u0005[ש\u0006הם \u0005רכים].\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003לא טרחינן באוכלא\u0004 \u0005[אין אנו טורחים במאכל],\u0006 שכיון שראויים החרובים לבהמה גם בלא ריסוק אין טורחים עוד בהם. \u0003ו\u0004הרי זו \u0003תיובתיה\u0004 \u0005[תשובתו,\u0006 קושיה חמורה\u0005]\u0006 על \u0003רב הונא.\u0004","ומתרצים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב הונא : לא, שחת דומיא\u0004 \u0005בדומה\u0006 ל\u0003חרובין; מה חרובין דאקושי\u0004 \u0005[ש\u0006הם \u0005קשים],\u0006 \u0003אף שחת\u0004 מדובר באופן \u0003דאקושי\u0004 \u0005[ש\u0006הם \u0005קשים]\u0006 וריסוקם הוא יצירת אוכל. ושואלים: \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 אפשרות שתהיה שחת קשה מכדי מאכל בהמה? ומשיבים: \u0003בעילי זוטרי\u0004 \u0005[בעיירים קטנים]\u0006 שאינם יכולים לאכול אלא שחת מרוסקת היטב.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לדבר ממה ששנינו בהמשך המשנה: \u0003ר' יהודה מתיר בחרובין לדקה.\u0004 ונדייק: \u0003לדקה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לגסה\u0004 — \u0003לא.\u0004 ומעתה, \u0003אי אמרת בשלמא תנא קמא סבר\u0004 \u0005[נניח אומר אומר אתה\u0006 ש\u0005התנא הראשון סבור]\u0006 ש\u0003מיטרח באוכלא לא טרחינן\u0004 \u0005[לטרוח באוכל אין אנו טורחים]\u0006 ואולם \u0003שווי משוינן\u0004 \u0005[לעשות\u0006 אוכל \u0005יוצרים]\u0006 \u0003היינו דקא אמר\u0004 \u0005[זהו שאמר]\u0006 \u0003ר' יהודה\u0004 ש\u0003החרובין לדקה נמי שווי אוכלא\u0004 \u0005[גם כן עשיית אוכל]\u0006 \u0003הוא,\u0004 שאין הבהמה הדקה יכולה כלל לאכול חרובים קשים. \u0003אלא, אי אמרת תנא קמא סבר\u0004 \u0005[אם אומר אתה\u0006 ש\u0005התנא הראשון סבור]\u0006 כי \u0003שווי אוכלא לא משוינן, מיטרח באוכלא מטרחינן\u0004 \u0005[לעשות אוכל אין אנו עושים, לטרוח באוכל אנו טורחים],\u0006 \u0003ר' יהודה\u0004 ה\u0003מתיר\u0004 רק \u0003בחרובין לדקה\u0004 ולא \u0003לגסה, כל שכן\u0004 שעליו להתיר \u0003לגסה!\u0004 שהרי אם ראויים החרובים למאכל בהמה דקה כל שכן שראויים למאכל לגסה!","ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 בהמה \u0003דקה\u0004 שהוזכרה כאן כוונתו ל\u0003דקה ממש?\u0004 לא, אלא \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה \u0003\"דקה\"\u0004 — \u0003גסה, ומאי קרי\u0004 \u0005[ומה\u0006 הסיבה שהוא \u0005קורא]\u0006 \u0003לה \"דקה\"\u0004 — \u0003דדייקא באוכלא\u0004 \u0005[ש\u0006היא \u0005מדקדקת במאכלה],\u0006 וכיון שבשעת הדחק תוכל בהמה זו לאכול חרובים שאינם מרוסקים — טורחים באוכל ומרסקים אותם.","ומקשים: \u0003הא מדקתני רישא\u0004 \u0005[הרי ממה ששנינו מתחילה]\u0006 \u0003\"בין דקה ובין גסה\" מכלל\u0004 הדברים נלמד ש\u0003ר' יהודה\u0004 שאמר \u0003\"דקה\"\u0004 \u0005—\u0006 \u0003דקה ממש קאמר\u0004 \u0005[אמר,\u0006 התכוין\u0005]!\u0006 לשאלה זו לא נמצאה תשובה והיא נשארה \u0003קשיא\u0004 \u0005[קשה].\u0006","ואולם עדיין לא נדחתה שיטת רב הונא, ועל כן \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה אחרת לדבר ממה ששנינו במשנה אחרת: \u0003מחתכין\u0004"],["\u0003את הדלועין לפני הבהמה ואת הנבלה לפני הכלבים. מאי לאו\u0004 \u0005[האם\u0006 \u0003לא] דלועין דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נבלה, מה נבלה\u0004 — \u0003דרכיכא\u0004 \u0005[ש\u0006היא \u0005רכה],\u0006 \u0003אף דלועין דרכיכי\u0004 \u0005[ש\u0006הם \u0005רכים],\u0006 \u0003אלמא\u0004 \u0005[\u0006ו\u0005מכאן]\u0006 ש\u0003טרחינן באוכלא\u0004 \u0005[טורחים אנו באוכל],\u0006 \u0003ותיובתא\u0004 \u0005[ו\u0006הרי זו \u0005קושיה חמורה]\u0006 ל\u0003רב יהודה! אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יהודה: לא,\u0004 מדובר כאן ב\u0003נבלה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003דלועין: מה דלועין דאשוני\u0004 \u0005[ש\u0006הם \u0005קשים],\u0006 \u0003אף נבלה\u0004 — \u0003דאשונא\u0004 \u0005[ש\u0006היא \u0005קשה]\u0006 ויש לעשותה ראויה למאכל. ושואלים: \u0003והיכי משכחת לה\u0004 \u0005[ואיך מוצא אתה אותה]\u0006 אפשרות שתהיה הנבילה קשה מכדי לשמש מאכל לכלבים? — \u0003בבשר פילי\u0004 \u0005[פילים].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לומר שמדובר כאן בבשר רגיל, ואולם מדובר כאן \u0003בגורייאתא זוטרי\u0004 \u0005[בגורים קטנים],\u0006 שצריכים שיחתכו להם כל בשר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב חנן מנהרדעא: מפרכינן\u0004 \u0005[מפוררים]\u0006 בשבת \u0003תבן ואספסתא\u0004 \u0005[ואספסת]\u0006 \u0003ומערבין\u0004 את שניהם יחד, והבהמה אוכלת את שניהם בשביל האספסת. \u0003אלמא\u0004 ש\u0003טרחינן באוכלא\u0004 \u0005[טורחים אנו באוכל]!\u0006 ודוחים: לא, \u0003תבן\u0004 שאמרו כאן הרי הוא \u0003בתיבנא סריא\u0004 \u0005[בתבן רקוב]\u0006 שיש לעשות בו כמה פעולות עד שיהיה ראוי למאכל בהמה, ו\u0003אספסתא\u0004 מדובר — \u0003בעילי זוטרי\u0004 \u0005[בעיירים קטנים]\u0006 שאינם יכולים לאכול את האספסת אלא אם כן יחתכוה עבורם.","\u0003אין אובסין\u0004 (מאכילים הרבה ובעל כרחו) בשבת \u0003את הגמל, ו\u0004אף \u0003לא דורסין\u0004 (תוחבים לו בעל כורחו) מאכל. \u0003אבל מלעיטין\u0004 אותו. \u0003ואין מאמירין את העגלים, אבל מלעיטין. ומהלקטין לתרנגולין, ונותנין מים למורסן\u0004 (מוץ ושיירי טחינה המשמשים למאכל בהמה), \u0003אבל לא גובלין\u0004 (לשים) את המורסן והמים. \u0003ואין נותנין מים לפני דבורים ולפני יונים שבשובך,\u0004 לפי שהן מתפרנסות בעצמן, \u0003אבל נותנין\u0004 מים \u0003לפני אווזין ותרנגולין, ולפני יוני הרדיסיות\u0004 (יוני בית).","שנינו במשנה שאין אובסין את הגמל בשבת. ושואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין אובסין\"? אמר רב יהודה: אין\u0004 מאכילים אותה עד ש\u0003עושין לה אבוס בתוך מעיה.\u0004 ושואלים: \u0003מי איכא כי האי גוונא\u0004 \u0005[האם יש מעין זה]\u0006 שאפשר להאכיל כל כך את הגמל? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003וכ\u0004פי ש\u0003אמר רב ירמיה מדיפתי: לדידי חזי לי ההוא טייעא דאכלא כורא, ואטעינא כורא\u0004 \u0005[אני ראיתי ערבי\u0006 אחד \u0005שהאכיל\u0006 את גמלו \u0005כור\u0006 מזון, \u0005והטעינו כור].\u0006","שנינו במשנה ש\u0003אין מאמירין\u0004 את העגלים אבל מלעיטין\" ושואלים: \u0003איזו היא המראה ואיזו היא הלעטה? אמר רב יהודה: המראה\u0004 כוונתו שתוחב לבהמה בגרונה \u0003למקום שאינה יכולה להחזיר\u0004 (לפלוט, להקיא), \u0003הלעטה\u0004 — שמכניס לה בפיה \u0003למקום שיכולה להחזיר. רב חסדא אמר: אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003למקום שאינה יכולה להחזיר, ו\u0004אולם \u0003המראה\u0004 הריהי \u0003בכלי,\u0004 שתוחב על ידי כלי, \u0003הלעטה\u0004 — \u0003ביד.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 ממה ששנינו בתוספתא: \u0003מהלקטין לתרנגולין, ואין צריך לומר שמלקיטין. ואין מלקיטין ליוני שובך וליוני עלייה, ואין צריך לומר שאין מהלקטין.\u0004 ומעתה נברר \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"מהלקטין\" ומאי\u0004 \u0005[ומהו]\u0006 \u0003\"מלקיטין\". אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"מהלקטין\"\u0004 פירושו \u0003דספי ליה\u0004 \u0005[שמאכיל אותו]\u0006 \u0003בידים\u0004 ואילו \u0003\"מלקיטין\"\u0004 פירושו \u0003דשדי ליה קמייהו\u0004 \u0005[שזורק אותו,\u0006 את האוכל, \u0005לפניהם],\u0006 \u0003מכלל\u0004 זה אתה למד ש\u0003יוני שובך ויוני עלייה מישדא קמייהו נמי לא\u0004 \u0005[לזרוק לפניהם גם כן לא\u0006 התיר\u0005],\u0006 ומה איסור יש בדבר זה?","\u0003אלא לאו\u0004 \u0005[הם לא]\u0006 \u0003\"מהלקטין\"\u0004 משמעו — שתוחבים את המזון לעוף \u0003למקום שאינה יכולה להחזיר, \"מלקיטין\"\u0004 — \u0003למקום שיכולה להחזיר,\u0004 וכיון שכך הרי הלקטה בעופות היא בדומה להלעטה לעגלים שאותה התירה משנתנו, ו\u0003מכלל\u0004 הדברים אתה למד כי \u0003המראה\u0004 שאסרה המשנה הריהי \u0003בכלי,\u0004 והרי זאת \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רב יהודה!\u0004","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב יהודה: לעולם\u0004 נפרש כי \u0003\"מהלקטין\"\u0004 משמעו — \u0003דספי ליה\u0004 \u0005[שמאכיל אותו]\u0006 \u0003בידים,\u0004 ואילו \u0003\"מלקיטין\"\u0004 משמעו — \u0003דשדי ליה קמייהו\u0004 \u0005[שזורק אותו,\u0006 את האוכל, \u0005לפניהם],\u0006 \u0003ודקא קשיא\u0004 \u0005[ו\u0006זה \u0005שהיה קשה]\u0006 \u0003לך\u0004 האם ב\u0003יוני שובך ויוני עלייה למישדא קמייהו נמי\u0004 \u0005[לזרוק לפניהם\u0006 אוכל בשבת \u0005גם כן]\u0006 \u0003לא\u0004 הותר? אין בכך קושי, כי \u0003הני\u0004 \u0005[אלה]\u0006 תרנגולים ואווזים \u0003מזונותן עליך\u0004 ואינם מתפרנסים אלא על ידי בעליהם. \u0003והני\u0004 \u0005[ו\u0006אילו \u0005אלה]\u0006 היונים \u0003אין מזונותן עליך\u0004 ולכך אסור לתת בפניהם מזונות. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 כיוצא בזה בברייתא\u0005]:\u0006 \u0003נותנין\u0004 בשבת \u0003מזונות לפני כלב, ואין נותנין מזונות לפני חזיר. ומה הפרש בין זה לזה? זה\u0004 — הכלב \u0003מזונותיו עליך, וזה,\u0004 החזיר, \u0003אין מזונותיו עליך,\u0004 שאין אדם מישראל מגדל חזירים.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהסבר זה, שכן אמרו ש\u0003אין נותנין מים לפני דבורים ולפני יונים שבשובך, אבל נותנין לפני אווזין ולפני תרנגולין ולפני יוני הרדיסיות. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הבדל זה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דהני\u0004 \u0005[שאלה]\u0006 אווזים ותרנגולים \u0003מזונותן עליך,\u0004 ודבורים ויונים \u0003אין מזונותן עליך.\u0004","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003מאי איריא מיא\u0004 \u0005[מה\u0006 הסיבה שנקט \u0005דווקא מים]?\u0006 \u0003אפילו חיטי ושערי נמי\u0004 \u0005[חיטים ושעורים גם כן]\u0006 \u0003לא\u0004 יתן! \u0003אלא\u0004 לא זה הטעם, כי אם \u0003שאני מיא דשכיחי באגמא\u0004 \u0005[שונים המים ש\u0006הם \u0005מצויים באגם]\u0006 ובעוד מאגרים ואין צורך לטרוח ולהביא מים לדבורים וליוני שובך היכולים למצוא את מימיהם באותם מאגרים בעצמם, מה שאין כן במזונות.","כיון שדובר בנתינת מזון לכלב מביאים דברים אחרים שנאמרו בנושא זה. \u0003דרש רבי יונה אפיתחא דבי נשיאה\u0004 \u0005[על פתח בית הנשיא]:\u0006 \u0003מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הכתוב]\u0006 \u0003\"ידע צדיק דין דלים\"\u0004 (משלי כט, ז) — \u0003יודע הקדוש ברוך הוא בכלב שמזונותיו מועטין\u0004 ואין מפרנסים אותו כראוי, \u0003לפיכך שוהה אכילתו במעיו שלשה ימים\u0004 כדי שיהיה שבע מאכילה זו. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 העוסקת בדיני טומאה: בעל חיים שבלע בשר המת \u0003כמה תשהה אכילתו במעיו ויהא\u0004 הבשר נחשב עדיין כבר אכילה ובשל כך אף \u0003טמא\u0004 ולא כמעוכל — \u0003בכלב שלשה ימים מעת לעת,\u0004 כלומר, שלש יממות, \u0003ובעופות ובדגים\u0004 עד \u0003כדי\u0004 הזמן \u0003שתפול\u0004 אותה חתיכת בשר \u0003לאור\u0004 (לאש) \u0003ותשרף,\u0004 שהם מעכלים במהירות רבה.","\u0003אמר רב המנונא: שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי \u0003אורח ארעא למשדא אומצא לכלבא\u0004 \u0005[דרך ארץ לזרוק חתיכת בשר לכלב],\u0006 שהרי אף הקדוש ברוך הוא דואג לו למזונותיו. ושואלים: \u0003וכמה\u0004 ראוי לתת לו? \u0003אמר רב מרי: משח אודניה, וחוטרא אבתריה\u0004 \u0005[\u0006תן לו \u0005כמידת אוזנו, ומיד\u0006 להכות \u0005במקל אחריו]\u0006 שלא יהא הכלב נגרר אחריו. ו\u0003הני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא \u0003בדברא\u0004 \u0005[בשדה],\u0006 \u0003אבל במתא\u0004 \u0005[בעיר]\u0006 \u0003לא\u0004 יתן לו כלום, משום \u0003דאתי למסרך\u0004 \u0005[שיבוא להיטפל]\u0006 וייגרר אחריו תמיד. \u0003אמר רב פפא: לית דעניא מכלבא, ולית דעתיר מחזירא\u0004 \u0005[אין עני מכלב, ואין עשיר מחזיר]\u0006 שאוכל הכל, ואף ממציאים לו מזונות בשפע.","ולענין הלכה \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה: איזו היא המראה ואיזו היא הלעטה? המראה\u0004 — שכופה את הבהמה ו\u0003מרביצה\u0004 לארץ, \u0003ופוקס\u0004 (פותח בכוח) \u0003את פיה ומאכילה כרשינין ומים בבת אחת,\u0004 שאינה יכולה לפולטם. \u0003הלעטה\u0004 — \u0003מאכילה ומשקה\u0004 כדרכה, \u0003ונותנין\u0004 לה \u0003כרשינין בפני עצמן ומים בפני עצמן,\u0004 שהוא רק מסייע לה במה שאוכלת בעצמה.","שנינו במשנה ש\u0003מהלקטין לתרנגולין\u0004 ונותנים מים למורסן אבל לא גובלים. \u0003אמר אביי, אמריתה קמיה דמר\u0004 \u0005[אמרתי\u0006 זאת \u0005לפני אדוני,\u0006 מורי, רבה\u0005]:\u0006 \u0003מתניתין מני\u0004 \u0005[\u0006\u0005משנתנו\u0006 שיטת \u0005מי היא]?\u0006 \u0003ואמר לי\u0004 רבי: כשיטת \u0003ר' יוסי בר יהודה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היה \u0003אחד נותן את הקמח ואחד נותן לתוכו מים\u0004 — \u0003האחרון חייב\u0004 משום לש, \u0003אלו דברי רבי. ר' יוסי בר יהודה אומר: אינו חייב\u0004 משום לש \u0003עד שיגבל\u0004 (ילוש) ממש את הקמח והמים, ואין די בנתינת המים לקמח.","ושיטה זו דומה לדברי המשנה שמותר לתת מים, אבל לא לגבל. ודוחים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי בר יהודה התם\u0004 \u0005[שם]\u0006 \u0003אלא\u0004 ב\u0003קמח\u0004 ש\u0003בר גיבול הוא,\u0004 שהוא ניתן לגיבול, \u0003אבל מורסן\u0004 שאינו ראוי כלל ל\u0003גיבול, אפילו ר' יוסי בר יהודה מודה\u0004 שיש בכך מלאכת לישה, אף אם אינו מגבל ממש, כיון שאין המורסן נעשה לעולם עיסה כבצק של קמח. ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כהסבר הזה, \u0003דתניא בהדיא\u0004 \u0005[\u0006\u0005ש\u0006כן \u0005שנינו\u0006 ברייתא \u0005מפורשת]:\u0006 \u0003אין נותנין\u0004 בשבת \u0003מים למורסן,\u0004 אלו \u0003דברי רבי. ר' יוסי בר יהודה אומר: נותנין מים למורסן.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין גובלין\u0004 בשבת \u0003את הקלי\u0004 (קמח של שבלים שיובשו בתנור לפני גמר בישולן). \u0003ויש אומרים: גובלין.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 \u0003\"יש אומרים\"\u0004 זה? \u0003אמר רב חסדא:\u0004"],["\u0003ר' יוסי בר' יהודה היא. והני מילי הוא דמשני\u0004 \u0005[ודברים אלה\u0006 מותרים כאשר \u0005משנה\u0006 בגיבול\u0005].\u0006 ושואלים: \u0003היכי משני\u0004 \u0005[כיצד משנה]?\u0006 \u0003אמר רב חסדא\u0004 שאינו גובל בבת אחת אלא \u0003על יד על יד\u0004 \u0005[מעט מעט].\u0006","עוד שנינו: \u0003ושוין שבוחשין את השתית\u0004 (מאכל עשוי קלי) \u0003בשבת ושותים זיתום המצרי,\u0004 לפי שאין בו משום רפואה. ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003\"אין גובלין\"\u0004 ופה נאמר שמסכימים הכל שמותר לבחוש את השתית, אף שבחישה זו כעין גיבול היא! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 שיש לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שנחלקו בשתית הרי זה \u0003בעבה,\u0004 שהוא כעין גיבול, ואולם \u0003הא\u0004 \u0005[זה]\u0006 שמשמע שרק גיבול אסור ואולם בחישה מותרת, הרי זה — \u0003ברכה,\u0004 שאין זו לישה. \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 \u0003הוא\u0004 באופן \u0003דמשני\u0004 \u0005[שמשנה\u0006 בעשייתם\u0005].\u0006","ושואלים: \u0003היכי משני\u0004 \u0005[כיצד משנה]?\u0006 \u0003אמר רב יוסף:\u0004 השינוי הוא בכך שכרגיל \u0003בחול\u0004 דרכו ש\u0003נותן\u0004 תחילה \u0003את החומץ ואחר כך נותן את השתית,\u0004 ואילו \u0003בשבת נותן\u0004 תחילה \u0003את השתית ואחר כך נותן את החומץ.\u0004 מסופר: \u0003לוי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא בר חייא אשכחיה לגבלא דבי נשיה דקא גביל וספי ליה לתוריה\u0004 \u0005[מצא את הגבל של בית הוריו שמגבל\u0006 מורסן \u0005ומאכיל אותו לשורו].\u0006 \u0003בטש ביה\u0004 \u0005[בעט בו]\u0006 שיפסיק. \u0003אתא אבוה אשכחיה\u0004 \u0005[בא אביו\u0006 של לוי ו\u0005מצאו]\u0006 ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבוה דאמך משמיה\u0004 \u0005[אבי אמך משמו]\u0006 של \u0003רב,\u0004 ומעירים: \u0003ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]?\u0006 — \u0003ר' ירמיה בר אבא: גובלין ולא מספין\u0004 \u0005[מאכילים],\u0006 \u0003ודלא לקיט בלישניה\u0004 \u0005[ועגל שאינו לוקט,\u0006 לוקח אוכל \u0005בלשונו]\u0006 — \u0003מהלקיטין ליה\u0004 \u0005[מאכילים אותו].\u0006 \u0003והני מילי הוא דמשני\u0004 \u0005[ודברים אלה\u0006 מותרים \u0005כאשר משנה].\u0006","ושואלים: \u0003היכי משני\u0004 \u0005[איך משנה\u0006 בגיבול\u0005]?\u0006 \u0003אמר רב יימר בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי :\u0004 שמעביר את התרווד או שאר כלי שבוחש בו במורסן \u0003שתי וערב.\u0004 ושואלים: \u0003והא לא מערב שפיר\u0004 \u0005[והרי אינו מתערב יפה],\u0006 ומה מועיל אם כן בפעולה זו? \u0003אמר רב יהודה:\u0004 הכוונה היא ש\u0003מנערו לכלי.\u0004","באותו ענין \u0003כתיב אפינקסיה\u0004 \u0005[כתוב\u0006 היה \u0005על פנקסו]\u0006 של \u0003זעירי: אמרית קדם\u0004 \u0005[אמרתי לפני]\u0006 \u0003רבי,\u0004 ואגב מעירים: \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 \"רבי\" זה — \u0003ר' חייא,\u0004 וזה שאמרתי לפניו: \u0003מהו\u0004 הדין, האם מותר \u0003לגבל\u0004 בשבת? \u0003אמר: אסור. מהו לפרק,\u0004 כלומר, לתת את הכלי מבהמה אחת לחברתה? \u0003אמר: מותר. אמר רב מנשיא: חד קמי חד, תרי קמי תרי\u0004 \u0005[\u0006כלי \u0005אחד לפני\u0006 בהמה \u0005אחת, שני\u0006 כלים \u0005לפני\u0006 \u0005שתי\u0006 בהמות\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006 \u0003תלתא קמי תרי\u0004 — \u0005[שלושה\u0006 כלים \u0005לפני\u0006 \u0005שתי\u0006 בהמות\u0005]\u0006 — \u0003אסור,\u0004 שיש בכך טרחה יתירה, שנותן לבהמה מזון יותר מן הרגיל. \u0003רב יוסף אמר:\u0004 מותר להוסיף \u0003קב ואפילו קביים. עולא אמר:\u0004 מותר להוסיף \u0003כור, ואפילו כוריים,\u0004 ואין מקפידים על כך כלל.","\u0003כתיב אפינקסיה\u0004 \u0005[כתוב\u0006 היה \u0005על פנקסו]\u0006 של \u0003לוי: אמרית קדם\u0004 \u0005[אמרתי לפני]\u0006 \u0003רבי,\u0004 ואגב מעירים: \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003רבינו הקדוש,\u0004 הוא ר' יהודה הנשיא, \u0003על דהוו גבלין שתיתא\u0004 \u0005[על שהיו גובלים את השתית]\u0006 \u0003בבבל, והוה צוח\u0004 \u0005[והיה צווח]\u0006 על כך \u0003רבי, ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003רבינו הקדוש, על דהוו\u0004 \u0005[שהיו]\u0006 \u0003גבלין שתיתא ולית דשמיע ליה\u0004 \u0005[גובלים את השתית, ולא היה מי ששומע לו],\u0006 \u0003ולית חילא בידיה למיסר\u0004 \u0005[ואין כוח בידו לאסור]\u0006 משום \u0003ר' יוסי בר' יהודה\u0004 שנחלק עליו והתיר, ועליו סמכו כל המתירים.","כיון שהביאו דברים שהיו כתובים על פנקסיהם של חכמים מסופר, כי \u0003כתיב אפינקסיה\u0004 \u0005[כתוב\u0006 היה \u0005על פנקסו]\u0006 של \u0003ר' יהושע בן לוי: האי מאן דבחד בשבא, יהי גבר ולא חדא ביה\u0004 \u0005[מי\u0006 שנולד \u0005באחד בשבת יהא אדם ולא אחת בו].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 \u0003\"ולא חדא ביה\"\u0004 \u0005[ומהו \"ולא אחת בו\"]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003ולא חד לטיבו\u0004 \u0005[\u0006דבר \u0005אחד לטוב]\u0006 בו, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אשי: אנא בחד בשבא הואי\u0004 \u0005[אני באחד בשבת,\u0006 ביום ראשון \u0005הייתי,\u0006 כלומר, נולדתי\u0005],\u0006 ולא שייך לומר בו שלא היה בו דבר אחד לטוב! \u0003אלא\u0004 תאמר שהכוונה היא ש\u0003לא חדא לבישו\u0004 \u0005[אחת לרע],\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אשי: אנא ודימי בר קקוזתא הווין בחד בשבא\u0004 \u0005[נהיינו,\u0006 נולדנו \u0005באחד בשבת],\u0006 \u0003אנא\u0004 נעשיתי \u0003מלך,\u0004 ראש ישיבה, \u0003והוא הוה ריש גנבי\u0004 \u0005[היה ראש גנבים],\u0006 והרי שאין בזה כלל קבוע! \u0003אלא,\u0004 יש לומר: \u0003אי כולי לטיבו אי כולי לבישו\u0004 \u0005[או כולו לטוב או כולו לרע].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דאיברו ביה\u0004 \u0005[שנבראו בו]\u0006 ביום ראשון \u0003אור וחושך.\u0004","\u0003האי מאן דבתרי בשבא יהי גבר\u0004 \u0005[מי ש\u0006נולד \u0005בשני בשבת יהא אדם]\u0006 \u0003רגזן. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום דאיפליגו ביה מיא\u0004 \u0005[שנחלקו בו\u0006 ביום השני \u0005המים]\u0006 העליונים והתחתונים בימי בראשית, והרי הוא איפוא יום של מחלוקת. \u0003האי מאן דבתלתא בשבא\u0004 \u0005[מי ש\u0006נולד \u0005בשלישי בשבת]\u0006 — \u0003יהי גבר עתיר\u0004 \u0005[יהיה אדם עשיר]\u0006 \u0003וזנאי יהא\u0004 \u0005[יהיה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003— משום דאיברו ביה\u0004 \u0005[שנבראו בו]\u0006 \u0003עשבים,\u0004 שהם תמיד בשפע גדול, אבל אינם מקפידים להיות נפרדים זה מזה, אלא גדלים בערבוביה. \u0003האי מאן דבארבעה בשבא\u0004 \u0005[מי ש\u0006נולד \u0005ברביעי בשבת]\u0006 — — \u0003יהי גבר חכים ונהיר\u0004 \u0005[יהיה אדם חכם ובקי].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003— משום דאיתלו ביה מאורות\u0004 \u0005[שניתלו בו המאורות].\u0006 והחכמה משולה לאור.","\u0003האי מאן דבחמשה בשבא\u0004 \u0005[מי ש\u0006נולד \u0005בחמישי בשבת]\u0006 — \u0003יהי גבר\u0004 \u0005[יהיה אדם]\u0006 \u0003גומל חסדים. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003— משום דאיברו ביה\u0004 \u0005[שנבראו בו]\u0006 \u0003דגים ועופות\u0004 שאינם מתפרנסים מעבודתם אצל בני אדם, אלא מזונם ניתן להם בחסד ה'. \u0003האי מאן דבמעלי שבתא\u0004 \u0005[מי ש\u0006נולד \u0005בערב שבת]\u0006 — \u0003יהי גבר\u0004 \u0005[יהיה אדם]\u0006 \u0003חזרן. אמר ר' נחמן בר יצחק:\u0004 הכווה היא שיהיה \u0003חזרן במצו‍ת,\u0004 שכן ערב שבת עיקר הנעשה בו הוא הכנה ליום השבת. \u0003האי מאן דבשבתא יהי\u0004 \u0005[מי ש\u0006נולד \u0005בשבת]\u0006 — \u0003בשבתא ימות,\u0004 וכל זה \u0003על דאחילו עלוהי יומא רבא דשבתא\u0004 \u0005[שחיללו עליו את היום הגדול של השבת],\u0006 שהרי מחללים את השבת מפני שלום הנולדים בו ביום, וכמידה כנגד מידה ימות בשבת. \u0003אמר רבא בר רב שילא: וקדישא רבא יתקרי\u0004 \u0005[וקדוש גדול ייקרא],\u0006 כיון שנולד בשבת שהוא יום קדוש.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' חנינא\u0004 לתלמידיו שספרו לפניו דברים אלה, \u0003פוקו\u0004 \u0005[צאו]\u0006 ו\u0003אמרו ליה לבר ליואי\u0004 \u0005[לו לבן לוי,\u0006 לר' יהושע בן לוי\u0005]:\u0006 \u0003לא מזל יום גורם\u0004 לאופיו של הנולד \u0003אלא מזל שעה גורם; האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004שעת מזל \u0003חמה\u0004 — \u0003יהי גבר זיותן\u0004 \u0005[יהיה אדם יפה],\u0006 \u0003יהי אכיל מדיליה ושתי מדיליה, ורזוהי גליין\u0004 \u0005[יהיה אוכל משלו ושותה משלו, וסודותיו גלויים],\u0006 \u0003אם גניב\u0004 \u0005[יגנוב]\u0006 — \u0003לא מצלח\u0004 \u0005[יצליח],\u0006 שהוא כחמה המאירה, שאורה משלה והיא גלויה לכל. \u0003האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004שעת מזל \u0003כוכב נוגה\u0004 — \u0003יהי גבר עתיר\u0004 \u0005[יהיה אדם עשיר]\u0006 \u0003וזנאי יהי\u0004 \u0005[יהיה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003משום דאיתיליד ביה נורא\u0004 \u0005[שנולדה בו האש]\u0006 בשעה של מזל זה, והיא אש היצר הבוער תמיד. \u0003האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004שעת מזל \u0003כוכב\u0004 — \u0003יהי גבר נהיר וחכים\u0004 \u0005[יהיה אדם בקי וחכם],\u0006 \u0003משום דספרא\u0004 \u0005[שסופר]\u0006 ה\u0003חמה הוא,\u0004 שכוכב חמה סמוך לחמה. \u0003האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004שעת מזל \u0003לבנה יהי גבר סביל מרעין\u0004 \u0005[יהיה אדם סובל מכאובים],\u0006 \u0003בנאי וסתיר, סתיר ובנאי\u0004 \u0005[בונה וסותר, וסותר ובונה],\u0006 \u0003אכיל דלא דיליה ושתי דלא דיליה ורזוהי כסיין\u0004 \u0005[אוכל לא משלא ושותה לא משלו, וסודותיו מכוסים]\u0006 \u0003אם גנב\u0004 \u0005[יגנוב]\u0006 — \u0003מצלח\u0004 \u0005[יצליח],\u0006 כלבנה המשתנה והולכת, שאורה אינו משלה, ופעמים גלויה ופעמים נסתרת. \u0003האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004מזל \u0003שבתאי\u0004 — \u0003יהי גבר מחשבתיה בטלין\u0004 \u0005[יהיה אדם שמחשבותיו בטלות].\u0006 \u0003ואית דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003כל\u0004 מה \u0003דמחשבין עליה בטלין\u0004 \u0005[שחושבים עליו יתבטל].\u0006 \u0003האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004מזל \u0003צדק יהי גבר\u0004 \u0005[יהיה אדם]\u0006 \u0003צדקן. אמר ר' נחמן בר יצחק: וצדקן\u0004 שאמרו הרי זה \u0003במצו‍ת. האי מאן\u0004 \u0005[מי]\u0006 שנולד \u0003ב\u0004מזל \u0003מאדים\u0004 — \u0003יהי גבר אשיד דמא\u0004 \u0005[יהיה אדם שופך דם].\u0006 \u0003אמר ר' אשי: אי אומנא, אי גנבא, אי טבחא, אי מוהלא\u0004 \u0005[או מקיז דם, או גנב, או שוחט, או מוהל].\u0006 \u0003אמר רבה: אנא במאדים הואי\u0004 \u0005[אני הייתי,\u0006 נולדתי \u0005ב\u0006מזל \u0005מאדים]\u0006 ואיני עוסק באף אחת מאומנות אלה. \u0003אמר אביי: מר נמי עניש וקטיל\u0004 \u0005[אדוני גם כן\u0006 כדיין \u0005מעניש והורג].\u0006","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים, \u0003ר' חנינא אומר: מזל מחכים, מזל מעשיר, ויש מזל לישראל. ר' יוחנן אמר: אין מזל לישראל.\u0004 שעם ישראל איננו כפוף לשלטון המזלות, ואין חוקי המזלות חלים עליו. \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן\u0004 בזה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר ר' יוחנן: מניין שאין מזל לישראל? שנאמר: \"כה אמר ה' אל דרך הגוים אל תלמדו ומאתות השמים אל תחתו כי יחתו הגוים מהמה\"\u0004 (ירמיה י, ב) — \u0003גויים יחתו, ולא ישראל.\u0004","\u0003ואף רב סבר\u0004 \u0005[סבור]\u0006 ש\u0003אין מזל לישראל,\u0004 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב : מניין שאין מזל לישראל?\u0004 — \u0003שנאמר\u0004 באברהם: \u0003\"ויוצא אתו החוצה\u0004 ויאמר הבט נא השמימה וספור הכוכבים אם תוכל לספור אותם ויאמר כה יהיה זרעך\u0003\"\u0004 (בראשית טו, ה), ולמדו חכמים ש\u0003אמר אברהם לפני הקדוש ברוך הוא: רבונו של עולם \"\u0004הן לי לא נתת זרע והנה \u0003בן ביתי יורש אתי\"\u0004 (בראשית טו, ג) \u0003אמר לו: לאו\u0004 \u0005[האם לא]\u0006 כאמור \"והנה דבר ה' אליו לאמור לא ירשך זה \u0003כי אם אשר יצא ממעיך\u0004 הוא ירשך\" (בראשית טו, ד)?!","\u0003אמר לפניו\u0004 אברהם: \u0003רבונו של עולם נסתכלתי באיצטגנינות\u0004 (בידיעתי את חכמת המזלות) \u0003שלי, ו\u0004לפי מזלי \u0003איני ראוי להוליד בן. אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא: \u0003צא מאיצטגנינות שלך\u0004 (\"ויוצא אותו\"), \u0003שאין מזל לישראל. מאי דעתיך\u0004 \u0005[מה דעתך],\u0006 מדוע חושב אתה כך?"],["\u0003דקאי\u0004 \u0005[שעומד]\u0006 \u0003צדק במערב\u0004 ולפיכך אין אתה יכול להוליד — \u0003מהדרנא ומוקמינא ליה\u0004 \u0005[אני מחזיר ומעמיד אותו]\u0006 \u0003במזרח. והיינו דכתיב\u0004 \u0005[וזהו שנאמר],\u0006 כך מבינים את הכתוב הנדרש באברהם אבינו: \u0003\"מי העיר ממזרח צדק יקראהו לרגלו\u0004 יתן לפניו גויים ומלכים ירד יתן כעפר חרבו כקש נדף קשתו\" (ישעיה מא, ב) — שהביא הקדוש ברוך הוא את כוכב צדק — בשביל (\"לרגלו\") אברהם אבינו.","\u0003ומ\u0004מה שאירע ל\u0003שמואל נמי\u0004 \u0005[גם כן]\u0006 אפשר לומר ש\u0003אין מזל לישראל.\u0004 שמסופר ש\u0003שמואל ו\u0004החכם הגוי \u0003אבלט הוו יתבי\u0004 \u0005[היו יושבים],\u0006 \u0003והוו קאזלי הנך אינשי לאגמא\u0004 \u0005[והיו הולכים כמה אנשים לאגם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אבלט לשמואל: האי גברא אזיל\u0004 \u0005[אדם זה ילך]\u0006 \u0003ולא אתי\u0004 \u0005[יבוא\u0006 ישוב\u0005],\u0006 כי \u0003טריק ליה חיויא ומיית\u0004 \u0005[יכיש אותו הנחש וימות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל: אי בר\u0004 \u0005[אם בן]\u0006 \u0003ישראל הוא, אזיל ואתי\u0004 \u0005[ילך ויבוא].\u0006 \u0003אדיתבי אזיל ואתי\u0004 \u0005[עד ש\u0006הם \u0005יושבים\u0006 במשך זמן, \u0005הלך ובא]\u0006 אותו האיש,","\u0003קם\u0004 \u0005[עמד]\u0006 \u0003אבלט שדיה לטוניה, אשכח ביה חיויא דפסיק ושדי בתרתי גובי\u0004 \u0005[השליך\u0006 מאותו איש \u0005את משאו ומצא בתוכו נחש שחתוך ומושלך בשני גזרים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל\u0004 לאותו אדם: \u0003מאי עבדת\u0004 \u0005[מה עשית]\u0006 שבשכר זה ניצלת ממות? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003כל יומא הוה מרמינן ריפתא בהדי הדדי ואכלינן\u0004 \u0005[אמר לו בכל יום היינו מטילים\u0006 ונותנים \u0005פת ביחד והיינו אוכלים]\u0006 יחד מן הפת. \u0003האידנא הוה איכא חד מינן\u0004 \u0005[היום היה אחד מאיתנו]\u0006 ש\u0003לא הוה ליה ריפתא\u0004 \u0005[היה לו לחם],\u0006 ובשל כך \u0003הוה קא מיכסף\u0004 \u0005[היה מתבייש]\u0006 שכאשר יגיע זמן גביית הלחם לא יוכל לתת משלו. \u0003אמינא להו\u0004 \u0005[אמרתי להם]\u0006 לבני החבורה: \u0003אנא קאימנא וארמינא\u0004 \u0005[\u0006\u0005אני אקום ואקח\u0006 את הלחם\u0005].\u0006 \u0003כי מטאי לגביה, שואי נפשאי כמאן דשקילי מיניה, כי היכי\u0004 \u0005[כשהגעתי אליו, עשיתי עצמי כאילו לקחתי ממנו, כדי]\u0006 ש\u0003לא ליכסיף\u0004 \u0005[יתבייש].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003מצוה עבדת\u0004 \u0005[עשית].\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003שמואל ודרש\u0004 על סמך מעשה זה: אף שנאמר \u0003\"וצדקה תציל ממות\"\u0004 (משלי י, ב) \u0003ולא ממיתה משונה\u0004 בלבד מצילה הצדקה, \u0003אלא ממיתה עצמה.\u0004","\u0003ומ\u0004מעשה שאירע ל\u0003ר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 אפשר להסיק ש\u0003אין מזל לישראל.\u0004 ש\u0003ר' עקיבא הויא ליה ברתא\u0004 \u0005[היתה לו בת],\u0006 \u0003אמרי ליה כלדאי\u0004 \u0005[אמרו לו החוזים בכוכבים]:\u0006 \u0003ההוא יומא דעיילה לבי גננא, טריק לה חיויא, ומיתא\u0004 \u0005[באותו יום שתיכנס לחופה, יכיש אותה הנחש, ותמות].\u0006 \u0003הוה, דאיגא אמילתא טובא\u0004 \u0005[היתה דואגת לדבר הרבה].\u0006 \u0003ההוא יומא שקלתא למכבנתא, דצתא בגודא, איתרמי איתיב בעיניה דחיויא\u0004 \u0005[באותו יום\u0006 של חתונתה \u0005לקחה סיכה\u0006 מראשה, \u0005נעצה\u0006 בחור \u0005שבכותל\u0006 לשמירה, ו\u0005נזדמן שנכנסה\u0006 הסיכה \u0005בעינו של הנחש].\u0006 \u0003לצפרא כי קא שקלה לה, הוה קא סריך ואתי חיויא בתרה\u0004 \u0005[בבוקר כשהוציאה\u0006 את סיכתה, \u0005היה נמשך ובא הנחש אחריה].\u0006","\u0003אמר לה אבוה\u0004 \u0005[אביה],\u0006 ר' עקיבא: \u0003מאי עבדת\u0004 \u0005[מה עשית]\u0006 שזכית להנצל מן הנחש? סיפרה לו: \u0003בפניא אתא עניא, קרא אבבא והוו טרידי כולי עלמא בסעודתא, וליכא דשמעיה\u0004 \u0005[בערב בא עני, ודפק על הדלת והיו טרודים הכל בסעודה, ולא היה\u0006 מי \u0005שישמע אותו].\u0006 \u0003קאימנא, שקלתי לריסתנאי דיהבית לי, יהבתיה ניהליה\u0004 \u0005[עמדתי, לקחתי את מנתי שנתת לי,\u0006 ו\u0005נתתי אותה לו].\u0006 \u0003אמר לה: מצוה עבדת\u0004 \u0005[עשית]\u0006 ובשכרה ניצלת. \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003ר' עקיבא ודרש:\u0004 מה שנאמר \u0003\"וצדקה תציל ממות\"\u0004 הרי זה \u0003לא ממיתה משונה אלא ממיתה עצמה.\u0004","\u0003ומ\u0004מעשה שאירע ל\u0003רב נחמן בר יצחק\u0004 יש להסיק \u0003נמי\u0004 \u0005[גם כן]\u0006 ש\u0003אין מזל לישראל. דאימיה\u0004 \u0005[שאמו]\u0006 של \u0003רב נחמן בר יצחק אמרי לה כלדאי\u0004 \u0005[אמרו לה החוזים בכוכבים]:\u0006 \u0003בריך גנבא הוה\u0004 \u0005[בנך גנב יהיה].\u0006 \u0003לא שבקתיה גלויי רישיה\u0004 \u0005[הניחתו לגלות ראשו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 לבנה: \u0003כסי רישיך, כי היכי דתיהוי עלך אימתא דשמיא, ובעי רחמי\u0004 \u0005[כסה ראשך, כדי שתהיה עליך יראת שמים, ובקש רחמים].\u0006 \u0003לא הוה ידע אמאי קאמרה ליה\u0004 \u0005[היה יודע מדוע אומרת לו]\u0006 כך. \u0003יומא חד יתיב קא גריס תותי דיקלא\u0004 \u0005[יום אחד היה יושב ולומד תחת דקל]\u0006 שהיה שייך לאחרים, \u0003נפל גלימא מעילויה רישיה\u0004 \u0005[הגלימה מעל ראשו],\u0006 \u0003דלי עיניה חזא לדיקלא\u0004 \u0005[הרים\u0006 את \u0005עיניו\u0006 ו\u0005ראה את הדקל],\u0006 \u0003אלמיה יצריה, סליק, פסקיה לקיבורא בשיניה\u0004 \u0005[תקפו יצרו,\u0006 ו\u0005עלה, וחתך את צרור התמרים בשיניו].\u0006 נמצא שאמנם היה בו יצר זה של גניבה מטבעו ובכל זאת אפשר להתגבר על היצר על ידי חינוך ותפילה.","\u0003מחתכין\u0004 בשבת \u0003את הדלועין\u0004 שנתלשו מבעוד יום \u0003לפני הבהמה, ואת הנבלה\u0004 שמתה בשבת \u0003לפני הכלבים\u0004 בשבת. \u0003ר' יהודה אומר: אם לא היתה נבלה מערב שבת\u0004 — \u0003אסורה\u0004 בחיתוך והזזה \u0003לפי שאינה מן המוכן.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדיני מוקצה בשבת. \u0003(ער\"ל שח\"ז\u0004 הוא \u0003סימן\u0004 להלכות שתילמדנה להלן\u0003). אמר עולא: הלכה כר' יהודה\u0004 הסובר שיש דין מוקצה בשבת, \u0003ושמואל אמר: הלכה כר' שמעון,\u0004","\u0003ואף רב סבר\u0004 \u0005[סבור]\u0006 ש\u0003הלכה כר' יהודה.\u0004 ומהיכן אתה למד זאת? \u0003מדכרכי דזוזי\u0004 \u0005[ממה ש\u0006שנינו בענין \u0005המחצלות שבספינות]\u0006 ש\u0003רב אסר\u0004 לטלטלן בשבת משום מוקצה, \u0003ושמואל שרי\u0004 \u0005[התיר].\u0006 \u0003ואף לוי סבר\u0004 \u0005[סבור]\u0006 ש\u0003הלכה כר' יהודה. כי הא\u0004 \u0005[כמו\u0006 \u0003זה]\u0004 ש\u0003לוי כי הוו מייתי טריפתא לקמיה ביומא טבא\u0004 \u0005[כאשר היו מביאים טריפה לפניו ביום טוב]\u0006 \u0003לא הוה חזי לה\u0004 \u0005[לא היה רואה,\u0006 בודק \u0005אותה]\u0006 \u0003אלא כי יתיב אקילקליתא\u0004 \u0005[כאשר היה יושב על האשפה].\u0006 \u0003דאמר\u0004 \u0005[שהיה אומר]:\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לא מתכשרא\u0004 \u0005[\u0006תימצא \u0005כשרה],\u0006 \u0003ואפילו לכלבים לא חזיא\u0004 \u0005[אינה ראויה],\u0006 ולכן אם יטריפנה לא יוכלו להזיזה משם. הרי שפסק כר' יהודה שנבילה שלא הוכנה מבעוד יום אסורה בטלטול.","\u0003ושמואל אמר: הלכה כר' שמעון\u0004 הסובר שאין דין מוקצה בשבת, \u0003ואף זעירי סבר\u0004 \u0005[סבור]\u0006 ש\u0003הלכה כר' שמעון. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בהמה שמתה\u0004 בשבת — \u0003לא יזיזנה\u0004 בשבת \u0003ממקומה, ותרגמא\u0004 \u0005[והסבירה]\u0006 \u0003זעירי:\u0004 לא אסרו אלא \u0003בבהמת קדשים,\u0004 שמפני כבוד הקדשים אסור לתת אותה לכלבים, ואם מתה — מוקצה היא מכל שימוש. \u0003אבל בחולין\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005]\u0006 להזיזה ולהשתמש בה, לפי שאין בה דין מוקצה. \u0003ואף ר' יוחנן אמר\u0004 ש\u0003הלכה כר' שמעון.\u0004 ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן: הלכה כסתם משנה, ותנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003אין מבקעין\u0004 בשבת \u0003עצים מן הקורות\u0004 הסדורות לצורך בנין, \u0003ולא מן הקורה שנשברה ביום טוב.\u0004 והרי סתם משנה כשיטת ר' יהודה! ומשיבים: \u0003ר' יוחנן,\u0004 הדין \u0003ההוא\u0004 שאמר באותה משנה — \u0003כ\u0004שיטת \u0003ר' יוסי בר יהודה מתני לה\u0004 \u0005[שנה אותה],\u0006 ודעת יחיד היא. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ששנינו: \u0003מתחילין\u0004 להסיק ביום טוב \u0003בערימת התבן, אבל לא בעצים שבמוקצה\u0004 (החצר שמאחורי הבית), משום שהם מוכנים לצורך אחר, והרי סתם משנה שיש דין מוקצה בשבת, וכדעת ר' יהודה! ומשיבים: \u0003התם בארזי ואשוחי\u0004 \u0005[שם\u0006 מדובר \u0005בארזים ואשוחים],\u0006 ש\u0003מוקצה מחמת חסרון כיס,\u0004 ובמוקצה זה, \u0003אפילו ר' שמעון מודה.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו במשנה: \u0003אין משקין\u0004 מים לפני השחיטה, כדי שיהיה נוח להפשיטן מעורן \u0003ושוחטין את\u0004 הבהמות \u0003המדבריות,\u0004 שהן הבהמות הרועות בשדה במשך כל הזמן. כי מאחר שאין אנשים מטפלים בהן כרגיל נחשבות הן למוקצה, ואין להשתמש בהן. \u0003אבל משקין ושוחטין את הבייתות\u0004 (בהמות הבית). נמצא שסתם משנה כר' יהודה!","ומשיבים: \u0003ר' יוחנן סתמא אחרינא אשכח\u0004 \u0005[סתם\u0006 משנה \u0005אחר מצא]\u0006 שהיא כשיטת ר' שמעון. שכן שנינו: \u0003בית שמאי אומרים: מגביהין\u0004 בשבת \u0003מעל השלחן עצמות וקליפין\u0004 (קליפות), \u0003ובית הלל אומרים: מסלק את הטבלה כולה\u0004 מעל השולחן \u0003ומנערה,\u0004 אבל לא ייגע במוקצה. \u0003ואמר רב נחמן\u0004 כי יש להפוך את השיטות במשנה זו, ו\u0003אנו אין לנו\u0004 ללמוד \u0003אלא\u0004 ששיטת \u0003בית שמאי כ\u0004שיטת \u0003ר' יהודה, ו\u0004שיטת \u0003בית הלל כ\u0004שיטת \u0003ר' שמעון.\u0004 נמצא כי שיטת בית הלל שהלכה כמותה מכוונת לשיטת ר' שמעון.","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בדבר זה, \u0003רב אחא ורבינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: בכל\u0004 דיני \u0003השבת כולה\u0004 כאשר נחלקו תנאים בדיניה ור' שמעון הוא אחד מן החולקים, \u0003הלכה כ\u0004שיטת \u0003ר' שמעון, לבר\u0004 \u0005[מחוץ]\u0006 \u0003מ\u0004בענין \u0003מוקצה מחמת מיאוס, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 — טלטול \u0003נר ישן\u0004 שמחמת מיאוס אין מטלטלים אותו שלא כדעת ר' שמעון. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: במוקצה מחמת מיאוס נמי\u0004 \u0005[גם כן]\u0006 \u0003הלכה כ\u0004שיטת \u0003ר' שמעון, לבר\u0004 \u0005[מחוץ]\u0006 \u0003מ\u0004בענין \u0003מוקצה מחמת איסור, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 — טלטול \u0003נר שהדליקו בה באותה שבת, אבל\u0004 ב\u0003מוקצה מחמת חסרון כיס, אפילו ר' שמעון מודה\u0004 שמוקצה הוא ואסור בטלטול. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 לשיטתו: \u0003כל הכלים ניטלין בשבת, חוץ ממסר\u0004 (משור) \u0003הגדול ויתד\u0004 (להב) \u0003של מחרישה\u0004 שהם מוקצים משום שבעליהם מקפידים עליהם שלא יפגמו.","האב או הבעל \u0003מפירין\u0004 את ה\u0003נדרים\u0004 של הבת או \u0003האשה בשבת, ונשאלין\u0004 אצל החכם \u0003ל\u0004התיר \u0003נדרים שהן לצורך השבת,\u0004 שאם לא יותרו לו, לא יוכל לענג את השבת כראוי. \u0003ופוקקין\u0004 בשבת \u0003את המאור\u0004 (החלון), \u0003ומודדין את המטלית\u0004 אם יש בה כשיעור לקבל טומאה, \u0003ומודדין את המקוה\u0004 אם יש בו כשיעור לטבול בו. \u0003ומעשה בימי אביו של ר' צדוק ובימי אבא שאול בן בטנית, שפקקו את המאור בטפיח\u0004 (כלי חרס), \u0003וקשרו את המקידה\u0004 (שבר חרס) בקשר שאינו של קיימא \u0003בגמי\u0004 (קנה קש ארוך) כדי \u0003לידע אם יש בגיגית\u0004 חלל כדי \u0003פותח טפח אם לאו\u0004 \u0005[לא],\u0006 \u0003ומדבריהם\u0004 ומעשיהם \u0003למדנו, שפוקקין ומודדין וקושרין בשבת.\u0004","שנינו במשנה שמפירים נדרים בשבת, ונשאלים לנדרים שהם לצורך השבת. ולהבנת דברי המשנה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003הפרה\u0004 של נדרים בשבת האם הותרה \u0003בין לצורך\u0004 שבת \u0003ובין שלא לצורך, ושאלה לצורך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 התירו להישאל בשבת, \u0003שלא לצורך\u0004 — \u0003לא\u0004 התירו להישאל בשבת. \u0003ומשום הכי קפלגינהו מהדדי\u0004 \u0005[ומשום כך חילקם\u0006 התנא \u0005זה מזה],\u0006","\u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003הפרה נמי\u0004 \u0005[גם כן]\u0006 אם היא \u0003לצורך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 התירוה בשבת, \u0003שלא לצורך\u0004 — \u0003לא, והא דקא פליג להו מהדדי\u0004 \u0005[וזה שהוא מחלק אותם זה מזה]\u0006 הרי זה \u0003משום\u0004 שלצורך \u0003הפרה אין צריך בית דין,\u0004 אלא מפר הבעל או האב מעצמו, \u0003ושאלה צריכה בית דין?\u0004","כדי לפתור בעיה זו \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003זוטי דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפא: מפירין נדרים בשבת לצורך השבת.\u0004 ומכאן נדייק: \u0003לצורך השבת\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא לצורך השבת\u0004 — \u0003לא.\u0004","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 נאמרה על אותו נושא, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003\"לצורך\"\u0004 ששנינו \u0003אתרוייהו קתני\u0004 \u0005[על שניהם שנה]\u0006 ואף הפרה הותרה דווקא כשהיא לצורך, \u0003ו\u0004אולם \u0003שלא לצורך\u0004 — \u0003לא\u0004 הותרה, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הפרת נדרים מעת לעת,\u0004 ולכן אינו חייב להפר את נדרי אשתו ביום השבת דווקא אם אינו לצורך השבת, ויכול להמתין עד סוף היממה, שיהא זה כבר אחר השבת ויפר לה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \u0003\"לצורך\"\u0004 — הכוונה היא לגבי \u0003שאלה\u0004 על התרת נדרים \u0003הוא דקתני\u0004 \u0005[ששנה],\u0006 \u0003אבל הפרת נדרים\u0004 יכולה שתיעשה בשבת \u0003אפילו שלא לצורך, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הפרת נדרים כל היום,\u0004 שאם לא יפר באותו יום לא יוכל עוד להפר לעולם, ולכן התירו לו לעשות זאת אפילו בשבת.","כדי לפתור בעיה זו \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 החכם \u0003זוטי דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפא: מפירין נדרים בשבת לצורך השבת.\u0004 ונדייק: \u0003לצורך השבת\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא לצורך השבת\u0004 — \u0003לא, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הפרת נדרים מעת לעת.\u0004","\u0003אמר רב אשי: והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003הפרת נדרים כל היום, ויש בדבר להקל ולהחמיר,\u0004 כלומר, להוסיף ולגרוע בזמן. \u0003כיצד? נדרה\u0004 אשה ב\u0003לילי שבת\u0004 — \u0003מיפר\u0004 ב\u0003לילי שבת ו\u0004ב\u0003יום השבת עד שתחשך.\u0004 ואולם אם \u0003נדרה\u0004 בעוד יום \u0003עם חשכה\u0004 (סמוך לחשיכה) — \u0003מיפר עד שלא תחשך, שאם לא הפר משחשכה,\u0004 שוב \u0003אינו יכול להפר,\u0004 לפי שכבר עבר היום. ומשיבים שהסבר זה \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 ובה הוא תלוי, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הפרת נדרים כל היום. ר' יוסי בר יהודה ור' אלעזר בר' שמעון אמרו: מעת לעת.\u0004","\u0003ו\u0004עוד שנינו במשנה כי \u0003נשאלים לנדרים\u0004 בשבת ומתירים אותם. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם היתר זה רק \u0003כשלא היה לו פנאי\u0004 לפני השבת להתיר את הנדר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יכול להישאל על נדרו בשבת \u0003אפילו היה לו פנאי\u0004 להישאל עליו עוד לפני השבת? \u0003תא שמע\u0004 \u0005בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו \u0003דאזדקיקו ליה רבנן\u0004 \u0005[שהזדקקו,\u0006 טפלו, \u0005בו חכמים]\u0006 ב\u0003רב זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב זירא ושרו ליה נדריה, ואף על גב דהוה ליה\u0004 \u0005[והתירו לו\u0006 את \u0005נדרו, אף על פי שהיה לו]\u0006 \u0003פנאי\u0004 לפני השבת.","במשנה סופר מעשה \u0003שפקקו את המאור בטפיח וקשרו את המקידה בגמי. אמר רב יהודה\u0004 שכך \u0003אמר רב,\u0004 כדי להבין משום מה עשו זאת יש להסביר שכך היה המעשה: \u0003הילקטי\u0004 \u0005[סימטה]\u0006 \u0003קטנה היתה בין שני בתים, וטומאה\u0004 של מת \u0003היתה שם\u0004 בסימטה"],["\u0003וגיגית סדוקה\u0004 היתה \u0003מונחת על גבן\u0004 של הבתים. ואילו היתה הגיגית סתומה היתה משמשת כאהל על בשר המת, ומטמאה כל מה שבסמטה, ואף מטמאה דרך החלונות את שני הבתים שלידה. ואולם, כיון שהיה סדק והיה בשר המת מונח בדיוק מתחתיו, ואם היה הסדק גדול עד כדי טפח (\"פותח טפח\") אין הטומאה פושטת בכל הסימטה ובבתים, אלא רק מעל לאותו סדק בלבד, \u0003ו\u0004לכן \u0003פקקו את המאור\u0004 (החלון) של בית \u0003בטפיח\u0004 (בכד חרס) שלא תכנס הטומאה בו, \u0003וקשרו את המקידה בגמי\u0004 (קנה קש ארוך) והכניסו את המקידה בתוך סדק הגיגית כדי לברר ו\u0003לידע\u0004 (לדעת) \u0003אם יש שם ב\u0004סדק ה\u0003גיגית פותח טפח אם לאו\u0004 \u0005[לא].\u0006","שנינו במשנה \u0003ומדבריהם למדנו שפוקקין ומודדין וקושרין בשבת.\u0004 מסופר: \u0003עולא איקלע לבי ריש גלותא\u0004 \u0005[לבית ראש הגולה].\u0006 \u0003חזייה\u0004 \u0005[ראהו]\u0006 \u0003לרבה בר רב הונא דיתיב באוונא דמיא וקא משח ליה\u0004 \u0005[שיושב באמבטיה של מים ומודד אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא לרבה בר רב הונא: \u0003אימר דאמרי רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 שמותרת המדידה בשבת, רק ב\u0003מדידה\u0004 של \u0003מצוה\u0004 אמרו, ואולם בזו \u0003דלאו\u0004 \u0005[שאינה]\u0006 של \u0003מצוה מי אמור\u0004 \u0005[האם אמרו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא: אינני מודד ממש אלא \u0003מתעסק בעלמא אנא\u0004 \u0005[בלבד אני],\u0006 אבל אין כוונתי כלל למדוד דבר, ובאופן זה אין בדבר כל איסור.",""]]};
